// Deferred-commit delete with a Gmail-style undo toast. The row hides immediately and the
// actual api.del only fires once the 6s window elapses — Undo means nothing was ever deleted,
// no email sent, no round-trip. Replaces a confirm modal, which asks BEFORE and can't take it
// back AFTER. Returns { pending, del }: filter your list by `!pending.has(id)`, and call
// The background-image for the preview pane.
//
// `var(--page-glows)` alone would be wrong: themeCss only emits that property when a glow
// list is CONFIGURED, and an unresolved var() with no fallback makes background-image
// `none`. The preview would then show a bare colour for every unconfigured theme while the
// real page shows three glows — a preview that lies in the default case, which is the case
// most people look at it in.
function previewGlowCss(f, mode) {
  // Explicit mode wins (the side-by-side preview asks for light AND dark at once); falling
  // back to the admin's own theme keeps any older single-mode caller correct.
  const active = mode || (document.documentElement.getAttribute('data-theme') === 'dark' ? 'dark' : 'light');
  const list = Array.isArray(f?.[active]?.glows) ? f[active].glows : DEFAULT_GLOWS(active);
  // The top wash sits UNDER the glows, exactly as it does on the real page. It used to be a
  // literal `#fffdf9` in index.css — the one part of the light background no theme reached —
  // so leaving it out of the preview would hide the very change that made it themeable.
  const wash = `linear-gradient(180deg, var(--page-top, ${active === 'light' ? '#fffdf9' : 'transparent'}) 0%, var(--bg) 40%)`;
  if (!list.length) return wash; // an explicit empty list IS a flat background — but the wash stays
  return list
    .map((g) => `radial-gradient(${g.w ?? 55}% ${g.h ?? 55}% at ${g.x ?? 50}% ${g.y ?? 0}%, ${g.color}, transparent ${g.fade ?? 60}%)`)
    .concat(wash)
    .join(',');
}

// The shipped glow stack per mode, as data — the starting point when an admin takes the
// background over. These mirror the fallbacks in index.css; they are not read from it,
// so if the CSS stack changes these want changing with it.
const DEFAULT_GLOWS = (mode) => (mode === 'light'
  ? [
    { color: 'rgba(249,115,22,.14)', w: 58, h: 42, x: 80, y: -12, fade: 60 },
    { color: 'rgba(245,158,11,.12)', w: 46, h: 40, x: -6, y: 6, fade: 56 },
    { color: 'rgba(249,115,22,.07)', w: 90, h: 46, x: 50, y: 118, fade: 62 },
  ]
  : [
    { color: 'rgba(249,115,22,.16)', w: 60, h: 52, x: 82, y: -14, fade: 56 },
    { color: 'rgba(245,158,11,.12)', w: 48, h: 46, x: -8, y: 4, fade: 56 },
    { color: 'rgba(245,158,11,.07)', w: 130, h: 90, x: 50, y: 128, fade: 60 },
  ]);

// <input type="color"> only speaks #rrggbb, but a glow is usually an rgba() with the alpha
// carrying most of the effect. The swatch shows the closest hex so the picker is usable;
// the text field beside it stays the source of truth for anything with transparency.
function hexOf(v) {
  const m = String(v || '').match(/^rgba?\(\s*(\d+)[,\s]+(\d+)[,\s]+(\d+)/i);
  if (m) return '#' + m.slice(1, 4).map((n) => Number(n).toString(16).padStart(2, '0')).join('');
  return /^#[0-9a-f]{6}$/i.test(String(v || '')) ? v : '#f97316';
}

/* ─────────────────────────  Admin  ───────────────────────── */
// What the sidebar's search knows about each screen beyond its label: the admin guide's
// title, body and bullet points (EN + FR) and the per-screen reference, so "Ko-fi" finds
// Funding and "72 hours" finds Hosting settings. Built once — the guide is static.
const ADMIN_SEARCH_KEYWORDS = (() => {
  const out = {};
  const add = (id, ...parts) => { out[id] = `${out[id] || ''} ${parts.filter(Boolean).join(' ')}`.slice(0, 4000); };
  for (const sec of GUIDE) for (const g of sec.items || []) {
    add(g.id, g.title?.en, g.title?.fr, g.body?.en, g.body?.fr, ...(g.points || []).flatMap((p) => [p.en, p.fr]));
  }
  for (const [id, screens] of Object.entries(ADMIN_SCREENS_REF)) {
    for (const sc of screens) add(sc.id, sc.name?.en, sc.name?.fr, sc.what?.en, sc.what?.fr, ...(sc.controls || []).flatMap((c) => [c.label?.en, c.label?.fr]));
    add(id, ...screens.flatMap((sc) => [sc.name?.en, sc.name?.fr]));
  }
  return out;
})();

export function Admin() {
  const { user } = useAuth(); const dialog = useDialog(); const toast = useToast(); const { t } = useI18n();
  const [modQ, setModQ] = useState(''); const [modQApplied, setModQApplied] = useState('');
  const [modSort, setModSort] = useState('oldest'); const [modKind, setModKind] = useState(''); const [modType, setModType] = useState(''); const [modStatus, setModStatus] = useState('PENDING');
  const subs = useAsync(() => api.get(`/mod/submissions?q=${encodeURIComponent(modQApplied)}&sort=${modSort}&kind=${modKind}&type=${modType}&status=${modStatus}`), [modQApplied, modSort, modKind, modType, modStatus]);
  // Moderating notifies the author (and suspend blocks resubmission), so every verdict gets
  // an undo window. The API call is DEFERRED, not reversed: the card hides immediately, and
  // nothing is sent — no mail, no state change — unless the window elapses. Undo means the
  // author never knew.
  const [modPending, setModPending] = useState(new Set()); // ids hidden during their window
  const unhideSub = (id) => setModPending((s) => { const n = new Set(s); n.delete(id); return n; });
  const modVerdict = (s, url, body, msg) => {
    setModPending((p) => new Set(p).add(s.id));
    setReview((r) => (r?.id === s.id ? null : r)); // close the review modal if it's this one
    toast.action({
      tone: 'success', duration: 6000, cancelLabel: t('common.undo', 'Undo'), msg,
      onCommit: async () => {
        try { await api.post(url, body); subs.reload(); }
        catch { toast.error(t('mod.failed', 'Failed.')); }
        finally { unhideSub(s.id); } // reload() drops it from the list when it really applied
      },
      onCancel: () => unhideSub(s.id),
    });
  };
  const approve = (s) => modVerdict(s, `/mod/submissions/${s.id}/approve`, undefined, t('mod.approved', 'Approved "{name}".').replace('{name}', s.item?.name));
  const reject = async (s) => {
    const reason = await dialog.prompt({ title: t('mod.reject.title', 'Reject submission'), label: t('mod.reject.label', 'Reason (sent to the author)'), placeholder: t('mod.reject.ph', 'Why is this rejected?'), okLabel: t('mod.reject.ok', 'Reject'), danger: true });
    if (!reason) return;
    modVerdict(s, `/mod/submissions/${s.id}/reject`, { reason }, t('mod.rejected', 'Rejected and author notified.'));
  };
  // Suspend (ADMIN): harsher than reject — the owner can't resubmit. Reversible via approve/reject.
  const suspend = async (s) => {
    const reason = await dialog.prompt({ title: t('mod.suspend.title', 'Suspend submission'), label: t('mod.suspend.label', 'Reason (sent to the author)'), placeholder: t('mod.suspend.ph', "Why is this suspended? The author can't resubmit."), okLabel: t('mod.suspend.ok', 'Suspend'), danger: true });
    if (!reason) return;
    modVerdict(s, `/mod/submissions/${s.id}/suspend`, { reason }, t('mod.suspended2', 'Suspended, the author can no longer resubmit.'));
  };
  const isAdmin = user?.role === 'ADMIN' || user?.role === 'SUPERADMIN';
  const isSuperAdmin = user?.role === 'SUPERADMIN';
  const isMod = isAdmin || user?.role === 'MOD';
  // A tab is visible if the user is an admin, has the capability granted (individually OR
  // via a custom role — effectiveCaps), or is a MOD for the capabilities MODs hold by
  // default (users/repos) — mirrors the server's requireCap.
  const caps = effectiveCaps(user);
  const can = (c) => isAdmin || caps.includes(c) || (isMod && ['manage_users', 'manage_repos'].includes(c));
  // Per-project edit grants (ProjectPermission) let a non-admin reach the project tabs even
  // with no capability — scoped to what they were granted (the tab itself scopes further).
  const pg = user?.projectGrants || {};
  const canShowcaseTab = can('manage_showcase') || !!pg.allShowcase || (pg.showcaseIds?.length > 0);
  const canProjectsTab = can('manage_projects') || (pg.projectKeys?.length > 0);
  const queue = (subs.data?.submissions || []).filter((s) => !modPending.has(s.id));
  // What is waiting on a human, refreshed on a slow poll so a badge appearing is the first
  // thing you notice rather than something you find by opening every tab. The server filters
  // each queue by capability, so a count here is always something this user can act on.
  const pending = useAsync(() => api.get('/admin/pending'), []);
  // useAsync builds `reload` fresh on every render, so depending on it would clear and
  // recreate this interval each time — the 60s timer would restart on every keystroke
  // elsewhere in the shell and, in practice, never mature. Hold the latest reload in a ref
  // and set the interval up exactly once.
  const pendingReload = useRef(pending.reload);
  pendingReload.current = pending.reload;
  useEffect(() => { const id = setInterval(() => pendingReload.current?.(), 60_000); return () => clearInterval(id); }, []);
  // …and at once when a screen says so (an alert marked as seen, a queue item dismissed):
  // a badge that waits for the next minute after you cleared it reads as "did not work".
  useEffect(() => { const h = () => pendingReload.current?.(); window.addEventListener('bcw:pending-changed', h); return () => window.removeEventListener('bcw:pending-changed', h); }, []);
  const pc = pending.data?.counts || {};
  const [review, setReview] = useState(null);
  // The nav, grouped.
  //
  // Forty-five rows at one level meant "Errors" and "Site theme" looked equally important and
  // neither could be found. A tab may now carry `sub`, which SideDash renders as one sidebar
  // row plus a sub-tab strip above the content — so the sidebar answers "what kind of thing
  // am I doing" and the strip answers "which one".
  //
  // Leaf ids are untouched on purpose: every deep link, every badge target and every
  // `s === 'x'` branch below keeps working. This moves rows in the nav, not pages.
  //
  // Headings say what the section is FOR rather than naming a noun-pile: a moderator scanning
  // for where to answer a report is helped more by "Waiting on you" than by "Moderation".
  const raw = [
    { heading: t('adm.h.help', 'Reference') },
    isMod && { id: 'guide', label: t('adm.tab.guide', 'Admin guide'), icon: BookOpen },
    // Admin-only, like its routes (requireRole('ADMIN') in demo.mjs, not a capability).
    isAdmin && { id: 'demo', label: t('adm.tab.demo', 'Demo mode'), icon: FlaskConical },

    { heading: t('adm.h.queues', 'Waiting on you') },
    // No badge, deliberately. This tab is a DIGEST of the six queues below, and every one of
    // them carries its own badge (Submissions, Reports, Messages, Sanctions, Commissions,
    // Performance). Summing them here counted every waiting item a second time — the sidebar
    // read 12 when six things were waiting, and the arithmetic got worse the more queues were
    // added. The numbers belong on the tabs where the work is actually done; this tab answers
    // "what is waiting", not "how much".
    isMod && { id: 'needs', label: t('adm.tab.needs', 'Needs attention'), icon: BellIcon },
    // Beside the queues, because it is one: the difference is that the rows on this one
    // have somebody's name on them.
    // Not isMod alone: view_tasks / manage_tasks / manage_teams can be granted to a USER, and
    // the server lets that USER read and dispatch the board -- a tab hidden from them made the
    // grant look broken. The server still decides what each row shows.
    (isMod || can('view_tasks') || can('manage_tasks') || can('manage_teams')) && { id: 'tasks', label: t('adm.tab.tasks', 'Tasks'), icon: TASKS_TAB_ICON },
    isMod && { id: 'moderation', label: t('adm.tab.moderation', 'Moderation'), icon: ShieldAlert,
      sub: [
        { id: 'moderation', label: t('adm.tab.submissions', 'Submissions'), icon: Inbox, badge: queue.length || undefined },
        can('manage_reports') && { id: 'reports', label: t('adm.tab.reports', 'Reports'), icon: AlertTriangle, badge: pc.reports || undefined },
        can('manage_reports') && { id: 'rights', label: t('adm.tab.rights', 'Rights notices'), icon: Scale, badge: pc.rights || undefined },
        can('manage_reports') && { id: 'feedback', label: t('adm.tab.feedback', 'Feedback & crashes'), icon: BugIcon, badge: pc.feedback || undefined },
        can('manage_reports') && { id: 'lookalikes', label: t('adm.tab.lookalikes', 'Lookalike pictures'), icon: ImageIcon },
        { id: 'messages', label: t('adm.tab.messages', 'Messages'), icon: Mail, badge: pc.contact || undefined },
        can('manage_legal') && { id: 'legal', label: t('adm.tab.legal', 'Legal'), icon: FileText },
        can('manage_sanctions') && { id: 'sanctions', label: t('adm.tab.sanctions', 'Sanctions'), icon: Gavel, badge: pc.contests || undefined },
      ].filter(Boolean) },

    { heading: t('adm.h.people', 'People') },
    can('manage_users') && { id: 'users', label: t('adm.tab.users', 'Accounts'), icon: Users,
      sub: [
        { id: 'users', label: t('adm.tab.users2', 'All accounts'), icon: Users },
        // Same gate as its routes (manage_users): the log's one personal field is an address.
        { id: 'maillog', label: t('adm.tab.maillog', 'Sent e-mails'), icon: Send },
        isAdmin && { id: 'onboarding', label: t('adm.tab.onboarding', 'Onboarding'), icon: Rocket },
        isAdmin && { id: 'access', label: t('adm.tab.access', 'Roles & permissions'), icon: Shield },
        // The two "who did what" screens, together: the audit chain and the whole-site
        // history read the same way and were two sections apart.
        isAdmin && { id: 'security', label: t('adm.tab.security', 'Security log'), icon: Lock },
        can('manage_history') && { id: 'history', label: t('adm.tab.history', 'Site history'), icon: History },
      ].filter(Boolean) },

    { heading: t('adm.h.content', 'What the site shows') },
    canProjectsTab && { id: 'projects', label: t('adm.tab.projects', 'Projects'), icon: Boxes,
      sub: [
        { id: 'projects', label: t('adm.tab.projects2', 'Better* projects'), icon: Boxes },
        // "Other projects" had a tab of its own next to Projects, which read as a separate
        // subsystem rather than as the second kind of project it is.
        canShowcaseTab && { id: 'showcase', label: t('adm.tab.showcase', 'Other projects'), icon: Sparkles },
        isAdmin && { id: 'marketplace', label: t('adm.tab.marketplace', 'Marketplace'), icon: ShoppingBag },
      ].filter(Boolean) },
    (isAdmin || can('manage_catalogs') || can('manage_assets')) && { id: 'catalogs', label: t('adm.tab.catalogs', 'Catalogs'), icon: Boxes,
      sub: [
        // The parent used to be isAdmin, so a grantee of either child could not reach it.
        isAdmin && { id: 'catalogs', label: t('adm.tab.catalogs2', 'Official'), icon: Boxes },
        can('manage_catalogs') && { id: 'commcatalogs', label: t('adm.tab.commcatalogs', 'Community'), icon: Layers },
        can('manage_assets') && { id: 'assets', label: t('adm.tab.assets', 'Downloads & assets'), icon: Download },
      ].filter(Boolean) },
    can('manage_announcements') && { id: 'announcements', label: t('adm.tab.editorial', 'Writing & notices'), icon: Newspaper,
      sub: [
        { id: 'announcements', label: t('adm.tab.announcements', 'Announcements'), icon: BellIcon },
        can('manage_faq') && { id: 'faq', label: t('adm.tab.faq', 'FAQ'), icon: HelpCircle },
        can('manage_newsletter') && { id: 'newsletter', label: t('adm.tab.newsletter', 'Newsletter'), icon: Mail },
        isAdmin && { id: 'mail', label: t('adm.tab.mail', 'Mail delivery'), icon: Send },
        isAdmin && { id: 'reviews', label: t('adm.tab.reviews', 'Reviews'), icon: Star },
        can('manage_polls') && { id: 'polls', label: t('adm.tab.polls', 'Polls'), icon: BarChart3 },
        can('manage_announcements') && { id: 'reactions', label: t('adm.tab.reactions', 'Reader feedback'), icon: ThumbsUp },
      ].filter(Boolean) },
    isAdmin && { id: 'badges', label: t('adm.tab.badges', 'Badges'), icon: BadgeCheck },

    { heading: t('adm.h.repos', 'Hosting') },
    can('manage_repos') && { id: 'repos', label: t('adm.tab.repos', 'Repos & pools'), icon: Database,
      sub: [
        { id: 'repos', label: t('adm.tab.repos2', 'Server repos'), icon: Server },
        { id: 'pools', label: t('adm.tab.pools', 'Storage pools'), icon: HardDrive },
        can('manage_hosting') && { id: 'entityhosting', label: t('adm.tab.entityhosting', 'Storage per blog & inbox'), icon: HardDrive },
        { id: 'transfers', label: t('adm.tab.transfers', 'Ownership'), icon: ArrowRightLeft },
        can('manage_hosting') && { id: 'hosting', label: t('adm.tab.hosting', 'Free hosting'), icon: Gift },
      ].filter(Boolean) },
    // Hosting plans stay here: they DEFINE the hosting product (sizes, speeds, what each tier
    // includes) and are edited beside the pools they size. What people paid lives in Money.
    isAdmin && { id: 'plans', label: t('adm.tab.plans2', 'Hosting plans'), icon: Layers },

    { heading: t('adm.h.money', 'Money') },
    // Money: one place for what came in, what is owed and what was given away.
    //
    // "Customers & revenue" sat under Accounts and "Pending payments" under Server repos, so
    // the question "how is the money doing" meant opening two unrelated groups. Leaf ids are
    // unchanged (?s=planusers, ?s=payments, ?s=promotions, ?s=kofi, ?s=charity keep landing),
    // and every leaf keeps the exact gate it had in its old group. Deliberately NOT here:
    // Hosting plans (the product definition, above), Marketplace (edits products attached to
    // project pages, under Projects), Commissions (a work queue with a badge, under Growth).
    (can('manage_users') || can('manage_hosting') || can('manage_promotions') || can('manage_donations')) && { id: 'money', label: t('adm.tab.money', 'Money'), icon: Wallet,
      sub: [
        // Was under Accounts, whose gate was manage_users; that is still its gate.
        can('manage_users') && { id: 'planusers', label: t('adm.tab.planusers', 'Free vs paid'), icon: Receipt },
        can('manage_hosting') && { id: 'payments', label: t('adm.tab.payments', 'Pending payments'), icon: CreditCard },
        can('manage_promotions') && { id: 'promotions', label: t('adm.tab.promotions', 'Promotions & codes'), icon: Megaphone },
        // Community Charity used to be a card at the foot of Home page; it is money that is not
        // a sale, like Ko-fi. Same capability as Ko-fi.
        can('manage_donations') && { id: 'kofi', label: t('adm.tab.kofi2', 'Ko-fi'), icon: KofiIcon },
        can('manage_donations') && { id: 'charity', label: t('adm.tab.charity', 'Community Charity'), icon: Heart },
      ].filter(Boolean) },

    { heading: t('adm.h.growth2', 'Growth') },
    can('manage_events') && { id: 'events', label: t('adm.tab.events', 'Events'), icon: PartyPopper },
    can('manage_myo') && { id: 'myo', label: t('adm.tab.myo', 'Commissions'), icon: Wand2, badge: pc.myo || undefined },

    { heading: t('adm.h.integrations', 'Integrations') },
    isAdmin && { id: 'sso', label: t('adm.tab.sso', 'SSO / OAuth'), icon: KeyRound },
    can('manage_api') && { id: 'api', label: t('adm.tab.api', 'Public API'), icon: KeyRound },
    can('manage_bot') && { id: 'bot', label: t('adm.tab.bot', 'Discord bot'), icon: Bot },

    { heading: t('adm.h.serverdata', 'The machine') },
    isAdmin && { id: 'serverperf', label: t('adm.tab.server', 'Server'), icon: ServerCog,
      sub: [
        { id: 'serverperf', label: t('adm.tab.serverperf2', 'Performance'), icon: Activity, badge: pc.alerts || undefined },
        { id: 'storage', label: t('adm.tab.storage', 'Storage'), icon: HardDrive },
        // Beside Performance rather than in its own group: the incidents on the public page are
        // the outages this screen's probes recorded, and writing the account of one is what you
        // do straight after looking at what broke.
        { id: 'statuspage', label: t('adm.tab.statuspage', 'Status page'), icon: HeartPulse },
        { id: 'serveradv', label: t('adm.tab.serveradv', 'Advanced'), icon: Wrench },
      ] },
    can('manage_analytics') && { id: 'analytics', label: t('adm.tab.analytics', 'Analytics'), icon: TrendingUp,
      sub: [
        { id: 'analytics', label: t('adm.tab.analytics2', 'Traffic'), icon: TrendingUp },
        { id: 'goals', label: t('adm.tab.goals', 'Goals'), icon: Target },
        { id: 'errors', label: t('adm.tab.errors', 'Errors'), icon: OctagonAlert },
      ] },

    { heading: t('adm.h.settings', 'How it looks & behaves') },
    isAdmin && { id: 'settings', label: t('adm.tab.settings', 'Settings'), icon: Sliders },
    isAdmin && { id: 'navui', label: t('adm.tab.chrome', 'Navigation & footer'), icon: Navigation,
      sub: [
        { id: 'navui', label: t('adm.tab.navui2', 'Topbar'), icon: Navigation },
        { id: 'footer', label: t('adm.tab.footer', 'Footer'), icon: PanelBottom },
        { id: 'homepage', label: t('adm.tab.homepage', 'Home page'), icon: LayoutGrid },
      ] },
    // Languages is its own tab so a TRANSLATOR (who is not an admin) can reach it — the whole
    // Navigation & footer group above is admin-only, and the site-string editor is exactly
    // what the translate_site capability is for.
    can('translate_site') && { id: 'languages', label: t('adm.tab.languages', 'Languages'), icon: Languages },
    // Site theme changes what EVERY visitor sees, so it sits a tier above the per-project
    // settings an ADMIN manages.
    isSuperAdmin && { id: 'sitetheme', label: t('adm.tab.sitetheme', 'Site theme'), icon: Palette },
  ].filter(Boolean);
  // Drop group headings whose whole group is hidden (no visible tab follows before the
  // next heading / the end) — so a granted non-admin sees only their sections.
  const tabs = raw.filter((it, i) => !it.heading || (raw[i + 1] && !raw[i + 1].heading));
  return (
    <SideDash icon={ShieldCheck} title={t('adm.title', 'Admin')} subtitle={t('adm.subtitle', 'Moderation, catalogs, hosting, analytics and settings.')} tabs={tabs}
      searchKeywords={ADMIN_SEARCH_KEYWORDS} remoteSearch={(q) => api.get(`/admin/search?q=${encodeURIComponent(q)}`)}>
      {(s) => (<>
        {/* The guide, from wherever you are.
            It was a tab in the sidebar and nothing else: two "Learn more" links existed on
            the whole site, both pointing at hosting settings, so the manual was something you
            had to remember to go and read. One line here puts it on every screen, pointing at
            the entry that documents THIS one, and guideEntryForTab is checked against the tab
            list by check-guide-coverage.mjs so it cannot quietly point nowhere. */}
        <GuideLink tab={s} />
        {/* While a demo runs, every admin screen says so; the demo screen has its own. */}
        {isAdmin && <DemoBanner current={s} />}
        {s === 'demo' && <AdminDemo />}
        {s === 'homepage' && <><SceneEditor /><ShowcaseEditor /><HomePageEditor /></>}
        {s === 'languages' && <><LanguagesCard /><BotI18nCard /></>}
        {s === 'moderation' && <div>
          <h2 className="font-semibold mb-3 flex items-center gap-2"><Inbox size={16} /> {t('mod.queue', 'Moderation queue')}</h2>
          <BmmInspector />
          <CodebaseMaps />
          <div className="flex flex-wrap gap-2 mb-3">
            <div className="relative flex-1 min-w-[200px]"><Search size={15} className="absolute left-3 top-1/2 -translate-y-1/2 text-[var(--faint)] pointer-events-none" />
              <Input className="!ps-9" placeholder={t('mod.search.ph', 'Search by item name, author or email…')} value={modQ} onChange={(e) => setModQ(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && setModQApplied(modQ)} /></div>
            <Button variant="primary" onClick={() => setModQApplied(modQ)}><Search size={15} /> {t('mod.search', 'Search')}</Button>
            <Dropdown value={modKind} onChange={setModKind} options={[
              { value: '', label: t('mod.allkinds', 'All kinds') }, { value: 'APP', label: t('mod.k.app', 'App') },
              { value: 'PLUGIN', label: t('mod.k.plugin', 'Plugin') }, { value: 'THEME', label: t('mod.k.theme', 'Theme') }, { value: 'PRESET', label: t('mod.k.preset', 'Preset') },
              { value: 'MODPACK', label: t('mod.k.modpack', 'Modpack') },
            ]} />
            <Dropdown value={modType} onChange={setModType} options={[
              { value: '', label: t('mod.alltypes', 'All types') }, { value: 'NEW', label: t('mod.t.new', 'New') }, { value: 'UPDATE', label: t('mod.t.update', 'Update') },
            ]} />
            <Dropdown value={modSort} onChange={setModSort} options={[
              { value: 'oldest', label: t('mod.oldest', 'Oldest first') }, { value: 'newest', label: t('mod.newest', 'Newest first') },
            ]} />
            <Dropdown value={modStatus} onChange={setModStatus} options={[
              { value: 'PENDING', label: t('mod.s.pending', 'Pending') }, { value: 'REJECTED', label: t('mod.s.rejected', 'Rejected') },
              { value: 'SUSPENDED', label: t('mod.s.suspended', 'Suspended') }, { value: 'PUBLISHED', label: t('mod.s.published', 'Published') },
            ]} />
          </div>
          {subs.loading ? <Loading /> : (queue.length ? <div className="space-y-2">
            {queue.map((sub) => { const I = KIND_ICON[sub.item?.kind] || Package; return (
              /* The four actions used to be flex children of the card row: with no shrink-0
                 they squashed against the content on a phone and their labels printed over
                 the badges. Content first, actions on their own measured row. */
              <Card key={sub.id} className="p-4">
                <div className="flex items-start gap-3">
                  <I size={18} className="text-[var(--accent-ink)] shrink-0 mt-0.5" />
                  <div className="flex-1 min-w-0">
                    <div className="font-medium truncate">{sub.item?.name} {sub.item?.version && <span className="text-xs text-[var(--faint)] font-normal">v{sub.item.version}</span>}</div>
                    <div className="text-xs text-[var(--faint)] flex items-center gap-1.5 flex-wrap">
                      <Badge>{sub.type}</Badge> <Badge tone="primary">{sub.item?.kind}</Badge>
                      {sub.status && sub.status !== 'PENDING' && <Badge tone={sub.status === 'SUSPENDED' ? 'red' : sub.status === 'REJECTED' ? 'amber' : sub.status === 'PUBLISHED' ? 'green' : ''}>{sub.status}</Badge>}
                      {sub.item?.project?.key && <span className="uppercase">{sub.item.project.key}</span>} · {sub.item?.owner?.displayName || '—'}
                      {/* Listing under an official catalogue needs the project's link. Shown on
                          the row, not discovered by clicking Approve and getting a 409 — a
                          refused button reads as broken rather than as a rule. */}
                      {sub.projectLink?.required && !sub.projectLink.ok && (
                        <Badge tone="red" title={t('mod.needlink.hint', 'The owner has not linked {why}. It can be hosted and shared privately, but not listed publicly.').replace('{why}', sub.projectLink.why || '')}>
                          <LinkIcon size={9} /> {t('mod.needlink', 'no {link} link').replace('{link}', sub.projectLink.link || 'project')}
                        </Badge>
                      )}
                      {sub.tags?.map((tg) => <Badge key={tg} tone="amber"><Tag size={9} /> {tg}</Badge>)}
                      {sub.comments?.length > 0 && <span className="flex items-center gap-1 text-[var(--faint)]"><MessageSquare size={11} /> {sub.comments.length}</span>}
                    </div>
                    {sub.reason && (sub.status === 'REJECTED' || sub.status === 'SUSPENDED') && <div className="text-[11px] text-[var(--muted)] mt-1 truncate" title={sub.reason}><b>{t('mod.reasonlabel', 'Reason')}:</b> {sub.reason}</div>}
                  </div>
                </div>
                <div className="mt-3">
                  <ActionBar actions={[
                    { key: 'review', label: t('mod.review', 'Review'), icon: Eye, onClick: () => setReview(sub) },
                    sub.status !== 'PUBLISHED' && {
                      key: 'approve', label: t('mod.approve', 'Approve'), icon: CheckCircle2, variant: 'primary',
                      // Disabled rather than hidden: a missing button leaves the moderator
                      // wondering what they are not allowed to do, where a disabled one with a
                      // reason answers it.
                      disabled: sub.projectLink?.required && !sub.projectLink.ok,
                      title: sub.projectLink?.required && !sub.projectLink.ok
                        ? t('mod.needlink.hint', 'The owner has not linked {why}. It can be hosted and shared privately, but not listed publicly.').replace('{why}', sub.projectLink.why || '')
                        : undefined,
                      onClick: () => approve(sub),
                    },
                    sub.status !== 'REJECTED' && { key: 'reject', label: t('mod.reject', 'Reject'), icon: XCircle, onClick: () => reject(sub) },
                    isAdmin && sub.status !== 'SUSPENDED' && { key: 'suspend', label: t('mod.suspend', 'Suspend'), icon: Ban, danger: true, onClick: () => suspend(sub) },
                  ].filter(Boolean)} />
                </div>
              </Card>); })}
          </div> : <EmptyState icon={CheckCircle2} title={t('mod.empty.t', 'Queue is empty')} sub={t('mod.empty.s2', 'Nothing is waiting for review. Submissions land here the moment somebody sends one.')} />)}
          {review && <SubmissionReview sub={review} onClose={() => setReview(null)} onApprove={() => { approve(review); setReview(null); }} onReject={() => { reject(review); setReview(null); }} reload={subs.reload} />}
        </div>}
        {s === 'needs' && <AdminNeedsAttention data={pending.data} loading={pending.loading} onReload={pending.reload} isAdmin={isAdmin} />}
        {s === 'tasks' && <AdminTasks />}
        {/* The new screen renders AdminThreads itself, under its policy card. */}
        {s === 'messages' && <AdminMessagesScreen />}
        {s === 'lookalikes' && <AdminMediaFlags />}
        {s === 'legal' && <AdminLegal />}
        {s === 'users' && <AdminUsers />}
        {s === 'maillog' && <AdminMailLog />}
        {s === 'onboarding' && <AdminOnboarding />}
        {s === 'planusers' && <AdminPlanUsers />}
        {s === 'access' && <AdminAccess isSuperAdmin={isSuperAdmin} />}
        {s === 'security' && <AdminSecurity />}
        {s === 'serverperf' && <AdminServerPerf />}
        {s === 'statuspage' && <AdminStatusPage />}
        {s === 'serveradv' && <AdminServerAdvanced />}
        {s === 'announcements' && <AdminAnnouncements />}
        {s === 'badges' && <AdminBadges />}
        {s === 'newsletter' && <AdminNewsletter />}
        {s === 'faq' && <AdminFaq />}
        {s === 'repos' && <AdminRepos />}
        {s === 'pools' && <AdminPools />}
        {s === 'entityhosting' && <AdminEntityHosting />}
        {s === 'transfers' && <AdminTransfers />}
        {/* Plugin/theme verification used to live here; the moderation queue now owns that
            review step, so the standalone panels were a second, diverging place to do it. */}
        {s === 'catalogs' && <AdminCatalogCreator />}
        {s === 'commcatalogs' && <AdminCatalogs />}
        {s === 'reports' && <AdminReports />}
        {s === 'rights' && <AdminRights />}
        {s === 'plans' && <AdminHostingPlans />}
        {s === 'mail' && <AdminMail />}
        {s === 'history' && <AdminHistory />}
        {s === 'hosting' && <AdminFreeHost />}
        {s === 'payments' && <AdminPendingPayments />}
        {s === 'promotions' && <><AdminCampaigns /><div className="mt-8"><AdminPromo /></div></>}
        {s === 'kofi' && <AdminKofi />}
        {s === 'charity' && <CharityAdminCard />}
        {s === 'events' && <AdminEvents />}
        {s === 'myo' && <AdminMyo />}
        {s === 'sso' && <AdminSso />}
        {s === 'api' && <AdminApi />}
        {s === 'sanctions' && <AdminSanctions />}
        {s === 'polls' && <AdminPolls />}
        {s === 'reactions' && <AdminReactions />}
        {s === 'storage' && <AdminStorage />}
        {s === 'marketplace' && <AdminMarketplace />}
        {s === 'bot' && <AdminBot />}
        {s === 'analytics' && <AdminAnalytics />}
        {s === 'errors' && <AdminErrors />}
        {s === 'feedback' && <AdminFeedbackCentre />}
        {s === 'goals' && <AdminGoals />}
        {s === 'projects' && <AdminProjects />}
        {s === 'assets' && <AdminAssets />}
        {s === 'showcase' && <AdminShowcase />}
        {s === 'reviews' && <AdminReviews />}
        {s === 'navui' && <AdminNav />}
        {s === 'footer' && <AdminFooter />}
        {s === 'guide' && <AdminGuide />}
        {s === 'settings' && <AdminSettings />}
        {s === 'sitetheme' && <AdminSiteTheme />}
      </>)}
    </SideDash>
  );
}


// The official catalogs, as catalogs — which is what they have always been on the BMM side:
// one feed URL per project+kind, each with its own payload shape. The form used to ask for
// project and kind on every single entry, which made "which catalog am I filling?" something
// you re-answered each time and never actually saw the contents of.
//
// This mirrors the community side deliberately: pick ONE catalog, see what is in it, add to
// it. The entry's type then follows from the catalog rather than being a per-entry choice
// that could quietly put a theme in the app feed.
// DERIVED, from the live project list crossed with the kinds each project publishes.
//
// Written out by hand it listed four catalogs and was missing BMM automations entirely —
// so a kind BMM has read for months, and that the submission form has offered for just as
// long, had no official catalog and no way to make one. A hand-written list is wrong the
// first time somebody adds a project or a kind, and it is wrong silently: the screen looks
// complete because it looks like a list.
//
// `kindLabel` rather than KIND_LABEL: on a BMM page a PRESET is an Automation, and calling
// it "Preset" is the wrong intuition about a file that can ask to run PowerShell.
const OFFICIAL_CATALOGS = CATALOG_PROJECTS.flatMap((key) => kindsFor(key).map((kind) => ({
  id: `${key}-${kind.toLowerCase()}`,
  projectKey: key,
  kind,
  label: `${key.toUpperCase()} · ${kindLabel(kind, key)}`,
})));

// Admin: quickly publish an OFFICIAL catalog entry for BMM or BSM.
function AdminCatalogCreator() {
  const toast = useToast(); const { t } = useI18n(); const dialog = useDialog();
  const [f, setF] = useState({ name: '', version: '1.0.0', description: '', tags: '', url: '' });
  const [file, setFile] = useState(null);
  const [busy, setBusy] = useState(false);
  // Picking a catalog sets project AND kind together — they are not independent choices.
  const [catId, setCatId] = useState(OFFICIAL_CATALOGS[0].id);
  const cat = OFFICIAL_CATALOGS.find((c) => c.id === catId) || OFFICIAL_CATALOGS[0];
  // Derived, never mirrored into form state: two copies of the same fact drift, and the one
  // that drifts here would publish an entry into the wrong feed.
  const projectKey = cat.projectKey;
  const kind = cat.kind;
  // What is already in the catalog being filled — the community catalog page shows its
  // contents, and there was no reason the official one should not.
  const contents = useAsync(() => api.get(`/admin/catalog?project=${cat.projectKey}&kind=${cat.kind}&status=PUBLISHED`), [catId]);
  const [edit, setEdit] = useState(null);
  const [removed, setRemoved] = useState(() => new Set()); // optimistically hidden during the undo window

  // The download URL is stored in a different place per kind — the feeds have different
  // payload shapes — so reading it back for the edit form has to mirror that.
  const urlOf = (it) => it.kind === 'PLUGIN' ? (it.meta?.download_url || '')
    : it.kind === 'APP' ? (it.meta?.download?.url || '')
    : (it.meta?.url || '');
  const startEdit = (it) => setEdit({
    id: it.id, name: it.name || '', version: it.version || '',
    description: it.description || '', url: urlOf(it), tags: (it.tags || []).join(', '),
  });
  const saveEdit = async () => {
    try {
      await api.patch(`/admin/catalog/${edit.id}`, {
        name: edit.name.trim(), version: edit.version.trim(), description: edit.description,
        url: edit.url.trim(), tags: edit.tags.split(',').map((x) => x.trim()).filter(Boolean),
      });
      toast.success(t('common.saved', 'Saved.')); setEdit(null); contents.reload();
    } catch (x) { toast.error(x.data?.error || t('common.failed', 'Failed.')); }
  };
  // Deletion is the existing 72h-grace schedule, not a hard delete — the entry unpublishes now
  // and its files survive until the window closes, so an undo really can put it back.
  const removeEntry = (it) => {
    setRemoved((s) => new Set(s).add(it.id));
    const restore = () => setRemoved((s) => { const n = new Set(s); n.delete(it.id); return n; });
    toast.action({
      tone: 'success', duration: 6000, cancelLabel: t('common.undo', 'Undo'),
      msg: t('cc.removed', 'Entry removed from the catalog.'),
      onCommit: async () => {
        try { await api.post(`/catalog/${it.id}/delete`); contents.reload(); }
        catch { toast.error(t('common.failed', 'Failed.')); restore(); }
      },
      onCancel: restore,
    });
  };
  const deeplink = projectKey === 'bmm'
    ? `bmm://catalog/${kind.toLowerCase()}/install?name=${encodeURIComponent(f.name || 'name')}${f.url ? `&url=${encodeURIComponent(f.url)}` : ''}`
    : '';

  const onFile = async (uploaded) => {
    setFile(uploaded);
    if (uploaded && kind === 'PRESET' && /json$/i.test(uploaded.name)) {
      try { const j = JSON.parse(await uploaded.text()); setF((s) => ({ ...s, name: j.name || s.name, version: j.version || s.version, meta: j })); }
      catch { toast.error(t('cc.presetinvalid', 'Preset is not valid JSON.')); }
    }
  };
  const submit = async () => {
    if (f.name.length < 2) return toast.error(t('cc.namereq', 'Name is required.'));
    setBusy(true);
    try {
      let payloadKey; if (file) payloadKey = await uploadPayload(kind, file);
      // Plugins use download_url; apps use the BMM App-Catalog shape (download.{url,file_type}).
      const ftype = /\.(zip|msi|exe)(\?|$)/i.exec(f.url || '')?.[1]?.toLowerCase() || 'exe';
      const meta = kind === 'PRESET' ? (f.meta || {})
        : kind === 'PLUGIN' ? { ...(f.url ? { download_url: f.url } : {}), ...(deeplink ? { deeplink } : {}) }
        : kind === 'APP' ? { id: f.name.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, ''), title: f.name, category: 'utility', price: 'free', tags: f.tags.split(',').map((t) => t.trim()).filter(Boolean).slice(0, 3), ...(f.url ? { download: { url: f.url, file_type: ftype } } : {}), ...(deeplink ? { deeplink } : {}) }
        : { ...(f.url ? { url: f.url } : {}), ...(deeplink ? { deeplink } : {}) };
      const body = { projectKey: projectKey, kind: kind, name: f.name, version: f.version, description: f.description,
        tags: f.tags.split(',').map((t) => t.trim()).filter(Boolean), payloadKey, meta };
      const res = await api.post('/admin/catalog', body);
      if (kind === 'PLUGIN' && res.validation) toast[res.validation.valid ? 'success' : 'error'](res.validation.valid ? t('cc.pubvalidated', 'Plugin "{n}" published & validated.').replace('{n}', f.name) : t('cc.pubinvalid', 'Published but INVALID: {r}, fix before users install.').replace('{r}', res.validation.reason));
      else toast.success(t('cc.published', 'Official {k} "{n}" published.').replace('{k}', KIND_LABEL[kind]).replace('{n}', f.name));
      setF({ name: '', version: '1.0.0', description: '', tags: '', url: '' }); setFile(null);
      contents.reload(); // the new entry should appear in the list below, not on next reload
    } catch (x) {
      const e = x.data?.error;
      // The API returns the accepted list with a 415; showing the raw code left you guessing
      // which of a dozen allowlists you had just missed.
      toast.error(
        e === 'unsupported_type' ? t('cc.badtype', 'That file type is not accepted for this kind. Allowed: {a}').replace('{a}', (x.data?.allowed || []).join(', '))
        : e === 'invalid_preset' ? t('cc.presetjsoninvalid', 'Preset JSON is invalid.')
        : e || t('common.failed', 'Failed.'));
    } finally {
      // Was missing entirely: `busy` went true and was never cleared, so the Publish button
      // stayed disabled after the FIRST attempt — success or failure — until a page reload.
      setBusy(false);
    }
  };
  const copy = () => { navigator.clipboard?.writeText(deeplink); toast.success(t('cc.dlcopied', 'Deeplink copied.')); };

  // The URL BMM actually consumes as a catalog source. It is derived from the project + kind
  // already chosen above, so there is nothing extra to fill in — the panel that publishes the
  // entry is also where you get the link to the feed it lands in.
  const feedUrl = `${location.origin}/api/catalog.json?project=${encodeURIComponent(projectKey)}&kind=${encodeURIComponent(kind.toLowerCase())}`;
  const copyFeed = () => { navigator.clipboard?.writeText(feedUrl); toast.success(t('cc.feedcopied', 'Catalog URL copied.')); };

  return (
    <div>
      <h2 className="font-semibold mb-1 flex items-center gap-2"><BadgeCheck size={16} className="text-[var(--accent-ink)]" /> {t('cc.title', 'Create an official catalog entry')}</h2>
      <p className="text-sm text-[var(--muted)] mb-4" dangerouslySetInnerHTML={{ __html: t('cc.sub', 'Publishes instantly (no moderation) and is flagged <b>Official</b>. BSM offers presets; BMM offers apps, plugins and themes with a <code>bmm://</code> deeplink.') }} />
      {/* Which catalog you are filling — chosen once, not re-answered per entry. */}
      <div className="flex flex-wrap gap-2 mb-3">
        {OFFICIAL_CATALOGS.map((c) => {
          const Icon = KIND_ICON[c.kind] || Boxes;
          const on = c.id === cat.id;
          return (
            <button key={c.id} type="button" onClick={() => setCatId(c.id)}
              className={`flex items-center gap-2 px-3 py-2 rounded-xl border text-sm transition-colors ${on ? 'border-[var(--primary)] tint-primary text-[var(--text)] font-medium' : 'border-[var(--line)] text-[var(--muted)] hover:border-[var(--line-strong)]'}`}>
              <Icon size={14} className={on ? 'text-[var(--accent-ink)]' : ''} /> {c.label}
            </button>
          );
        })}
      </div>

      {/* Server-Repos are the fifth thing the catalog index points at, and the one that is
          NOT a CatalogKind — a repo is a hosted ServerRepo, not an entry somebody publishes
          here. Saying so is the point: the index lists five types and this screen makes
          four, and without this line that gap reads as a missing button. */}
      <Card className="p-3 mb-4 flex flex-wrap items-center gap-2">
        <Server size={14} className="text-[var(--muted)]" />
        <span className="text-xs text-[var(--muted)] flex-1 min-w-0">
          {t('cc.repos', 'Server-Repos are not published here, they are hosted by their owners and appear in the index automatically once verified and listed.')}
        </span>
        <a href="/api/repos.json" target="_blank" rel="noreferrer">
          <Button size="sm" variant="ghost"><ExternalLink size={13} /> {t('cc.reposfeed', 'Repo feed')}</Button>
        </a>
      </Card>

      {/* Where this entry ends up. BMM adds this URL as a catalog source, so it belongs next to
          the form that publishes into it rather than somewhere a reader has to go and find. */}
      <Card className="p-3 mb-4 flex flex-wrap items-center gap-2">
        <span className="text-xs font-semibold text-[var(--muted)]">{t('cc.feed', 'Catalog URL for BMM')}</span>
        <code className="font-mono text-xs px-2 py-1 rounded-lg bg-[var(--surface-2)] break-all flex-1 min-w-0">{feedUrl}</code>
        <Button size="sm" variant="ghost" onClick={copyFeed}><Copy size={13} /> {t('common.copy', 'Copy')}</Button>
        <a href={feedUrl} target="_blank" rel="noreferrer"><Button size="sm" variant="ghost"><ExternalLink size={13} /> {t('cc.open', 'Open')}</Button></a>
      </Card>
      <Card className="p-5 space-y-3">
        <div className="grid sm:grid-cols-2 gap-3">
          <Field label={t('cc.name', 'Name')}><Input value={f.name} onChange={(e) => setF({ ...f, name: e.target.value })} placeholder={kind === 'PRESET' ? 'Afterburner Boom' : kind === 'THEME' ? 'Midnight Orange' : 'Auto Backup'} /></Field>
          <Field label={t('cc.version', 'Version')}><Input value={f.version} onChange={(e) => setF({ ...f, version: e.target.value })} /></Field>
        </div>
        <Field label={t('cc.description', 'Description')}><Textarea value={f.description} onChange={(e) => setF({ ...f, description: e.target.value })} placeholder={t('cc.descph', 'What it does, in a sentence or two…')} /></Field>
        <Field label={t('cc.tags', 'Tags (comma-separated)')}><Input value={f.tags} onChange={(e) => setF({ ...f, tags: e.target.value })} placeholder="audio, utility, dark-theme" /></Field>
        {kind === 'PLUGIN' && <div className="rounded-lg border border-[var(--line)] bg-[var(--surface-2)] p-2.5 text-xs text-[var(--muted)]" dangerouslySetInnerHTML={{ __html: t('cc.pluginnote', "Host the <code>.bmmplug</code> yourself (URL below) or with us (upload it, priced by size). Either way it's checksum-validated on publish.") }} />}
        {kind !== 'PRESET' && <Field label={kind === 'PLUGIN' ? t('cc.plugurl', '.bmmplug URL (self-hosted)') : t('cc.dlurl', 'Download URL')} hint={kind === 'PLUGIN' ? t('cc.plugurlhint', 'GitHub raw / personal server. Leave empty to host with us via upload.') : t('cc.dlurlhint', 'Where the app/theme is fetched from.')}><Input value={f.url} onChange={(e) => setF({ ...f, url: e.target.value })} placeholder={kind === 'PLUGIN' ? 'https://raw.githubusercontent.com/you/repo/main/plugin.bmmplug' : 'https://github.com/you/repo/releases/latest/download/app.zip'} /></Field>}
        <Field label={kind === 'PRESET' ? t('cc.presetfile', 'Preset .json (metadata is read from the file)') : kind === 'PLUGIN' ? t('cc.plugfile', '.bmmplug file (our-hosted, priced by size)') : t('cc.payloadfile', 'Payload file (optional, zip / wasm)')}>
          <Input type="file" accept={kind === 'PRESET' ? '.json,application/json' : kind === 'PLUGIN' ? '.bmmplug,.zip' : undefined} onChange={(e) => onFile(e.target.files?.[0] || null)} /></Field>
        {deeplink && (
          <div className="rounded-lg border border-[var(--line)] bg-[var(--surface-2)] p-3">
            <div className="text-[10px] font-semibold uppercase tracking-wider text-[var(--faint)] mb-1 flex items-center gap-1"><Link2 size={11} /> {t('cc.deeplink', 'BMM deeplink')}</div>
            <div className="flex items-center gap-2"><code className="text-xs text-[var(--muted)] truncate flex-1" title={deeplink}>{deeplink}</code><Button size="sm" onClick={copy}><Copy size={13} /></Button></div>
          </div>
        )}
        <div className="flex justify-end"><Button variant="primary" disabled={busy} onClick={submit}>{busy ? <Spinner /> : <><BadgeCheck size={15} /> {t('cc.publish', 'Publish official')}</>}</Button></div>
      </Card>

      {/* What is already in this catalog. Without it, publishing was a blind append — no way
          to see a duplicate, or to check the last entry actually landed. */}
      <div className="mt-5">
        <div className="text-xs font-semibold uppercase tracking-wider text-[var(--faint)] mb-2">
          {t('cc.contents', 'Already in this catalog')}
          {contents.data?.items?.length > 0 && <span className="text-[var(--muted)] normal-case tracking-normal"> · {contents.data.items.length}</span>}
        </div>
        {contents.loading ? <Loading /> : !contents.data?.items?.length ? (
          <EmptyState icon={Boxes} title={t('cc.empty.t', 'Nothing published yet')} sub={t('cc.empty.s', 'Entries you publish above appear here.')} />
        ) : (
          <Card className="divide-y divide-[var(--line)] overflow-hidden">
            {contents.data.items.filter((it) => !removed.has(it.id)).map((it) => (
              <div key={it.id} className="p-3">
                <div className="flex items-center gap-3">
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2 flex-wrap">
                      <span className="font-medium truncate" title={it.name}>{it.name}</span>
                      {it.version && <span className="text-[11px] font-mono text-[var(--faint)]">v{it.version}</span>}
                      {it.status === 'HIDDEN' && <Badge tone="">{t('cc.hidden', 'hidden')}</Badge>}
                      {it.meta?.validation?.valid === false && <Badge tone="red">{t('cc.invalid', 'invalid')}</Badge>}
                    </div>
                    {it.description && <p className="text-xs text-[var(--muted)] truncate" title={it.description}>{it.description}</p>}
                  </div>
                  <span className="text-[11px] text-[var(--faint)] shrink-0">{fmtAgo(it.updatedAt)}</span>
                  <button onClick={() => startEdit(it)} title={t('common.edit', 'Edit')}
                    className="p-1.5 rounded-lg text-[var(--muted)] hover:text-[var(--text)]"><Pencil size={13} /></button>
                  <button onClick={() => removeEntry(it)} title={t('common.delete', 'Delete')}
                    className="p-1.5 rounded-lg text-error hover:bg-error-bg"><Trash2 size={13} /></button>
                </div>
                {edit?.id === it.id && (
                  <div className="mt-3 pt-3 border-t border-[var(--line)] grid sm:grid-cols-2 gap-2">
                    <Field label={t('cc.name', 'Name')}><Input value={edit.name} onChange={(e) => setEdit({ ...edit, name: e.target.value })} /></Field>
                    <Field label={t('cc.version', 'Version')}><Input value={edit.version} onChange={(e) => setEdit({ ...edit, version: e.target.value })} /></Field>
                    <div className="sm:col-span-2"><Field label={t('cc.description', 'Description')}><Textarea rows={2} value={edit.description} onChange={(e) => setEdit({ ...edit, description: e.target.value })} /></Field></div>
                    <div className="sm:col-span-2"><Field label={t('cc.dlurl', 'Download URL')}><Input value={edit.url} onChange={(e) => setEdit({ ...edit, url: e.target.value })} placeholder="https://…" /></Field></div>
                    <div className="sm:col-span-2"><Field label={t('cc.tags', 'Tags (comma-separated)')}><Input value={edit.tags} onChange={(e) => setEdit({ ...edit, tags: e.target.value })} /></Field></div>
                    <div className="sm:col-span-2 flex gap-2">
                      <Button size="sm" variant="primary" onClick={saveEdit}><Save size={13} /> {t('common.save', 'Save')}</Button>
                      <Button size="sm" variant="ghost" onClick={() => setEdit(null)}>{t('common.cancel', 'Cancel')}</Button>
                    </div>
                  </div>
                )}
              </div>
            ))}
          </Card>
        )}
      </div>
    </div>
  );
}



// Admin: find a user by id / display name / email / linked creator id, then inspect them.
function AdminUsers() {
  const { t } = useI18n();
  const [sp] = useSearchParams();
  const [q, setQ] = useState(sp.get('q') || '');
  const [results, setResults] = useState(null);
  const [hasMore, setHasMore] = useState(false);
  const [busy, setBusy] = useState(false);
  const [detail, setDetail] = useState(null);
  // Filters. Held in one object so `load` reads the CURRENT set rather than closing over a
  // stale one — a filter that applies on the next search but not this one is worse than none.
  const [f, setF] = useState({ role: '', status: '', twofa: '', closed: '', linked: '', days: '', sort: 'new' });
  const activeFilters = Object.entries(f).filter(([k, v]) => v && !(k === 'sort' && v === 'new')).length;
  // Load users; `append` pages more (Load more), else replaces. Empty term = all users.
  const load = async (term, append = false, filters = f) => {
    term = (term || '').trim();
    setBusy(true);
    try {
      const skip = append ? (results?.length || 0) : 0;
      const qs = new URLSearchParams({ q: term, skip: String(skip), take: '30' });
      for (const [k, v] of Object.entries(filters)) if (v) qs.set(k, v);
      const { users, hasMore: more } = await api.get(`/admin/users?${qs}`);
      setResults(append ? [...(results || []), ...users] : users); setHasMore(more);
    } catch { if (!append) setResults([]); } finally { setBusy(false); }
  };
  const search = () => load(q, false);
  useEffect(() => { load(sp.get('q') || '', false); /* eslint-disable-next-line */ }, []);
  const since = (d) => new Date(d).toLocaleDateString(undefined, { year: 'numeric', month: 'short', day: 'numeric' });
  return (
    <div>
      <h2 className="font-semibold mb-1 flex items-center gap-2"><Users size={16} className="text-[var(--accent-ink)]" /> {t('au.title', 'User search')}</h2>
      <p className="text-sm text-[var(--muted)] mb-4">{t('au.desc', 'Search by user id, Unique BC id (BC-XXXX-XXXX), display name, email, a linked creator id, or a linked Discord (username / id). Click a user to see full details.')}</p>
      <div className="flex gap-2 mb-5">
        <div className="relative flex-1">
          <Search size={15} className="absolute left-3 top-1/2 -translate-y-1/2 text-[var(--faint)] pointer-events-none" />
          <Input className="!ps-9" placeholder={t('au.search.ph', 'id / display name / email / creator id / Discord…')} value={q} onChange={(e) => setQ(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && search()} />
        </div>
        <Button variant="primary" disabled={busy} onClick={search}>{busy ? <Spinner /> : <><Search size={15} /> {t('au.search', 'Search')}</>}</Button>
      </div>

      {/* Filters apply on change rather than on a second button: a set of controls that need a
          separate "apply" is how somebody stares at a list that does not match what the boxes
          say. `activeFilters` is shown because an empty result with a filter left on reads
          exactly like an empty result. */}
      <div className="flex flex-wrap items-center gap-2 mb-5">
        {[
          ['role', t('au.f.role', 'Any role'), [['USER', 'USER'], ['MOD', 'MOD'], ['ADMIN', 'ADMIN'], ['SUPERADMIN', 'SUPERADMIN']]],
          ['status', t('au.f.status', 'Any status'), [['active', t('au.f.active', 'Active')], ['suspended', t('au.f.susp', 'Suspended')], ['banned', t('au.f.banned', 'Banned')]]],
          ['closed', t('au.f.closed', 'Open or closed'), [['no', t('au.f.open', 'Open')], ['yes', t('au.f.isclosed', 'Closed')]]],
          ['twofa', t('au.f.2fa', '2FA, either'), [['yes', t('au.f.2fayes', 'Has 2FA')], ['no', t('au.f.2fano', 'No 2FA')]]],
          ['linked', t('au.f.linked', 'Any link'), [['discord', 'Discord'], ['creator', t('au.f.creator', 'Creator id')], ['none', t('au.f.nolink', 'Nothing linked')]]],
          ['days', t('au.f.joined', 'Joined, any time'), [['1', t('au.f.d1', 'Last 24 h')], ['7', t('au.f.d7', 'Last 7 days')], ['30', t('au.f.d30', 'Last 30 days')], ['365', t('au.f.d365', 'Last year')]]],
          ['sort', t('au.f.new', 'Newest first'), [['old', t('au.f.old', 'Oldest first')], ['name', t('au.f.name', 'By name')]]],
        ].map(([key, any, opts]) => (
          <select key={key} value={f[key]} className="input !py-1.5 !text-sm !w-auto"
            onChange={(e) => { const next = { ...f, [key]: e.target.value }; setF(next); load(q, false, next); }}>
            <option value={key === 'sort' ? 'new' : ''}>{any}</option>
            {opts.map(([v, label]) => <option key={v} value={v}>{label}</option>)}
          </select>
        ))}
        {activeFilters > 0 && (
          <Button size="sm" variant="ghost" onClick={() => { const next = { role: '', status: '', twofa: '', closed: '', linked: '', days: '', sort: 'new' }; setF(next); load(q, false, next); }}>
            {t('au.f.clear', 'Clear {n} filter(s)').replace('{n}', activeFilters)}
          </Button>
        )}
      </div>
      {results === null ? <EmptyState icon={Users} title={t('au.find.t', 'Find a user')} sub={t('au.find.s', 'Enter a term above to search.')} />
        : results.length ? <div className="space-y-2">
          {results.map((u) => (
            <button key={u.id} onClick={() => setDetail(u.id)} className="w-full text-start card card-hover p-4 flex items-center gap-3">
              <Avatar user={u} size={40} />
              <div className="flex-1 min-w-0">
                <div className="font-medium flex items-center gap-2 flex-wrap min-w-0"><span className="truncate min-w-0" title={u.displayName}>{u.displayName}</span> <Badge tone={u.role === 'SUPERADMIN' ? 'red' : u.role === 'ADMIN' ? 'amber' : u.role === 'MOD' ? 'primary' : ''}>{u.role}</Badge>{u.status === 'banned' ? <Badge tone="red"><Ban size={10} /> {t('au.banned', 'banned')}</Badge> : u.status === 'suspended' ? <Badge tone="amber"><Clock size={10} /> {t('au.suspended', 'suspended')}</Badge> : null}</div>
                <div className="text-xs text-[var(--faint)] truncate">{u.email} · {t('au.since', 'since')} {since(u.createdAt)}</div>
                <div className="text-xs text-[var(--faint)] mt-0.5 font-mono truncate flex items-center gap-2">
                  {u.bcId && <span className="inline-flex items-center gap-1 text-[var(--accent-ink)]"><Fingerprint size={11} /> {u.bcId}</span>}
                  <span className="truncate" title={u.id}>{u.id}</span>
                </div>
                {u.discord && (
                  <div className="text-xs mt-0.5 flex items-center gap-1.5 truncate text-[#5865F2]">
                    <DiscordIcon size={12} /> <span className="font-medium">{u.discord.username || 'linked'}</span>
                    <span className="text-[var(--faint)] font-mono">· {u.discord.id}</span>
                  </div>
                )}
              </div>
              <div className="text-xs text-[var(--muted)] flex flex-col items-end gap-0.5 shrink-0">
                <span className="flex items-center gap-1"><Server size={11} /> {u.repoCount}</span>
                <span className="flex items-center gap-1"><Package size={11} /> {u.itemCount}</span>
                {u.creatorIds.length > 0 && <Badge tone="green">{t('au.creatorids', '{n} creator id(s)').replace('{n}', u.creatorIds.length)}</Badge>}
                {u.discord && <Badge tone="primary"><DiscordIcon size={10} /> {t('au.discord', 'Discord')}</Badge>}
              </div>
            </button>
          ))}
          {hasMore && <div className="text-center pt-1"><Button variant="ghost" disabled={busy} onClick={() => load(q, true)}>{busy ? <Spinner /> : t('au.loadmore', 'Load more')}</Button></div>}
        </div> : <EmptyState icon={XCircle} title={t('au.none.t', 'No users found')}
          sub={q || activeFilters ? t('au.none.s3', 'The term and the filters above exclude every account. Clearing them lists everyone.') : t('au.none.s', 'Try a different id, name, email or creator id.')}
          action={q || activeFilters ? { label: t('au.none.clear', 'Clear the search and filters'), icon: X, onClick: () => { const next = { role: '', status: '', twofa: '', closed: '', linked: '', days: '', sort: 'new' }; setQ(''); setF(next); load('', false, next); } } : null} />}
      {detail && <UserDetailModal id={detail} onClose={() => setDetail(null)} />}
    </div>
  );
}

// Admin: who's on a free plan vs. who has actually paid us. "Paying" is driven by
// real Payment rows (never by plan name), so it stays correct as pricing/thresholds
// change — a user who was billed once and then stays under the free tier forever
// after still counts as a paying customer (they have Payment history).
const PLANUSERS_TABS = [
  ['paying', CreditCard, 'Paying customers'],
  ['free', Gift, 'Free plan'],
  ['archived', Archive, 'Archived'],
];
// Classified by CURRENT state (see the endpoint): a user can appear in more than one
// tab — e.g. one free repo + one paid boost — since the tabs aren't a strict partition.

// Running costs, and what they leave once revenue has paid them.
//
// Sits inside Customers & revenue rather than in a screen of its own, because the number
// anybody actually wants is the SUBTRACTION. MRR on one page and costs on another is how a
// business ends up knowing both figures and not the answer.
//
// Money is integer cents throughout, formatted only at the edge. Currencies are never summed
// across: the totals are in whichever currency the costs are mostly in, and anything else is
// listed separately rather than converted at a rate this screen would have to invent.
function AdminExpenses({ mrrCents }) {
  const toast = useToast(); const dialog = useDialog(); const { t } = useI18n();
  const { data, loading, reload } = useAsync(() => api.get('/admin/expenses'), []);
  const [open, setOpen] = useState(false);
  const [f, setF] = useState({ label: '', category: 'hosting', amount: '', currency: 'CHF', recurring: 'monthly', note: '' });
  const [busy, setBusy] = useState(false);

  const rows = data?.expenses || [];
  const burn = data?.monthlyBurn || 0;
  const cats = data?.categories || [];
  const money = (c) => (c / 100).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  const net = (mrrCents || 0) - burn;

  const add = async () => {
    const amount = Math.round(Number(String(f.amount).replace(',', '.')) * 100);
    if (!f.label.trim() || !Number.isFinite(amount) || amount < 0) {
      toast.error(t('ex.bad', 'A label and an amount are required.')); return;
    }
    setBusy(true);
    try {
      await api.post('/admin/expenses', {
        label: f.label.trim(), category: f.category, amountCents: amount,
        currency: f.currency.toUpperCase(), recurring: f.recurring, note: f.note.trim(),
      });
      setF({ ...f, label: '', amount: '', note: '' });
      reload();
    } catch { toast.error(t('common.err', 'Something went wrong.')); }
    finally { setBusy(false); }
  };

  // Ending a recurring cost, not deleting it: last month's figure must not change because a
  // subscription stopped today.
  const end = async (e) => {
    if (!await dialog.confirm({
      title: t('ex.end.t', 'Mark this as ended?'),
      message: t('ex.end.m', 'It stops counting from now on and stays in the history, so past months keep the figure they actually had.'),
      confirmLabel: t('ex.end.ok', 'Mark ended'),
    })) return;
    try { await api.put(`/admin/expenses/${e.id}`, { endedAt: new Date().toISOString() }); reload(); }
    catch { toast.error(t('common.err', 'Something went wrong.')); }
  };
  const del = async (e) => {
    if (!await dialog.confirm({
      title: t('ex.del.t', 'Delete this cost?'),
      message: t('ex.del.m', 'It disappears from every month it applied to, including closed ones. To stop a recurring cost without rewriting history, mark it ended instead.'),
      danger: true,
    })) return;
    try { await api.del(`/admin/expenses/${e.id}`); reload(); }
    catch { toast.error(t('common.err', 'Something went wrong.')); }
  };

  if (loading) return null;
  const maxSeries = Math.max(1, ...(data?.series || []).map((s) => s.cents));

  return (
    <Card className="p-4 mb-3">
      <button type="button" onClick={() => setOpen((v) => !v)} className="w-full flex items-center gap-2 text-start mb-1">
        <Wallet size={15} className="text-[var(--accent-ink)]" />
        <span className="font-medium text-sm">{t('ex.title', 'Running costs')}</span>
        <Badge>{rows.length}</Badge>
        <span className="ms-auto text-sm tabular-nums">
          <span className="text-[var(--muted)]">{t('ex.burn', 'per month')} </span>
          <b>{money(burn)}</b>
        </span>
        <ChevronDown size={15} className={`text-[var(--faint)] transition-transform ${open ? 'rotate-180' : ''}`} />
      </button>

      {/* The subtraction, always visible whether the panel is open or not — it is the reason
          this exists. Red when costs exceed income, and it says which. */}
      <div className="grid sm:grid-cols-3 gap-2 mt-2 text-sm">
        <div className="p-2.5 rounded-lg bg-[var(--surface-2)]">
          <div className="text-[11px] text-[var(--faint)]">{t('ex.in', 'Recurring income')}</div>
          <div className="tabular-nums font-medium text-success">{money(mrrCents || 0)}</div>
        </div>
        <div className="p-2.5 rounded-lg bg-[var(--surface-2)]">
          <div className="text-[11px] text-[var(--faint)]">{t('ex.out', 'Recurring costs')}</div>
          <div className="tabular-nums font-medium text-error">−{money(burn)}</div>
        </div>
        <div className="p-2.5 rounded-lg" style={{ background: `color-mix(in srgb, var(--${net >= 0 ? 'success' : 'error'}) 12%, transparent)` }}>
          <div className="text-[11px] text-[var(--faint)]">{net >= 0 ? t('ex.net', 'Left over each month') : t('ex.short', 'Short each month')}</div>
          <div className={`tabular-nums font-bold ${net >= 0 ? 'text-success' : 'text-error'}`}>{money(Math.abs(net))}</div>
        </div>
      </div>

      {/* More than one currency in play makes every total above a half-truth. Said once,
          here, rather than silently adding francs to euros. */}
      {(data?.currencies || []).length > 1 && (
        <div className="mt-2 text-xs text-[var(--muted)] flex items-start gap-1.5">
          <AlertTriangle size={13} className="text-[var(--warning)] shrink-0 mt-0.5" />
          {t('ex.multicur', 'Costs are recorded in {n} currencies and are NOT converted — the totals above add the raw numbers together and are only meaningful once they share a currency.').replace('{n}', data.currencies.length)}
        </div>
      )}

      {open && (<div className="mt-4 space-y-4">
        {/* Twelve months at a glance. Bars, not a chart library: the shape is the whole
            message and a dependency would not add one. */}
        <div>
          <div className="text-[11px] text-[var(--faint)] mb-1.5">{t('ex.series', 'Cost per month')}</div>
          <div className="flex items-end gap-1 h-16">
            {(data?.series || []).map((s) => (
              <div key={s.month} className="flex-1 rounded-t bg-[var(--primary)] hover:bg-[var(--primary)] transition-colors"
                style={{ height: `${Math.max(2, (s.cents / maxSeries) * 100)}%` }}
                title={`${s.month} · ${money(s.cents)}`} />
            ))}
          </div>
        </div>

        {Object.keys(data?.byCategory || {}).length > 0 && (
          <div className="flex flex-wrap gap-1.5">
            {Object.entries(data.byCategory).sort((a, b) => b[1] - a[1]).map(([k, v]) => (
              <span key={k} className="text-xs px-2 py-1 rounded-lg bg-[var(--surface-2)] border border-[var(--line)]">
                {t(`ex.cat.${k}`, k)} <b className="tabular-nums">{money(v)}</b>
              </span>
            ))}
          </div>
        )}

        <div className="grid sm:grid-cols-[1fr_auto_auto_auto] gap-2">
          <Input value={f.label} onChange={(e) => setF({ ...f, label: e.target.value })} placeholder={t('ex.label', 'What is it (VPS, domain, …)')} />
          <Input className="!w-24" value={f.amount} onChange={(e) => setF({ ...f, amount: e.target.value })} placeholder="0.00" inputMode="decimal" />
          <Select className="!w-auto" value={f.category} onChange={(e) => setF({ ...f, category: e.target.value })}>
            {cats.map((c) => <option key={c} value={c}>{t(`ex.cat.${c}`, c)}</option>)}
          </Select>
          <Select className="!w-auto" value={f.recurring} onChange={(e) => setF({ ...f, recurring: e.target.value })}>
            <option value="monthly">{t('ex.r.monthly', 'per month')}</option>
            <option value="yearly">{t('ex.r.yearly', 'per year')}</option>
            <option value="none">{t('ex.r.none', 'one-off')}</option>
          </Select>
        </div>
        <div className="flex gap-2">
          <Input className="!w-20" value={f.currency} onChange={(e) => setF({ ...f, currency: e.target.value })} placeholder="CHF" maxLength={3} />
          <Input value={f.note} onChange={(e) => setF({ ...f, note: e.target.value })} placeholder={t('ex.note', 'Note (optional)')} />
          <Button size="sm" onClick={add} disabled={busy}><Plus size={14} /> {t('ex.add', 'Add')}</Button>
        </div>

        <div className="space-y-1.5">
          {rows.map((e) => {
            const ended = e.endedAt && new Date(e.endedAt) <= new Date();
            return (
              <div key={e.id} className={`flex items-center gap-2 text-xs p-2 rounded-lg bg-[var(--surface-2)] ${ended ? 'opacity-55' : ''}`}>
                <Badge tone={e.recurring === 'none' ? undefined : 'primary'}>
                  {e.recurring === 'monthly' ? t('ex.r.monthly', 'per month') : e.recurring === 'yearly' ? t('ex.r.yearly', 'per year') : t('ex.r.none', 'one-off')}
                </Badge>
                <span className="font-medium truncate" title={e.label}>{e.label}</span>
                <span className="text-[var(--faint)] shrink-0">{t(`ex.cat.${e.category}`, e.category)}</span>
                {ended && <Badge tone="amber">{t('ex.ended', 'ended')}</Badge>}
                <span className="ms-auto tabular-nums shrink-0">{money(e.amountCents)} {e.currency}</span>
                {!ended && e.recurring !== 'none' && (
                  <button onClick={() => end(e)} className="text-[var(--faint)] hover:text-[var(--warning)] shrink-0" title={t('ex.end.ok', 'Mark ended')}>
                    <XCircle size={13} />
                  </button>
                )}
                <button onClick={() => del(e)} className="text-[var(--faint)] hover:text-error shrink-0" title={t('common.delete', 'Delete')}>
                  <Trash2 size={13} />
                </button>
              </div>
            );
          })}
          {!rows.length && <p className="text-xs text-[var(--muted)]">{t('ex.none', 'Nothing recorded yet. Add the VPS, the domain, anything you pay for, the figures above become real as soon as one exists.')}</p>}
        </div>
      </div>)}
    </Card>
  );
}

function AdminPlanUsers() {
  const { t } = useI18n(); const toast = useToast();
  const [sp] = useSearchParams();
  const [tab, setTab] = useState('paying');
  const [results, setResults] = useState(null);
  const [hasMore, setHasMore] = useState(false);
  const [busy, setBusy] = useState(false);
  const [detail, setDetail] = useState(null);
  const [expanded, setExpanded] = useState(null);
  const [includeStaff, setIncludeStaff] = useState(false);
  const [mrr, setMrr] = useState(null); // { totalCents, subCount, annualCents }
  const [q, setQ] = useState(''); const [qApplied, setQApplied] = useState('');
  const load = async (append = false) => {
    setBusy(true);
    try {
      const skip = append ? (results?.length || 0) : 0;
      const { users, hasMore: more, mrr: m } = await api.get(`/admin/billing/users?tab=${tab}&skip=${skip}&take=30${includeStaff ? '&includeStaff=1' : ''}${qApplied ? `&q=${encodeURIComponent(qApplied)}` : ''}`);
      setResults(append ? [...(results || []), ...users] : users); setHasMore(more); if (m) setMrr(m);
    } catch { if (!append) setResults([]); } finally { setBusy(false); }
  };
  const mrrMoney = (c) => `$${((c || 0) / 100).toFixed(2)}`;
  useEffect(() => { load(false); setExpanded(null); /* eslint-disable-next-line */ }, [tab, includeStaff, qApplied]);
  // Deep-link from the Discord payment embed: /admin?s=planusers&user=<id> opens that
  // customer's detail straight away.
  useEffect(() => { const u = sp.get('user'); if (u) setDetail(u); /* eslint-disable-next-line */ }, []);
  const since = (d) => new Date(d).toLocaleDateString(undefined, { year: 'numeric', month: 'short', day: 'numeric' });
  // A real fallback, not an empty string: the three tabs each have their own pair of keys,
  // and a fourth tab added later would otherwise render an empty state with no title at all.
  const emptyCopy = [t(`pu.empty.${tab}.t`, 'No customer here'), t(`pu.empty.${tab}.s`, 'Nobody is in this tab yet.')];
  return (
    <div>
      <h2 className="font-semibold mb-1 flex items-center gap-2"><Receipt size={16} className="text-[var(--accent-ink)]" /> {t('pu.title', 'Customers & revenue')}</h2>
      <p className="text-sm text-[var(--muted)] mb-3">{t('pu.desc', "What every customer currently has active: free-tier hosting, paid hosting/boosts, or expired/ended terms. Click a row to see the detail; click the user's name for their full profile.")}</p>
      <AdminExpenses mrrCents={mrr?.totalCents || 0} />
      {/* The cards render even with nothing to show. They used to be hidden until the
          request came back with an `mrr` object, so an empty site showed no figures at
          all — and the honest answer to "how much am I making" on an empty site is a
          visible 0, not a blank space where a number should be. */}
      {(() => {
        const measured = mrr?.stripe !== false;   // undefined = older API, treat as measured
        const dash = <span className="text-[var(--faint)]">—</span>;
        const num = (v) => (measured ? v : dash);
        return (
          <>
            <div className="grid sm:grid-cols-3 gap-3 mb-2">
              <Card className="p-4"><div className="text-xs text-[var(--faint)] flex items-center gap-1.5 mb-1"><RefreshCw size={12} className="text-success" /> {t('pu.mrr', 'Monthly recurring revenue')}</div><div className="text-2xl font-bold text-success tabular-nums">{num(<>{mrrMoney(mrr?.totalCents || 0)}<span className="text-sm font-normal text-[var(--faint)]">/{t('pu.mo', 'mo')}</span></>)}</div></Card>
              <Card className="p-4"><div className="text-xs text-[var(--faint)] flex items-center gap-1.5 mb-1"><TrendingUp size={12} className="text-[var(--accent-ink)]" /> {t('pu.arr', 'Annualized (est.)')}</div><div className="text-2xl font-bold tabular-nums">{num(<>{mrrMoney(mrr?.annualCents || 0)}<span className="text-sm font-normal text-[var(--faint)]">/{t('pu.yr', 'yr')}</span></>)}</div></Card>
              <Card className="p-4"><div className="text-xs text-[var(--faint)] flex items-center gap-1.5 mb-1"><CreditCard size={12} className="text-[var(--accent-ink)]" /> {t('pu.activesubs', 'Active subscriptions')}</div><div className="text-2xl font-bold tabular-nums">{num(mrr?.subCount || 0)}</div></Card>
            </div>
            {/* A zero you cannot trust is worse than no number: without this the card
                reads a confident "$0.00/mo" whether nobody is paying or Stripe simply
                never answered. */}
            {!measured && (
              <div className="text-xs text-warning flex items-center gap-1.5 mb-4">
                <AlertTriangle size={12} /> {t('pu.nostripe', 'Stripe did not answer, these figures could not be measured.')}
              </div>
            )}
            {/* Subscriptions live in Stripe with no account here — a wiped database, a
                shared test key, a deleted customer. Named, because otherwise this page
                is quietly smaller than the Stripe dashboard and nothing explains the gap. */}
            {measured && mrr?.orphanSubs > 0 && (
              <div className="text-xs text-[var(--muted)] flex items-start gap-1.5 mb-4">
                <Info size={12} className="mt-0.5 shrink-0" />
                <span>{t('pu.orphans', '{n} active subscription(s) in Stripe ({m}/mo) belong to no account here, so they are excluded above.')
                  .replace('{n}', String(mrr.orphanSubs)).replace('{m}', mrrMoney(mrr.orphanMrrCents))}</span>
              </div>
            )}
            {measured && !mrr?.orphanSubs && <div className="mb-4" />}
          </>
        );
      })()}
      <div className="flex flex-wrap gap-2 items-center mb-3">
        <div className="relative flex-1 min-w-[200px]"><Search size={14} className="absolute left-2.5 top-1/2 -translate-y-1/2 text-[var(--faint)] pointer-events-none" />
          <Input className="!ps-8 !py-1.5 !text-sm" placeholder={t('pu.search', 'Search a customer, name, email, creator id…')} value={q}
            onChange={(e) => setQ(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && setQApplied(q.trim())} /></div>
        <Button size="sm" onClick={() => setQApplied(q.trim())}>{t('pu.searchbtn', 'Search')}</Button>
        {qApplied && <Button size="sm" variant="ghost" onClick={() => { setQ(''); setQApplied(''); }}><X size={13} /> {t('pu.clear', 'Clear')}</Button>}
      </div>
      <label className="flex items-center gap-2 text-xs text-[var(--muted)] mb-4 cursor-pointer w-fit">
        <input type="checkbox" checked={includeStaff} onChange={(e) => setIncludeStaff(e.target.checked)} /> {t('pu.includestaff', 'Include staff (admins/mods), normally excluded from this customer report')}
      </label>
      <div className="flex gap-2 mb-4">
        {PLANUSERS_TABS.map(([id, I, label]) => (
          <button key={id} onClick={() => setTab(id)} className={`flex-1 px-3 py-2 rounded-xl text-sm font-medium border transition ${tab === id ? 'bg-[var(--surface-2)] border-[var(--line)] text-[var(--text)]' : 'border-transparent text-[var(--muted)] hover:text-[var(--text)]'}`}>
            <I size={14} className="inline me-1.5 -mt-0.5" /> {t(`pu.tab.${id}`, label)}</button>
        ))}
      </div>
      {busy && !results ? <Loading /> : results && results.length ? <div className="space-y-2">
        {results.map((u) => {
          const isOpen = expanded === u.id;
          return (
          <Card key={u.id} className="p-0 overflow-hidden">
            <button onClick={() => setExpanded(isOpen ? null : u.id)} className="w-full text-start p-4 flex items-center gap-3 hover:bg-[var(--surface-2)] transition">
              <Avatar user={u} size={40} />
              <div className="flex-1 min-w-0">
                {/* A <button>, not a clickable <span>: it opens the user detail, and looked
                    like a link (hover:underline) while being unreachable by keyboard — no
                    focus, no Enter (WCAG 2.1.1 / 4.1.2). */}
                <div className="font-medium flex items-center gap-2 flex-wrap min-w-0"><span className="truncate min-w-0"><button type="button" onClick={(e) => { e.stopPropagation(); setDetail(u.id); }} className="text-start hover:underline hover:text-[var(--accent-ink)]" title={t('au.opendetail', 'Open this account’s details')}>{u.displayName}</button></span> <Badge tone={u.role === 'SUPERADMIN' ? 'red' : u.role === 'ADMIN' ? 'amber' : u.role === 'MOD' ? 'primary' : ''}>{u.role}</Badge></div>
                <div className="text-xs text-[var(--faint)] truncate" title={u.email}>{u.email}</div>
              </div>
              {tab === 'paying' && (u.totalSpentCents != null || u.mrrCents > 0) && (
                <div className="text-xs text-end shrink-0">
                  {u.mrrCents > 0 && <div className="text-sm font-semibold text-success">{mrrMoney(u.mrrCents)}<span className="text-[var(--faint)] font-normal">/{t('pu.mo', 'mo')}</span></div>}
                  {u.totalSpentCents != null && <div className="text-[var(--faint)]">{t('pu.spent', '{n} spent').replace('{n}', mrrMoney(u.totalSpentCents))} · {t('pu.payments', '{n} payment(s)').replace('{n}', u.paymentCount)}</div>}
                </div>
              )}
              <Badge className="shrink-0">{t('pu.active', '{n} active').replace('{n}', u.active.length)}</Badge>
              <ChevronDown size={15} className={`shrink-0 text-[var(--faint)] transition-transform ${isOpen ? 'rotate-180' : ''}`} />
            </button>
            {isOpen && (
              <div className="px-4 pb-4 pt-1 space-y-1.5 border-t border-[var(--line)]">
                {u.active.map((a, i) => {
                  // Back-compat: tolerate a plain-string entry (old API shape).
                  if (typeof a === 'string') return (
                    <div key={i} className="flex items-center gap-2 text-sm px-3 py-1.5 rounded-lg bg-[var(--surface-2)]"><span className="truncate" title={a}>{a}</span></div>
                  );
                  const TypeIcon = a.type === 'subscription' ? RefreshCw : a.type === 'boost' ? Star : a.type === 'catalog' ? Package : Server;
                  const money = (c, cur) => { const C = (cur || 'usd').toUpperCase(); const s = C === 'USD' ? '$' : C === 'EUR' ? '€' : C === 'GBP' ? '£' : ''; return s ? `${s}${(c / 100).toFixed(2)}` : `${(c / 100).toFixed(2)} ${C}`; };
                  const bits = [];
                  if (a.type === 'hosting' && a.specs) bits.push(`${a.specs.storageGB} GB · ${a.specs.uploadMbps} Mbps`);
                  if (a.type === 'boost' && a.featuredUntil) bits.push(`${t('pu.d.until', 'until')} ${since(a.featuredUntil)}`);
                  if (a.type === 'catalog') bits.push(`${a.kind || ''}${a.sizeMB != null ? ` · ${a.sizeMB} MB` : ''}`.trim());
                  if (a.type === 'subscription') { const per = a.intervalCount > 1 ? `/${a.intervalCount} ${a.interval}` : `/${a.interval}`; bits.push(`${money(a.amountCents, a.currency)} ${per}`); if (a.currentPeriodEnd) bits.push(`${t('bill.sub.renews', 'Renews {d}').replace('{d}', since(a.currentPeriodEnd))}`); }
                  if (a.status) bits.push(a.status);
                  if (a.deleteAt) bits.push(`${t('pu.d.deletes', 'deletes')} ${since(a.deleteAt)}`);
                  return (
                    <div key={i} className="flex items-start gap-2.5 text-sm px-3 py-2 rounded-lg bg-[var(--surface-2)]">
                      <TypeIcon size={14} className={`shrink-0 mt-0.5 ${a.paid ? 'text-success' : 'text-[var(--accent-ink)]'}`} />
                      <div className="flex-1 min-w-0">
                        <div className="flex items-center gap-2 flex-wrap">
                          <span className="font-medium truncate" title={a.name || a.label}>{a.name || a.label}</span>
                          <Badge tone={a.paid ? 'green' : ''}>{a.paid ? t('pu.d.paid', 'paid') : t('pu.d.free', 'free')}</Badge>
                          {a.repoId && <a href={`/repo/${a.repoId}`} target="_blank" rel="noreferrer" className="text-[var(--accent-ink)] hover:underline text-xs inline-flex items-center gap-0.5">{t('pu.d.open', 'open')} <ArrowUpRight size={11} /></a>}
                        </div>
                        {bits.length > 0 && <div className="text-xs text-[var(--faint)] mt-0.5">{bits.join(' · ')}</div>}
                        {a.spend && a.spend.spentCents > 0 && (
                          <div className="text-xs text-success mt-0.5">{money(a.spend.spentCents, a.spend.currency)} {t('pu.d.acrosspay', 'across {n} payment(s)').replace('{n}', a.spend.count)}{a.spend.lastAt ? ` · ${t('pu.last', 'last')} ${since(a.spend.lastAt)}` : ''}</div>
                        )}
                        {a.spend?.invoiceNos?.length > 0 && (
                          <div className="text-[11px] text-[var(--faint)] mt-0.5 flex items-center gap-1.5 flex-wrap"><Receipt size={10} className="shrink-0" /> {t('pu.d.invoices', 'Invoices:')}
                            {a.spend.invoiceNos.slice(-3).map((n) => (
                              <button key={n} onClick={(e) => { e.stopPropagation(); navigator.clipboard?.writeText(n); toast.success(t('common.copied', 'Copied.')); }} className="font-mono hover:text-[var(--accent-ink)]" title={t('common.copy', 'Copy')}>{n}</button>
                            ))}
                            {a.spend.invoiceNos.length > 3 && <span>+{a.spend.invoiceNos.length - 3}</span>}
                          </div>
                        )}
                        {a.type === 'subscription' && a.mrrCents > 0 && (
                          <div className="text-xs text-success mt-0.5">≈ {money(a.mrrCents, a.currency)} {t('pu.permo', 'per month')}</div>
                        )}
                      </div>
                    </div>
                  );
                })}
              </div>
            )}
          </Card>
          ); })}
        {hasMore && <div className="text-center pt-1"><Button variant="ghost" disabled={busy} onClick={() => load(true)}>{busy ? <Spinner /> : t('pu.loadmore', 'Load more')}</Button></div>}
      </div> : <EmptyState icon={tab === 'paying' ? CreditCard : tab === 'free' ? Gift : Archive} title={emptyCopy[0]}
        sub={qApplied ? t('pu.empty.filtered', 'No customer in this tab matches the search above.') : emptyCopy[1]}
        action={qApplied ? { label: t('pu.empty.clear', 'Clear the search'), icon: X, onClick: () => { setQ(''); setQApplied(''); } } : null} />}
      {detail && <UserDetailModal id={detail} onClose={() => setDetail(null)} />}
    </div>
  );
}

function PolicyChipList({ label, items, onAdd, onRemove, placeholder }) {
  const [v, setV] = useState('');
  const add = () => { const x = v.trim(); if (x) { onAdd(x); setV(''); } };
  return (
    <div>
      <div className="text-[11px] font-semibold uppercase tracking-wider text-[var(--faint)] mb-1">{label}</div>
      <div className="flex gap-1.5"><Input value={v} onChange={(e) => setV(e.target.value)} placeholder={placeholder} onKeyDown={(e) => e.key === 'Enter' && add()} /><Button size="sm" onClick={add}><Plus size={13} /></Button></div>
      <div className="flex flex-wrap gap-1 mt-1.5">
        {items.length ? items.map((x) => (
          <span key={x} className="inline-flex items-center gap-1 px-1.5 py-0.5 rounded-md bg-[var(--surface-2)] border border-[var(--line)] text-[11px]">{x}<button onClick={() => onRemove(x)} className="text-[var(--faint)] hover:text-error"><X size={10} /></button></span>
        )) : <span className="text-[11px] text-[var(--faint)]">{'—'}</span>}
      </div>
    </div>
  );
}

// Account entries ({type:"bcweb"|"discord", id, label}) — searches the same
// creator-id/Discord-id/username/display-name index as the "Find a user" box below.
function PolicyAccountChips({ label, items, onAdd, onRemove }) {
  const { t } = useI18n();
  const [q, setQ] = useState(''); const [results, setResults] = useState(null); const [busy, setBusy] = useState(false);
  const search = async () => {
    if (!q.trim()) return setResults(null);
    setBusy(true);
    try { const { users } = await api.get(`/admin/users?q=${encodeURIComponent(q)}&take=8`); setResults(users); } catch { setResults([]); } finally { setBusy(false); }
  };
  const has = (type, id) => items.some((a) => a.type === type && a.id === id);
  const add = (entry) => { if (!has(entry.type, entry.id)) onAdd(entry); };
  return (
    <div>
      <div className="text-[11px] font-semibold uppercase tracking-wider text-[var(--faint)] mb-1">{label}</div>
      <div className="flex gap-1.5">
        <Input value={q} onChange={(e) => setQ(e.target.value)} placeholder={t('gap.accsearch', 'id / display name / creator id / Discord…')} onKeyDown={(e) => e.key === 'Enter' && search()} />
        <Button size="sm" onClick={search}>{busy ? <Spinner /> : <Search size={13} />}</Button>
      </div>
      {results && (
        <div className="mt-1.5 space-y-1">
          {results.length ? results.map((u) => (
            <div key={u.id} className="flex items-center justify-between gap-2 px-2 py-1 rounded-md bg-[var(--surface-2)] border border-[var(--line)] text-[11px]">
              <span className="truncate">{u.displayName}{u.discord && <span className="text-[var(--faint)]"> · Discord: {u.discord.username || u.discord.id}</span>}</span>
              <span className="flex gap-1 shrink-0">
                <button onClick={() => add({ type: 'bcweb', id: u.id, label: u.displayName })} className="px-1.5 py-0.5 rounded border border-[var(--line)] hover:text-[var(--accent-ink)] hover:border-[var(--primary-2)]">+ BC</button>
                {u.discord && <button onClick={() => add({ type: 'discord', id: u.discord.id, label: u.discord.username || u.discord.id })} className="px-1.5 py-0.5 rounded border border-[var(--line)] hover:text-[var(--accent-ink)] hover:border-[var(--primary-2)]">+ Discord</button>}
              </span>
            </div>
          )) : <div className="text-[11px] text-[var(--faint)] px-1">{t('gap.noaccounts', 'No accounts found.')}</div>}
        </div>
      )}
      <div className="flex flex-wrap gap-1 mt-1.5">
        {items.length ? items.map((a) => (
          <span key={`${a.type}:${a.id}`} className="inline-flex items-center gap-1 px-1.5 py-0.5 rounded-md bg-[var(--surface-2)] border border-[var(--line)] text-[11px]">
            <Users size={9} className="text-[var(--faint)]" /> {a.type === 'discord' ? 'Discord: ' : ''}{a.label || a.id}
            <button onClick={() => onRemove(a)} className="text-[var(--faint)] hover:text-error"><X size={10} /></button>
          </span>
        )) : <span className="text-[11px] text-[var(--faint)]">{'—'}</span>}
      </div>
    </div>
  );
}

// Site-wide whitelist/blacklist applied identically to every hosted repo (see
// GlobalAccessPolicy in schema.prisma + hosting-content.mjs's sandboxGate). MOD can
// see it (GET is MOD+); only ADMIN+ can change it (PUT enforces that server-side).
// Who is kept out of EVERY service — the API, the site, the hosted repos, the bot's
// webhooks — by address, by client, by BMM creator id; and the shield that blocks an address
// on its own after it has been rate-limited too often. The repo access policy above is per
// hosted content; this one is the front door.
function SiteBansCard() {
  const { t } = useI18n(); const toast = useToast();
  const { data, loading, reload } = useAsync(() => api.get('/admin/security/bans'), []);
  const [raw, setRaw] = useState(null);
  const [shield, setShield] = useState(null);
  const [busy, setBusy] = useState(false);
  const [nowIp, setNowIp] = useState('');
  const lines = (arr) => (arr || []).map((e) => [e.v, e.note ? `# ${e.note}` : ''].filter(Boolean).join('  ')).join('\n');
  useEffect(() => { if (data?.policy) { setRaw({ ips: lines(data.policy.ips), uas: lines(data.policy.uas), creators: lines(data.policy.creators) }); setShield({ ...data.policy.shield }); } }, [data]); // eslint-disable-line
  if (loading || !raw || !shield) return null;
  const parse = (txt) => String(txt || '').split('\n').map((l) => l.trim()).filter(Boolean).map((l) => { const i = l.indexOf('#'); const v = (i >= 0 ? l.slice(0, i) : l).trim(); const note = i >= 0 ? l.slice(i + 1).trim() : ''; return { v, note }; }).filter((e) => e.v);
  const save = async () => {
    setBusy(true);
    try { await api.put('/admin/security/bans', { ips: parse(raw.ips), uas: parse(raw.uas), creators: parse(raw.creators), shield }); toast.success(t('bans.saved', 'Bans saved, live within 15 s.')); reload(); }
    catch { toast.error(t('common.failed', 'Failed.')); } finally { setBusy(false); }
  };
  const lift = async (ip) => { try { await api.del(`/admin/security/bans/live/${encodeURIComponent(ip)}`); reload(); } catch { toast.error(t('common.failed', 'Failed.')); } };
  const blockNow = async () => { if (!nowIp.trim()) return; try { await api.post('/admin/security/bans/live', { ip: nowIp.trim(), minutes: shield.minutes || 30 }); setNowIp(''); reload(); } catch { toast.error(t('common.failed', 'Failed.')); } };
  const ta = 'w-full font-mono text-xs rounded-lg border border-[var(--line)] bg-[var(--surface-2)] p-2 min-h-[96px] outline-none focus:border-[var(--primary)]';
  const live = data?.live || [];
  return (
    <Card className="p-5">
      <div className="flex items-start justify-between gap-3 flex-wrap mb-1">
        <div>
          <h2 className="font-semibold flex items-center gap-2"><Ban size={16} className="text-error" /> {t('bans.title', 'Bans & shield')}</h2>
          <p className="text-sm text-[var(--muted)] max-w-2xl">{t('bans.desc', 'Kept out of every service: the site, the API, hosted repos, the bot’s endpoints. One entry per line; a note after #. Applies within 15 seconds, no restart.')}</p>
        </div>
        <Button size="sm" variant="primary" disabled={busy} onClick={save}>{busy ? <Spinner /> : <><Save size={14} /> {t('common.save', 'Save')}</>}</Button>
      </div>
      <div className="grid md:grid-cols-3 gap-3 mt-3">
        <div>
          <div className="text-[11px] font-semibold uppercase tracking-wider text-[var(--faint)] mb-1">{t('bans.ips', 'IP addresses & ranges')}</div>
          <textarea className={ta} value={raw.ips} onChange={(e) => setRaw((r) => ({ ...r, ips: e.target.value }))} placeholder={'203.0.113.7  # scraper\n198.51.100.0/24\n2001:db8::/32'} spellCheck={false} />
        </div>
        <div>
          <div className="text-[11px] font-semibold uppercase tracking-wider text-[var(--faint)] mb-1">{t('bans.uas', 'User agents (contains)')}</div>
          <textarea className={ta} value={raw.uas} onChange={(e) => setRaw((r) => ({ ...r, uas: e.target.value }))} placeholder={'EvilBot/1.0\ncurl/7.  # a script hammering the feed'} spellCheck={false} />
        </div>
        <div>
          <div className="text-[11px] font-semibold uppercase tracking-wider text-[var(--faint)] mb-1">{t('bans.creators', 'BMM creator ids')}</div>
          <textarea className={ta} value={raw.creators} onChange={(e) => setRaw((r) => ({ ...r, creators: e.target.value }))} placeholder={'bc_9f2e…  # X-Creator-ID header'} spellCheck={false} />
        </div>
      </div>
      <div className="grid md:grid-cols-[minmax(0,1fr)_minmax(0,1fr)] gap-3 mt-4">
        <div className="rounded-xl border border-[var(--line)] p-3">
          <div className="flex items-center justify-between gap-2 mb-2">
            <div className="text-[11px] font-semibold uppercase tracking-wider text-[var(--faint)] flex items-center gap-1.5"><Shield size={12} /> {t('bans.shield', 'Automatic shield')}</div>
            <label className="flex items-center gap-1.5 text-xs cursor-pointer"><input type="checkbox" className="accent-[var(--primary)]" checked={shield.enabled !== false} onChange={(e) => setShield((x) => ({ ...x, enabled: e.target.checked }))} /> {t('common.enabled', 'Enabled')}</label>
          </div>
          <p className="text-[11px] text-[var(--muted)] mb-2">{t('bans.shield.d', 'An address that gets rate-limited this many times in ten minutes is blocked outright for a while — cheaper than answering it. Known scanners and attack tools are already refused before this.')}</p>
          <div className="grid grid-cols-2 gap-2">
            <Field label={t('bans.after429', 'Block after N rate-limits')} className="!mb-0"><Input type="number" min="0" max="100000" value={shield.after429 ?? 30} onChange={(e) => setShield((x) => ({ ...x, after429: Math.max(0, Number(e.target.value) || 0) }))} /></Field>
            <Field label={t('bans.minutes', 'For (minutes)')} className="!mb-0"><Input type="number" min="1" max="10080" value={shield.minutes ?? 30} onChange={(e) => setShield((x) => ({ ...x, minutes: Math.max(1, Number(e.target.value) || 1) }))} /></Field>
          </div>
          <label className="flex items-center gap-1.5 text-xs cursor-pointer mt-2"><input type="checkbox" className="accent-[var(--primary)]" checked={!!shield.blockNoUA} onChange={(e) => setShield((x) => ({ ...x, blockNoUA: e.target.checked }))} /> {t('bans.noua', 'Refuse page requests that send no User-Agent at all')}</label>
          <div className="text-[11px] text-[var(--faint)] mt-2 leading-snug">{t('bans.ddos', 'This is the application layer. A volumetric flood has to be absorbed BEFORE it reaches the server — a CDN / DDoS front (Cloudflare, the VPS provider’s protection) — and Caddy’s connection limits sit between the two.')}</div>
        </div>
        <div className="rounded-xl border border-[var(--line)] p-3">
          <div className="text-[11px] font-semibold uppercase tracking-wider text-[var(--faint)] mb-2">{t('bans.live', 'Blocked right now')} <span className="font-normal normal-case text-[var(--muted)]">· {live.length}</span></div>
          <div className="flex gap-1.5 mb-2">
            <Input className="!py-1 text-xs font-mono flex-1" placeholder="203.0.113.7" value={nowIp} onChange={(e) => setNowIp(e.target.value)} onKeyDown={(e) => { if (e.key === 'Enter') blockNow(); }} />
            <Button size="sm" onClick={blockNow}><Ban size={13} /> {t('bans.blocknow', 'Block now')}</Button>
          </div>
          {live.length === 0 ? <div className="text-xs text-[var(--faint)]">{t('bans.live.none', 'Nobody, the shield has not had to fire.')}</div> : (
            <div className="space-y-1 max-h-48 overflow-auto">
              {live.map((b) => (
                <div key={b.ip} className="flex items-center gap-2 text-xs rounded-lg bg-[var(--surface-2)] px-2 py-1">
                  <code className="font-mono flex-1 min-w-0 truncate" title={b.ip}>{b.ip}</code>
                  <span className="text-[var(--faint)]">{b.reason}</span>
                  <span className="text-[var(--faint)] tabular-nums">{Math.max(0, Math.round((b.until - Date.now()) / 60000))} min</span>
                  <button type="button" onClick={() => lift(b.ip)} className="text-[var(--accent-ink)] hover:underline">{t('bans.lift', 'Lift')}</button>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    </Card>
  );
}

function GlobalAccessPolicyCard() {
  const toast = useToast();
  const { t } = useI18n();
  const { data, loading, reload } = useAsync(() => api.get('/admin/access-policy'), []);
  const [policy, setPolicy] = useState(null);
  const [busy, setBusy] = useState(false);
  useEffect(() => { if (data?.policy && !policy) setPolicy(data.policy); /* eslint-disable-next-line */ }, [data]);

  // ABOVE the loading guard: useUndoableSave calls useToast() and useI18n(), so placing it
  // below meant one hook count on the loading render and a larger one once the data
  // arrived — React error #310. Found by check-undefined-jsx, not by anyone using it.
  const undoSave = useUndoableSave(reload);
  if (!policy) return <Card className="p-5">{loading ? <Loading /> : null}</Card>;

  const addTo = (field, val) => setPolicy((s) => ({ ...s, [field]: [...new Set([...(s[field] || []), val])] }));
  const rm = (field, val) => setPolicy((s) => ({ ...s, [field]: (s[field] || []).filter((x) => x !== val) }));
  const addAccount = (field, entry) => setPolicy((s) => {
    const list = s[field] || [];
    if (list.some((a) => a.type === entry.type && a.id === entry.id)) return s;
    return { ...s, [field]: [...list, entry] };
  });
  const rmAccount = (field, entry) => setPolicy((s) => ({ ...s, [field]: (s[field] || []).filter((a) => !(a.type === entry.type && a.id === entry.id)) }));

  const save = () => {
    setBusy(true);
    undoSave(() => api.put('/admin/access-policy', policy),
      t('gap.saved', 'Global access policy saved.'),
      { onSettled: () => setBusy(false), errorFor: () => t('gap.savefail', 'Failed to save.') });
  };

  return (
    <Card className="p-5 space-y-4">
      <div>
        <h2 className="font-semibold mb-1 flex items-center gap-2"><Globe size={16} className="text-[var(--accent-ink)]" /> {t('gap.title', 'Global access policy')}</h2>
        <p className="text-sm text-[var(--muted)]">{t('gap.desc', "Applied identically to every hosted repo, on top of each owner's own settings — a ban here blocks a client everywhere; the whitelist here is added to whichever repos require one.")}</p>
      </div>
      <label className="flex items-center gap-2 text-sm"><input type="checkbox" checked={policy.whitelistOnly} onChange={(e) => setPolicy({ ...policy, whitelistOnly: e.target.checked })} /> {t('gap.wlonly', 'Whitelist-only for ALL repos (forces every hosted repo into whitelist mode, site-wide)')}</label>
      <div className="grid sm:grid-cols-2 gap-4">
        <div className="space-y-3">
          <div className="text-xs font-semibold uppercase tracking-wider text-[var(--faint)] flex items-center gap-1.5"><Shield size={12} className="text-success" /> {t('gap.whitelist', 'Whitelist')}</div>
          <PolicyChipList label={t('gap.ips', 'IPs')} items={policy.whitelistIps || []} onAdd={(v) => addTo('whitelistIps', v)} onRemove={(v) => rm('whitelistIps', v)} placeholder="203.0.113.4" />
          <PolicyChipList label={t('gap.creatorid', 'Creator ID')} items={policy.whitelistKeys || []} onAdd={(v) => addTo('whitelistKeys', v)} onRemove={(v) => rm('whitelistKeys', v)} placeholder="BMM creator id…" />
          <PolicyAccountChips label={t('gap.accounts', 'Accounts')} items={policy.whitelistAccounts || []} onAdd={(e) => addAccount('whitelistAccounts', e)} onRemove={(e) => rmAccount('whitelistAccounts', e)} />
        </div>
        <div className="space-y-3">
          <div className="text-xs font-semibold uppercase tracking-wider text-[var(--faint)] flex items-center gap-1.5"><Ban size={12} className="text-error" /> {t('gap.blacklist', 'Blacklist')}</div>
          <PolicyChipList label={t('gap.ips', 'IPs')} items={policy.bannedIps || []} onAdd={(v) => addTo('bannedIps', v)} onRemove={(v) => rm('bannedIps', v)} placeholder="198.51.100.7" />
          <PolicyChipList label={t('gap.creatorid', 'Creator ID')} items={policy.bannedKeys || []} onAdd={(v) => addTo('bannedKeys', v)} onRemove={(v) => rm('bannedKeys', v)} placeholder="BMM creator id…" />
          <PolicyAccountChips label={t('gap.accounts', 'Accounts')} items={policy.bannedAccounts || []} onAdd={(e) => addAccount('bannedAccounts', e)} onRemove={(e) => rmAccount('bannedAccounts', e)} />
        </div>
      </div>
      <div className="flex justify-end"><Button variant="primary" disabled={busy} onClick={save}>{busy ? <Spinner /> : t('gap.save', 'Save global policy')}</Button></div>
    </Card>
  );
}

// Admin (+SuperAdmin): grant/revoke blog-post permissions (any ADMIN+), and — only
// for a SUPERADMIN — reassign a user's role. Kept in one screen since both are
// "who can do what" access-control actions.
// Login attempts (success/fail, IP, which account) + the admin/staff audit trail
// (role changes, access-policy edits, server-control grants/elevations).
const SECURITY_RANGES = [['24', '24h'], ['168', '7d'], ['720', '30d'], ['8760', '1y']];
// A failed-login IP is flagged once it's tried 5+ times in the loaded window —
// a cheap, no-config heuristic to surface likely brute-force/credential-stuffing
// activity without needing a real rate-limiting/ban system here.
const BRUTE_FORCE_THRESHOLD = 5;

// One audit entry, opened.
//
// The list is a summary by necessity — 300 characters of detail truncated to a line, no
// hash, no neighbours. Every question that starts "but what exactly…" needed the database
// until this existed. The chain state is shown per row here, because "the log verifies" is a
// statement about the whole log and an investigator is looking at ONE row.
function AuditDetail({ id, onClose, onPickActor }) {
  const { t } = useI18n();
  const d = useAsync(() => (id ? api.get(`/admin/security/audit/entry/${id}`) : Promise.resolve(null)), [id]);
  const e = d.data?.entry;
  const row = (label, value, mono) => (
    <div className="grid grid-cols-1 sm:grid-cols-[130px_minmax(0,1fr)] gap-1 sm:gap-3 py-1.5 border-b border-[var(--line)] last:border-0">
      <div className="text-xs text-[var(--faint)] pt-0.5">{label}</div>
      <div className={`text-sm min-w-0 break-words ${mono ? 'font-mono text-[11.5px]' : ''}`}>{value}</div>
    </div>
  );
  // Three separate claims, each shown only when it MEANS something. A legacy row has no
  // signature, and reporting "not verified" for it would read as tampering.
  const flag = (ok, yes, no, nul) => ok === null || ok === undefined
    ? <Badge>{nul}</Badge>
    : ok ? <Badge tone="green" className="inline-flex items-center gap-1"><CheckCircle2 size={11} /> {yes}</Badge>
         : <Badge tone="red" className="inline-flex items-center gap-1"><AlertTriangle size={11} /> {no}</Badge>;
  return (
    <Modal open={!!id} onClose={onClose} title={t('sec.detail.title', 'Audit entry')} icon={Shield} width="max-w-2xl">
      {d.loading ? <Loading /> : !e ? <EmptyState icon={Shield} title={t('sec.detail.gone', 'Entry not found')} /> : (
        <div>
          <div className="mb-3 flex flex-wrap items-center gap-2">
            <Badge tone="blue" className="font-mono">{e.action}</Badge>
            {d.data.anchored && <Badge tone={d.data.anchorMatches ? 'green' : 'red'} className="inline-flex items-center gap-1"><Fingerprint size={11} /> {t('sec.detail.anchored', 'Anchored off-DB')}</Badge>}
            {!d.data.signed && <Badge>{t('sec.detail.legacy', 'Unsigned (pre-chain)')}</Badge>}
          </div>
          {row(t('sec.detail.when', 'When'), new Date(e.createdAt).toLocaleString())}
          {row(t('sec.detail.actor', 'Actor'), e.actor
            ? <button onClick={() => { onPickActor?.(e.actor.id); onClose(); }} className="hover:text-[var(--accent-ink)] text-start">
                {e.actor.displayName} <span className="text-xs text-[var(--faint)]">({e.actor.role})</span>
              </button>
            : '—')}
          {row(t('sec.detail.detail', 'Detail'), e.detail || <span className="text-[var(--faint)]">—</span>)}
          {row('IP', e.ip || <span className="text-[var(--faint)]">—</span>, true)}
          {row(t('sec.detail.id', 'Entry id'), <span className="inline-flex items-center gap-2">{e.id}<button onClick={() => copyText(e.id)} className="text-[var(--faint)] hover:text-[var(--accent-ink)]"><Copy size={12} /></button></span>, true)}
          {d.data.signed && <>
            {row(t('sec.detail.sig', 'Signature'), flag(d.data.hmacOk, t('sec.detail.sigok', 'Matches its contents'), t('sec.detail.signo', 'Contents altered'), t('sec.detail.legacy', 'Unsigned (pre-chain)')))}
            {row(t('sec.detail.link', 'Link to previous'), flag(d.data.linkOk, t('sec.detail.linkok', 'Continuous'), t('sec.detail.linkno', 'Broken'), t('sec.detail.linkfirst', 'First retained entry')))}
            {row(t('sec.detail.linkn', 'Link from next'), flag(d.data.nextLinkOk, t('sec.detail.linkok', 'Continuous'), t('sec.detail.linkno', 'Broken'), t('sec.detail.linklast', 'Newest entry')))}
            {row(t('sec.detail.hash', 'Hash'), e.hash, true)}
            {row(t('sec.detail.prev', 'Previous hash'), e.prevHash || 'GENESIS', true)}
          </>}
        </div>
      )}
    </Modal>
  );
}

// The quick ranges, and the two that are not ranges: a custom window, and the whole log.
const AUDIT_QUICK = [['24', '24h'], ['168', '7d'], ['720', '30d'], ['8760', '1y']];

/**
 * A day, as a heading.
 *
 * Two hundred rows of "16/09/2026 21:04:11" is a list with no shape: every row is the same
 * width of the same grey, the date repeats a hundred times, and finding "what happened on
 * Tuesday" means reading. Grouping by day costs one sticky line per day and turns scrolling
 * into navigation. The heading is sticky rather than inline because the question it answers,
 * "which day am I looking at", is asked in the middle of a group, not at its top.
 */
function DayHeading({ at, count }) {
  const { t } = useI18n();
  const d = new Date(at);
  const today = new Date();
  const same = (a, b) => a.toDateString() === b.toDateString();
  const yest = new Date(today.getTime() - 864e5);
  const label = same(d, today) ? t('log.today', 'Today') : same(d, yest) ? t('log.yesterday', 'Yesterday')
    : d.toLocaleDateString(undefined, { weekday: 'short', day: 'numeric', month: 'short', year: d.getFullYear() === today.getFullYear() ? undefined : 'numeric' });
  return (
    <div className="sticky top-0 z-10 px-4 py-1.5 bg-[var(--bg-solid)] border-b border-[var(--line)] flex items-center gap-2">
      <span className="text-[11px] font-semibold uppercase tracking-wider text-[var(--faint)]">{label}</span>
      {count != null && <span className="text-[11px] text-[var(--faint)] tabular-nums">· {count}</span>}
    </div>
  );
}

/** Rows, cut into days. Returns [{ day, at, rows }] in the order it was given. */
function byDay(rows, at = (r) => r.createdAt) {
  const out = [];
  for (const r of rows) {
    const key = new Date(at(r)).toDateString();
    const last = out[out.length - 1];
    if (last && last.day === key) last.rows.push(r);
    else out.push({ day: key, at: at(r), rows: [r] });
  }
  return out;
}

/** The clock time, with the full stamp one hover away. A date inside a day group is noise. */
function LogTime({ at }) {
  const d = new Date(at);
  return (
    <time dateTime={d.toISOString()} title={d.toLocaleString()}
      className="text-[11px] text-[var(--faint)] tabular-nums shrink-0">
      {d.toLocaleTimeString(undefined, { hour: '2-digit', minute: '2-digit', second: '2-digit' })}
    </time>
  );
}

function AdminSecurity() {
  const { t } = useI18n();
  const toast = useToast();
  const dialog = useDialog();
  const [tab, setTab] = useState('logins');
  const [q, setQ] = useState('');
  const [loginFilter, setLoginFilter] = useState('all'); // all | success | failed | suspicious
  const [hours, setHours] = useState('168');
  // The audit tab's own filters. Held apart from `hours` because a date range and a rolling
  // window are different questions and one must not silently override the other.
  const [from, setFrom] = useState('');
  const [to, setTo] = useState('');
  const [action, setAction] = useState('');
  const [actorId, setActorId] = useState('');
  const [page, setPage] = useState(0);
  const [openId, setOpenId] = useState(null);
  const PAGE = 200;
  // Typing in the box must not fire a query per keystroke now that the search runs on the
  // server. 300ms is the pause that reads as "I have finished typing".
  const [qDebounced, setQDebounced] = useState('');
  useEffect(() => { const h = setTimeout(() => setQDebounced(q), 300); return () => clearTimeout(h); }, [q]);
  useEffect(() => { setPage(0); }, [qDebounced, from, to, action, actorId, hours, tab]);

  const logins = useAsync(() => api.get(`/admin/security/logins?hours=${hours}`), [hours]);
  const auditQs = new URLSearchParams();
  if (from) auditQs.set('from', new Date(from).toISOString());
  if (to) auditQs.set('to', new Date(to).toISOString());
  if (!from && !to) auditQs.set('hours', hours);
  if (action) auditQs.set('action', action);
  if (actorId) auditQs.set('actorId', actorId);
  if (qDebounced) auditQs.set('q', qDebounced);
  auditQs.set('take', String(PAGE));
  auditQs.set('skip', String(page * PAGE));
  const auditKey = auditQs.toString();
  const audit = useAsync(() => api.get(`/admin/security/audit?${auditKey}`), [auditKey]);
  const facets = useAsync(() => api.get('/admin/security/audit/facets'), []);
  const [verify, setVerify] = useState(null); // null | 'checking' | { ok, …, sinceBreak }
  const runVerify = async () => { setVerify('checking'); try { setVerify(await api.get('/admin/security/audit/verify')); } catch { setVerify({ error: true }); } };
  // Repair, in the order it has to happen. `evidenceDone` is what unlocks re-sealing on this
  // screen, and the API enforces the same rule against the log rather than trusting this flag.
  const [busyTool, setBusyTool] = useState('');
  const [evidenceDone, setEvidenceDone] = useState(false);
  const exportEvidence = async () => {
    setBusyTool('evidence');
    try {
      const bundle = await api.get('/admin/security/audit/evidence');
      // Saved by the browser, not shown: this is the artefact, and reading it on the screen of
      // the machine it accuses is not the point of taking it off that machine.
      const blob = new Blob([JSON.stringify(bundle, null, 2)], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url; a.download = `audit-evidence-${new Date().toISOString().slice(0, 19).replace(/[:T]/g, '')}.json`;
      document.body.appendChild(a); a.click(); a.remove();
      setTimeout(() => URL.revokeObjectURL(url), 4000);
      setEvidenceDone(true);
      toast.success(t('sec.tool.exported', 'Evidence exported. Keep it somewhere this server cannot reach.'));
    } catch { toast.error(t('common.failed', 'Failed.')); }
    finally { setBusyTool(''); }
  };
  const anchorHead = async () => {
    setBusyTool('anchor');
    try { await api.post('/admin/security/audit/anchor', {}); toast.success(t('sec.tool.anchored', 'Head anchored outside the database.')); runVerify(); }
    catch (e) { toast.error(e?.body?.error === 'no_signed_head' ? t('sec.tool.nohead', 'Nothing signed to anchor yet.') : t('common.failed', 'Failed.')); }
    finally { setBusyTool(''); }
  };
  const reseal = async () => {
    const ok = await dialog.confirm({
      title: t('sec.tool.reseal.t', 'Re-sign the log from the break?'),
      body: t('sec.tool.reseal.b', 'This makes the chain verify again and makes the NEXT alteration detectable. It does not make the re-signed entries trustworthy — their content is whatever the database holds now — and it overwrites the evidence that the break was ever there. Export the bundle first.'),
      confirmText: t('sec.tool.reseal.go', 'Re-sign'),
      danger: true,
    });
    if (!ok) return;
    setBusyTool('reseal');
    try {
      const r = await api.post('/admin/security/audit/reseal', { confirmToken: 'CONFIRM' });
      toast.success(`${t('sec.tool.resealed', 'Re-signed')} ${r.resealed}`);
      runVerify();
    } catch (e) {
      const code = e?.body?.error;
      toast.error(code === 'export_evidence_first' ? t('sec.tool.needexport', 'Export the evidence bundle first, re-sealing destroys it.')
        : code === 'nothing_to_reseal' ? t('sec.tool.nobreak', 'The chain verifies. Nothing to re-sign.')
        : t('common.failed', 'Failed.'));
    }
    finally { setBusyTool(''); }
  };
  const attempts = logins.data?.attempts || [];
  const entries = audit.data?.entries || [];
  const total = audit.data?.total || 0;

  const failsByIp = {};
  for (const a of attempts) if (!a.success) failsByIp[a.ip] = (failsByIp[a.ip] || 0) + 1;
  const suspiciousIps = new Set(Object.entries(failsByIp).filter(([, n]) => n >= BRUTE_FORCE_THRESHOLD).map(([ip]) => ip));

  const qLower = q.trim().toLowerCase();
  const filteredAttempts = attempts.filter((a) => {
    if (loginFilter === 'success' && !a.success) return false;
    if (loginFilter === 'failed' && a.success) return false;
    if (loginFilter === 'suspicious' && !suspiciousIps.has(a.ip)) return false;
    if (!qLower) return true;
    return a.email.toLowerCase().includes(qLower) || a.ip.includes(qLower) || a.user?.displayName?.toLowerCase().includes(qLower);
  });

  const failedCount = attempts.filter((a) => !a.success).length;
  const uniqueIps = new Set(attempts.map((a) => a.ip)).size;
  const filtersOn = !!(from || to || action || actorId || qDebounced);
  const clearFilters = () => { setFrom(''); setTo(''); setAction(''); setActorId(''); setQ(''); };

  const exportCsv = (rowsArr, cols, name) => {
    if (!rowsArr.length) return;
    downloadCsv(toCsv(rowsArr, cols), name);
  };

  return (
    <div>
      <h2 className="font-semibold mb-1 flex items-center gap-2"><Lock size={16} className="text-[var(--accent-ink)]" /> {t('sec.title', 'Security log')}</h2>
      <SettingsPointer className="mb-3" keys={['audit.maxDays', 'audit.maxEntries']}>{t('sec.ptr', 'How long this log is kept, and how many entries')}</SettingsPointer>
      <p className="text-sm text-[var(--muted)] mb-3">{t('sec.desc', 'Login attempts (success/fail, IP) and the admin action audit trail.')}</p>

      <div className="grid grid-cols-2 sm:grid-cols-4 gap-3 mb-3">
        <Card className="p-3"><div className="text-[var(--faint)] text-xs mb-1">{t('sec.attempts', 'Attempts')}</div><div className="text-xl font-bold tabular-nums">{attempts.length}</div></Card>
        <Card className="p-3"><div className="text-[var(--faint)] text-xs mb-1">{t('sec.failedn', 'Failed')}</div><div className="text-xl font-bold tabular-nums text-error">{failedCount}</div></Card>
        <Card className="p-3"><div className="text-[var(--faint)] text-xs mb-1">{t('sec.uniqueips', 'Unique IPs')}</div><div className="text-xl font-bold tabular-nums">{uniqueIps}</div></Card>
        <Card className="p-3"><div className="text-[var(--faint)] text-xs mb-1 flex items-center gap-1"><AlertTriangle size={11} className={suspiciousIps.size ? 'text-error' : ''} /> {t('sec.suspicious', 'Suspicious IPs')}</div><div className={`text-xl font-bold tabular-nums ${suspiciousIps.size ? 'text-error' : ''}`}>{suspiciousIps.size}</div></Card>
      </div>

      <div className="flex items-center justify-between flex-wrap gap-2 mb-3">
        <div className="seg-rail p-0.5 gap-0.5">
          <button onClick={() => setTab('logins')} className={`px-3 py-1.5 rounded-[10px] text-sm transition ${tab === 'logins' ? 'bg-[var(--bg-solid)] text-[var(--accent-ink)] shadow-sm font-medium' : 'text-[var(--muted)] hover:text-[var(--text)]'}`}>{t('sec.tab.logins', 'Login attempts')}</button>
          <button onClick={() => setTab('audit')} className={`px-3 py-1.5 rounded-[10px] text-sm transition ${tab === 'audit' ? 'bg-[var(--bg-solid)] text-[var(--accent-ink)] shadow-sm font-medium' : 'text-[var(--muted)] hover:text-[var(--text)]'}`}>{t('sec.tab.audit', 'Admin audit trail')}</button>
        </div>
        {/* The quick ranges are what the DATE fields are a refinement of, so they go dim
            rather than disappear once a range is typed — a control that vanishes when you
            use its neighbour reads as a bug. */}
        <div className={`seg-rail p-0.5 gap-0.5 ${tab === 'audit' && (from || to) ? 'opacity-40' : ''}`}>
          {(tab === 'audit' ? AUDIT_QUICK : SECURITY_RANGES).map(([h, label]) => (
            <button key={h} onClick={() => { setHours(h); if (tab === 'audit') { setFrom(''); setTo(''); } }} className={`px-2.5 py-1 rounded-[10px] text-xs transition ${hours === h ? 'bg-[var(--bg-solid)] text-[var(--accent-ink)] shadow-sm font-medium' : 'text-[var(--faint)] hover:text-[var(--text)]'}`}>{label}</button>
          ))}
        </div>
      </div>

      <div className="flex flex-wrap gap-2 mb-3">
        <div className="relative flex-1 min-w-[200px]"><Search size={15} className="absolute left-3 top-1/2 -translate-y-1/2 text-[var(--faint)] pointer-events-none" />
          <Input className="!ps-9" placeholder={tab === 'logins' ? t('sec.search.logins', 'Search email, IP or account…') : t('sec.search.audit', 'Search actor, action, detail or IP…')} value={q} onChange={(e) => setQ(e.target.value)} /></div>
        {tab === 'logins' && (
          <Select className="!w-auto" value={loginFilter} onChange={(e) => setLoginFilter(e.target.value)}>
            <option value="all">{t('sec.f.all', 'All outcomes')}</option><option value="success">{t('sec.f.success', 'Success only')}</option><option value="failed">{t('sec.f.failed', 'Failed only')}</option><option value="suspicious">{t('sec.f.suspicious', 'Suspicious IPs only')}</option>
          </Select>
        )}
        <Button size="sm" onClick={() => tab === 'logins'
          ? exportCsv(filteredAttempts, [['email', (a) => a.email], ['success', (a) => a.success], ['ip', (a) => a.ip], ['reason', (a) => a.reason], ['createdAt', (a) => a.createdAt]], 'login_attempts')
          : exportCsv(entries, [['actor', (e) => e.actor?.displayName], ['action', (e) => e.action], ['detail', (e) => e.detail], ['ip', (e) => e.ip], ['createdAt', (e) => e.createdAt], ['id', (e) => e.id], ['hash', (e) => e.hash]], 'audit_trail')}>
          <Download size={13} /> CSV
        </Button>
      </div>

      {/* The audit filter row. Dates first, because an investigation starts from one. */}
      {tab === 'audit' && (
        <Card className="p-3 mb-3">
          <div className="flex flex-wrap items-end gap-3">
            <div className="min-w-[170px]">
              <div className="text-[11px] text-[var(--faint)] mb-1">{t('sec.f.from', 'From')}</div>
              <Input type="datetime-local" value={from} onChange={(e) => setFrom(e.target.value)} />
            </div>
            <div className="min-w-[170px]">
              <div className="text-[11px] text-[var(--faint)] mb-1">{t('sec.f.to', 'To')}</div>
              <Input type="datetime-local" value={to} onChange={(e) => setTo(e.target.value)} />
            </div>
            <div className="min-w-[190px] flex-1">
              <div className="text-[11px] text-[var(--faint)] mb-1">{t('sec.f.action', 'Action')}</div>
              <Select value={action} onChange={(e) => setAction(e.target.value)}>
                <option value="">{t('sec.f.anyaction', 'Any action')}</option>
                {(facets.data?.families || []).map((f) => <option key={f.family} value={f.family}>{f.family}* ({f.count})</option>)}
                <option disabled>──────────</option>
                {(facets.data?.actions || []).map((a) => <option key={a.action} value={a.action}>{a.action} ({a.count})</option>)}
              </Select>
            </div>
            <div className="min-w-[190px] flex-1">
              <div className="text-[11px] text-[var(--faint)] mb-1">{t('sec.f.actor', 'Actor')}</div>
              <Select value={actorId} onChange={(e) => setActorId(e.target.value)}>
                <option value="">{t('sec.f.anyactor', 'Anyone')}</option>
                {(facets.data?.actors || []).map((a) => <option key={a.id} value={a.id}>{a.displayName || a.id} ({a.count})</option>)}
              </Select>
            </div>
            {filtersOn && <Button size="sm" variant="ghost" onClick={clearFilters}><X size={13} /> {t('sec.f.clear', 'Clear')}</Button>}
          </div>
          {/* What the numbers on screen are actually counting. Without this line a filtered
              view and an unfiltered one look identical, and the reader takes the second for
              the first. */}
          <div className="text-[11px] text-[var(--faint)] mt-2">
            {/* `t(key, fallback)` takes no values — there is no interpolation in this
                dictionary, so a "{n}" inside a string reaches the reader as "{n}". Numbers
                are composed around the phrase instead. */}
            {total} {t('sec.f.count', 'matching entries')}
            {facets.data?.oldest ? ` · ${t('sec.f.oldest', 'log starts')} ${new Date(facets.data.oldest).toLocaleDateString()}` : ''}
          </div>
        </Card>
      )}

      {tab === 'logins' && (logins.loading ? <Loading /> : filteredAttempts.length ? <Card className="p-0 overflow-hidden">
        <div className="max-h-[65vh] overflow-auto">
          {byDay(filteredAttempts).map((g) => (
            <div key={g.day}>
              <DayHeading at={g.at} count={g.rows.length} />
              <div className="divide-y divide-[var(--line)]">
                {g.rows.map((a) => (
                  <div key={a.id} className="flex items-start gap-3 px-4 py-2.5 text-sm">
                    {a.success ? <CheckCircle2 size={15} className="text-success shrink-0 mt-0.5" /> : <XCircle size={15} className="text-error shrink-0 mt-0.5" />}
                    <div className="flex-1 min-w-0">
                      {/* The address wraps rather than truncating: an email is the thing you
                          came to read, and half of one identifies nobody. */}
                      <div className="flex items-center gap-1.5 flex-wrap">
                        <button onClick={() => setQ(a.email)} className="font-medium hover:text-[var(--accent-ink)] break-all text-start">{a.email}</button>
                        {a.user && <span className="text-xs text-[var(--faint)]">· {a.user.displayName} ({a.user.role})</span>}
                        {suspiciousIps.has(a.ip) && <Badge tone="red">{t('sec.bruteforce', 'Brute-force?')}</Badge>}
                      </div>
                      <div className="text-[11px] text-[var(--faint)] font-mono flex items-center gap-1.5 flex-wrap">
                        <button onClick={() => setQ(a.ip)} className="hover:text-[var(--accent-ink)]">{a.ip}</button>
                        {a.reason ? <span>· {a.reason}</span> : null}
                        {/* On a phone the time rides with the detail line instead of
                            competing with the address for the same 360px. */}
                        <span className="sm:hidden">· <LogTime at={a.createdAt} /></span>
                      </div>
                    </div>
                    <span className="hidden sm:block"><LogTime at={a.createdAt} /></span>
                  </div>
                ))}
              </div>
            </div>
          ))}
        </div>
      </Card> : <EmptyState icon={Lock} title={attempts.length ? t('sec.nomatch', 'No matches') : t('sec.none.logins', 'No login attempts in this range')}
        sub={attempts.length ? t('sec.nomatch.logins.s', 'The outcome filter and the search box hide every attempt recorded in this range.') : t('sec.none.logins.s', 'Nobody tried to sign in during the window selected above. Widen it to look further back.')}
        action={attempts.length ? { label: t('sec.nomatch.clear', 'Show every attempt'), icon: X, onClick: () => { setLoginFilter('all'); setQ(''); } } : null} />)}

      {tab === 'audit' && (
        <Card className="p-3 mb-3">
          <div className="flex items-center gap-3 flex-wrap">
            <ShieldCheck size={16} className={verify && verify !== 'checking' && !verify.error && !verify.ok ? 'text-error shrink-0' : 'text-success shrink-0'} />
            <div className="flex-1 min-w-[180px] text-sm">
              <div className="font-medium">{t('sec.tamper.title', 'Tamper-evident log')}</div>
              <div className="text-[11px] text-[var(--faint)]">{t('sec.tamper.desc', 'Every staff action is HMAC-chained — edits or deletions are detectable. Sensitive actions (file downloads, DB writes, power) are anchored off-DB (catches truncation) and alert SUPERADMINs.')}</div>
            </div>
            {verify && verify !== 'checking' && !verify.error && verify.ok && (
              <Badge tone="green" className="flex items-center gap-1"><CheckCircle2 size={12} /> {t('sec.intact', 'Intact')} · {verify.checked} {t('sec.chained', 'chained')}{verify.anchorsChecked ? ` · ${verify.anchorsChecked} ${t('sec.anchored', 'anchored')}` : ''}{verify.legacy ? ` (+${verify.legacy} ${t('sec.legacy', 'legacy')})` : ''}</Badge>
            )}
            {verify?.error && <Badge tone="red">{t('sec.verify.failed', 'Verify failed')}</Badge>}
            <Button size="sm" variant="ghost" disabled={verify === 'checking'} onClick={runVerify}>{verify === 'checking' ? <Spinner /> : <><ShieldCheck size={13} /> {t('sec.verify', 'Verify integrity')}</>}</Button>
            {/* Reachable while everything is fine, because that is when it is worth doing:
                an anchor placed during an incident only protects what comes after it. */}
            <Button size="sm" variant="ghost" disabled={!!busyTool} onClick={anchorHead} title={t('sec.tool.anchor.d2', 'Write the newest entry\u2019s fingerprint outside the database, so deleting the newest rows becomes detectable.')}>
              {busyTool === 'anchor' ? <Spinner /> : <><Anchor size={13} /> {t('sec.tool.anchor2', 'Anchor now')}</>}
            </Button>
          </div>
          {/* Since when. A break's timestamp on a badge told an admin where the chain stopped
              and nothing about what that costs them: every entry from that moment on proves
              nothing any more, and how many that is decides whether this is a curiosity or an
              incident. */}
          {verify && verify !== 'checking' && !verify.error && !verify.ok && (() => {
            const brk = verify.firstBreak || verify.anchorBreak;
            const reasonLabel = { content_altered: t('sec.r.content', 'Content altered'), chain_broken: t('sec.r.chain', 'Chain broken'), anchored_entry_deleted: t('sec.r.truncated', 'Log truncated'), anchored_entry_altered: t('sec.r.anchored', 'Anchored entry altered') }[brk?.reason] || t('sec.r.tampered', 'Tampered');
            const sb = verify.sinceBreak;
            return (
              <div className="mt-3 rounded-[12px] border b-error tint-error p-3">
                <div className="flex items-center gap-2 font-medium text-sm text-error"><AlertTriangle size={14} /> {reasonLabel}</div>
                {sb && <>
                  <div className="text-sm mt-1">{t('sec.brk.since', 'Untrustworthy since')} {new Date(sb.at).toLocaleString()} <span className="text-[var(--faint)]">({sb.hoursSince}{t('sec.brk.hours', 'h ago')})</span></div>
                  <div className="text-[12px] text-[var(--muted)] mt-1">
                    {sb.entriesAfter} {t('sec.brk.after', 'entries were written at or after that point, the chain says nothing about them, in either direction.')}
                  </div>
                  {sb.trustedUntil && <div className="text-[12px] text-[var(--muted)]">{t('sec.brk.until', 'Everything up to')} {new Date(sb.trustedUntil).toLocaleString()} {t('sec.brk.until2', 'still verifies.')}</div>}
                </>}
                {brk?.id && <div className="mt-2 flex flex-wrap gap-2">
                  <Button size="sm" onClick={() => setOpenId(brk.id)}><Eye size={13} /> {t('sec.brk.open', 'Open the first broken entry')}</Button>
                  <Button size="sm" variant="ghost" onClick={() => { setFrom(''); setTo(''); setAction(''); setActorId(''); setQ(''); setFrom(new Date(new Date(brk.at).getTime() - 3600e3).toISOString().slice(0, 16)); }}>
                    <Clock size={13} /> {t('sec.brk.window', 'Show the hour around it')}
                  </Button>
                </div>}

                {/* What a broken chain MEANS, per reason. The four reasons are not the same
                    incident and do not have the same answer, and an admin reading "Chain
                    broken" at 3am should not have to work out which one they have. */}
                <div className="mt-3 pt-3 border-t b-error text-[12px] leading-relaxed">
                  <div className="font-medium mb-1">{t('sec.rb.what', 'What this means')}</div>
                  <p className="text-[var(--muted)]">{{
                    content_altered: t('sec.rb.content', 'A row\u2019s own content no longer matches its signature. Somebody edited an entry in the database directly — the log records the edited version, and the original is gone unless a backup has it.'),
                    chain_broken: t('sec.rb.chain', 'Each row still signs itself correctly, but one no longer points at the row before it. Entries were deleted or inserted in the middle. Nothing says WHAT was removed — only that the count changed.'),
                    anchored_entry_deleted: t('sec.rb.trunc', 'An entry written to the external anchor volume is missing from the database, and it is newer than the retention window, so it was not pruned. The newest rows were deleted — the one kind of tampering the in-database chain cannot see by itself.'),
                    anchored_entry_altered: t('sec.rb.anchored', 'A sensitive action\u2019s entry differs from the copy anchored outside the database at the moment it happened. The anchor is the earlier, uncompromised record.'),
                  }[brk?.reason] || t('sec.rb.generic', 'The chain no longer verifies. Treat every entry from the break onward as unverifiable in both directions.')}</p>
                  <p className="text-[var(--muted)] mt-1.5">
                    {t('sec.rb.key', 'The signing secret lives in the server\u2019s environment, not the database. A forged chain that verifies would mean that secret leaked too — so a break usually means somebody had database access and not the key.')}
                  </p>
                </div>

                {/* Three tools, in the order they have to be used. Export first: every other
                    action here writes to the database under suspicion, and re-sealing over a
                    break destroys the only record of what the break looked like. */}
                <div className="mt-3 pt-3 border-t b-error">
                  <div className="font-medium text-[12px] mb-2">{t('sec.rb.do', 'What to do, in this order')}</div>
                  <ol className="space-y-2.5">
                    <li className="flex flex-wrap items-start gap-2">
                      <span className="text-[11px] tabular-nums text-[var(--faint)] mt-1.5 w-4 shrink-0">1.</span>
                      <div className="min-w-0 flex-1">
                        <Button size="sm" variant={evidenceDone ? 'ghost' : 'primary'} disabled={!!busyTool} onClick={exportEvidence}>
                          {busyTool === 'evidence' ? <Spinner /> : <><Download size={13} /> {t('sec.tool.export', 'Export the evidence bundle')}</>}
                        </Button>
                        <p className="text-[11px] text-[var(--muted)] mt-1">
                          {t('sec.tool.export.d', 'The break, the rows on both sides of it, and every external anchor \u2014 signed with the site key so it can be shown to have come from here unedited. Save it somewhere this server cannot write to.')}
                          {evidenceDone && <span className="text-success"> {t('sec.tool.export.ok', 'Exported.')}</span>}
                        </p>
                      </div>
                    </li>
                    <li className="flex flex-wrap items-start gap-2">
                      <span className="text-[11px] tabular-nums text-[var(--faint)] mt-1.5 w-4 shrink-0">2.</span>
                      <div className="min-w-0 flex-1">
                        <Button size="sm" variant="ghost" disabled={!!busyTool} onClick={anchorHead}>
                          {busyTool === 'anchor' ? <Spinner /> : <><Anchor size={13} /> {t('sec.tool.anchor', 'Anchor the log head now')}</>}
                        </Button>
                        <p className="text-[11px] text-[var(--muted)] mt-1">
                          {t('sec.tool.anchor.d', 'Writes the newest entry\u2019s fingerprint to the anchor volume, outside the database. Only sensitive actions anchor themselves, so an ordinary log has nothing to compare against \u2014 after this, deleting the newest rows is detectable.')}
                        </p>
                      </div>
                    </li>
                    <li className="flex flex-wrap items-start gap-2">
                      <span className="text-[11px] tabular-nums text-[var(--faint)] mt-1.5 w-4 shrink-0">3.</span>
                      <div className="min-w-0 flex-1">
                        <Button size="sm" variant="ghost" disabled={!!busyTool} onClick={reseal}>
                          {busyTool === 'reseal' ? <Spinner /> : <><ShieldCheck size={13} /> {t('sec.tool.resealbtn', 'Re-sign from the break')}</>}
                        </Button>
                        <p className="text-[11px] text-[var(--muted)] mt-1">
                          {t('sec.tool.reseal.d', 'Last, and only once the bundle is saved. It restores detection going forward; it does not restore trust in the entries it re-signs, and it overwrites the proof that the break happened. Superadmin, and elevation required.')}
                        </p>
                      </div>
                    </li>
                  </ol>
                </div>
              </div>
            );
          })()}
        </Card>
      )}

      {tab === 'audit' && (audit.loading ? <Loading /> : entries.length ? <>
        <Card className="p-0 overflow-hidden">
          <div className="max-h-[65vh] overflow-auto">
            {byDay(entries).map((g) => (
              <div key={g.day}>
                <DayHeading at={g.at} count={g.rows.length} />
                <div className="divide-y divide-[var(--line)]">
                  {g.rows.map((e) => (
                    <div key={e.id} className="flex items-start gap-3 px-4 py-2.5 text-sm hover:bg-[var(--surface-2)] transition">
                      <Shield size={15} className="text-[var(--accent-ink)] shrink-0 mt-0.5" />
                      <button onClick={() => setOpenId(e.id)} className="flex-1 min-w-0 text-start">
                        {/* Who and what on one line, the detail on its own. The three used to
                            share a single truncated line, so on anything narrower than a
                            laptop the detail, which is the part that says what was actually
                            done, was the part that got cut. */}
                        <div className="flex items-baseline gap-1.5 flex-wrap">
                          <span className="font-medium">{e.actor?.displayName || t('sec.noactor', 'system')}</span>
                          <span className="text-[var(--muted)] font-mono text-[12px]">{e.action}</span>
                        </div>
                        {e.detail && <div className="text-[12px] text-[var(--faint)] break-words">{e.detail}</div>}
                        <div className="text-[11px] text-[var(--faint)] font-mono flex items-center gap-1.5 flex-wrap">
                          <span>{e.ip || '—'}</span>
                          <span className="sm:hidden">· <LogTime at={e.createdAt} /></span>
                        </div>
                      </button>
                      <span className="hidden sm:block"><LogTime at={e.createdAt} /></span>
                    </div>
                  ))}
                </div>
              </div>
            ))}
          </div>
        </Card>
        {total > PAGE && (
          <div className="flex items-center justify-between gap-2 mt-2 text-xs text-[var(--faint)]">
            <span>{t('sec.page.showing', 'Showing')} {page * PAGE + 1}–{Math.min(total, (page + 1) * PAGE)} / {total}</span>
            <div className="flex gap-2">
              <Button size="sm" variant="ghost" disabled={page === 0} onClick={() => setPage((n) => Math.max(0, n - 1))}>{t('sec.page.prev', 'Newer')}</Button>
              <Button size="sm" variant="ghost" disabled={(page + 1) * PAGE >= total} onClick={() => setPage((n) => n + 1)}>{t('sec.page.next', 'Older')}</Button>
            </div>
          </div>
        )}
      </> : <EmptyState icon={Shield} title={filtersOn ? t('sec.nomatch', 'No matches') : t('sec.none.audit', 'No audit entries in this range')}
        sub={filtersOn ? t('sec.nomatch.audit.s', 'The dates, action, actor or search above exclude every entry.') : t('sec.none.audit.s', 'No staff action was recorded in the window selected above.')}
        action={filtersOn ? { label: t('sec.f.clearall', 'Clear the filters'), icon: X, onClick: clearFilters } : null} />)}

      <AuditDetail id={openId} onClose={() => setOpenId(null)} onPickActor={(id) => { setTab('audit'); setActorId(id); }} />
    </div>
  );
}

// A compact multi-line SVG chart for cpu/mem/disk % history — same hand-rolled
// approach as the repo dashboard's traffic chart (no charting library dependency).
// Smooth path through points [{x,y}] via Catmull-Rom → cubic Bézier. Turns jagged
// straight-segment line charts into polished flowing curves (the "pro chart" look).
// Catmull-Rom through the points, emitted as cubic Beziers.
//
// The control-point y values are CLAMPED to the band spanned by the two points they sit
// between, and that clamp is load-bearing. A cubic Bezier is contained in the convex hull
// of its four control points, so with all four inside [min(p1.y,p2.y), max(p1.y,p2.y)] the
// curve cannot leave the range of the data — which is what stops it being cut off.
//
// Without the clamp, a Catmull-Rom tangent OVERSHOOTS at a spike. Real case: the analytics
// KPI sparkline draws into a `viewBox="0 0 120 40"` on data like [0,0,0,3,3,0,0,0,0] — one
// busy day surrounded by empty ones. The tangents put control points at y = -4.7 and
// y = 44.7, outside the viewBox on both sides, and an SVG clips to its own viewport. The
// crest and the trough came out sliced flat against the edge of the card.
//
// It only showed up SOMETIMES because it needs a sharp spike in otherwise flat data: the
// flatter the neighbours, the further the tangent throws the control point.
//
// The cost is that a crest is very slightly flatter than an unclamped spline. That is the
// correct trade — the alternative is a curve that lies about its own peak.
function smoothPath(pts) {
  if (!pts.length) return '';
  if (pts.length < 3) return pts.map((p, i) => `${i ? 'L' : 'M'} ${p.x.toFixed(1)} ${p.y.toFixed(1)}`).join(' ');
  const clamp = (v, a, b) => Math.max(Math.min(a, b), Math.min(Math.max(a, b), v));
  let d = `M ${pts[0].x.toFixed(1)} ${pts[0].y.toFixed(1)}`;
  for (let i = 0; i < pts.length - 1; i++) {
    const p0 = pts[i - 1] || pts[i], p1 = pts[i], p2 = pts[i + 1], p3 = pts[i + 2] || p2;
    const c1x = p1.x + (p2.x - p0.x) / 6, c1y = clamp(p1.y + (p2.y - p0.y) / 6, p1.y, p2.y);
    const c2x = p2.x - (p3.x - p1.x) / 6, c2y = clamp(p2.y - (p3.y - p1.y) / 6, p1.y, p2.y);
    d += ` C ${c1x.toFixed(1)} ${c1y.toFixed(1)}, ${c2x.toFixed(1)} ${c2y.toFixed(1)}, ${p2.x.toFixed(1)} ${p2.y.toFixed(1)}`;
  }
  return d;
}

function MetricChart({ history }) {
  const [wrapRef, W] = useElementWidth(760); const H = 200; const padL = 32; const padR = 8; const padY = 16;
  const [hoverIdx, setHoverIdx] = useState(null);
  if (!history.length) return <div className="text-sm text-[var(--faint)] py-10 text-center">No samples yet — click "Sample now" or wait for the next ~10 min tick.</div>;
  const n = history.length;
  const x = (i) => n === 1 ? (padL + W - padR) / 2 : padL + (i / Math.max(1, n - 1)) * (W - padL - padR);
  const y = (pct) => H - padY - (Math.max(0, Math.min(100, pct)) / 100) * (H - padY * 2);
  // A lone point (or two) has no meaningful line yet — draw dots too, so the chart
  // is never blank while history is still building up (a single "M ..." path with
  // no "L" segment renders invisibly, which looked like a broken/empty graph).
  const series = (key, color) => {
    const d = smoothPath(history.map((h, i) => ({ x: x(i), y: y(h[key]) })));
    return (
      <g key={key}>
        {n > 1 && <path d={d} fill="none" stroke={color} strokeWidth={2} strokeLinecap="round" strokeLinejoin="round" vectorEffect="non-scaling-stroke" />}
        {history.map((h, i) => <circle key={i} cx={x(i)} cy={y(h[key])} r={hoverIdx === i ? (n > 12 ? 3 : 4) : (n > 12 ? 1.5 : 2.5)} fill={color} />)}
      </g>
    );
  };
  // Map mouse position -> nearest sample by comparing against the SVG's own
  // viewBox coordinate space (via its rendered bounding box), so this stays
  // correct regardless of how wide the chart is actually drawn on screen.
  const onMove = (e) => {
    const rect = e.currentTarget.getBoundingClientRect();
    const svgX = ((e.clientX - rect.left) / rect.width) * W;
    let best = 0; let bestDist = Infinity;
    for (let i = 0; i < n; i++) { const d = Math.abs(x(i) - svgX); if (d < bestDist) { bestDist = d; best = i; } }
    setHoverIdx(best);
  };
  const hv = hoverIdx != null ? history[hoverIdx] : null;
  const ttW = 132; const ttH = 62;
  const ttX = hoverIdx != null ? Math.min(Math.max(x(hoverIdx) - ttW / 2, padL), W - padR - ttW) : 0;
  return (
    <div ref={wrapRef} className="w-full">
    <svg viewBox={`0 0 ${W} ${H}`} width="100%" height="192" preserveAspectRatio="none" className="cursor-crosshair" onMouseMove={onMove} onMouseLeave={() => setHoverIdx(null)}>
      {/* Danger band: anything above 90% is tinted red so sustained pressure is obvious. */}
      <rect x={padL} y={y(100)} width={W - padL - padR} height={y(90) - y(100)} fill="#f87171" opacity="0.08" />
      <line x1={padL} x2={W - padR} y1={y(90)} y2={y(90)} stroke="#f87171" strokeWidth={1} strokeDasharray="4 3" opacity="0.5" />
      {[0, 25, 50, 75, 100].map((g) => (
        <g key={g}>
          <line x1={padL} x2={W - padR} y1={y(g)} y2={y(g)} stroke="var(--line)" strokeWidth={1} />
          <text x={2} y={y(g) + 3} fontSize="9" fill="var(--faint)">{g}%</text>
        </g>
      ))}
      {series('diskPct', '#a78bfa')}
      {series('memPct', '#38bdf8')}
      {series('cpuPct', '#f97316')}
      {hv && (
        <g pointerEvents="none">
          <line x1={x(hoverIdx)} x2={x(hoverIdx)} y1={padY} y2={H - padY} stroke="var(--faint)" strokeWidth={1} strokeDasharray="3 3" />
          <rect x={ttX} y={4} width={ttW} height={ttH} rx={6} fill="var(--surface-2)" stroke="var(--line)" />
          <text x={ttX + 8} y={18} fontSize="9" fill="var(--faint)">{new Date(hv.createdAt).toLocaleString([], { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' })}</text>
          <text x={ttX + 8} y={32} fontSize="10" fontWeight="600" fill="#f97316">CPU {hv.cpuPct.toFixed(1)}%</text>
          <text x={ttX + 8} y={45} fontSize="10" fontWeight="600" fill="#38bdf8">RAM {hv.memPct.toFixed(1)}%</text>
          <text x={ttX + 8} y={58} fontSize="10" fontWeight="600" fill="#a78bfa">Disk {hv.diskPct.toFixed(1)}%</text>
        </g>
      )}
    </svg>
    </div>
  );
}

// Utilisation thresholds → tone. Disk fills slowly so its "warn" is higher; CPU/RAM
// spike, so they warn earlier. Used to colour the KPI cards and the health summary.
const PERF_THRESH = { cpuPct: [75, 90], memPct: [80, 92], diskPct: [85, 95], loadRatio: [1, 1.5] };
const toneFor = (v, [warn, crit]) => v == null ? '' : v >= crit ? 'crit' : v >= warn ? 'warn' : 'ok';
const TONE_TEXT = { ok: 'text-success', warn: 'text-warning', crit: 'text-error', '': '' };
const TONE_STROKE = { ok: '#34d399', warn: '#f59e0b', crit: '#f87171', '': 'var(--primary)' };
// kbit/s → a readable rate (Mb/s above 1000, else kb/s).
const fmtKbps = (k) => k == null ? '—' : k >= 1000 ? `${(k / 1000).toFixed(1)} Mb/s` : `${Math.round(k)} kb/s`;

// Server performance dashboard — read-only (no dangerous action lives here, so no
// step-up 2FA required). CPU/RAM/disk/latency/uptime are sampled from INSIDE this
// container every ~10 min by the sweeper (monitor.mjs); a per-container/per-service
// breakdown with restart controls would need Docker-socket access, which is a
// separate, bigger ask (see the "Advanced server management" tab).
// The thresholds every alert fires on. They lived only in the database until now, so
// tuning them meant writing SQL — and a threshold nobody can reach is a threshold nobody
// tunes, which is how an alert channel becomes noise people mute.
//
// The form shows the EFFECTIVE values (stored overrides merged with the defaults), never
// blank boxes: an empty field would read as "no threshold" when it actually means "the
// default applies". Reset writes an empty override rather than writing the defaults in,
// so a later change to a default is picked up instead of being frozen at today's number.
function AlertThresholds() {
  const { t } = useI18n(); const toast = useToast();
  const data = useAsync(() => api.get('/admin/server/thresholds'), []);
  const [form, setForm] = useState(null);
  const [busy, setBusy] = useState(false);
  useEffect(() => { if (data.data?.thresholds) setForm(data.data.thresholds); }, [data.data]);

  const FIELDS = [
    { k: 'cpuPct', label: t('sp.th.cpu', 'CPU %') },
    { k: 'memPct', label: t('sp.th.mem', 'Memory %') },
    { k: 'diskPct', label: t('sp.th.disk', 'Disk %') },
    { k: 'storagePct', label: t('sp.th.storage', 'Storage pool %'), hint: t('sp.th.storage.h', 'Warn while a hosting pool still has room to act.') },
    { k: 'vitalsPoorPct', label: t('sp.th.vitals', 'Web Vitals poor %'), hint: t('sp.th.vitals.h', 'Share of "poor" samples on a metric, over the last hour.') },
    { k: 'vitalsMinSamples', label: t('sp.th.vitalsmin', 'Web Vitals min samples'), hint: t('sp.th.vitalsmin.h', 'Below this, two bad loads would fire it.') },
    { k: 'errorBurst', label: t('sp.th.errors', 'Error burst'), hint: t('sp.th.errors.h', 'New errors within ten minutes.') },
  ];

  const save = async () => {
    setBusy(true);
    try { const r = await api.put('/admin/server/thresholds', form); setForm(r.thresholds); toast.success(t('sp.th.saved', 'Thresholds saved.')); }
    catch { toast.error(t('sp.failed', 'Failed.')); } finally { setBusy(false); }
  };
  const reset = async () => {
    setBusy(true);
    try { const r = await api.put('/admin/server/thresholds', {}); setForm(r.thresholds); toast.success(t('sp.th.reset', 'Back to defaults.')); }
    catch { toast.error(t('sp.failed', 'Failed.')); } finally { setBusy(false); }
  };

  if (data.loading || !form) return <Loading />;
  return (
    <Card className="p-5">
      <p className="text-xs text-[var(--muted)] mb-3">
        {t('sp.th.sub', 'What each alert fires on. Leave them alone and the built-in defaults apply.')}
      </p>
      <div className="grid sm:grid-cols-2 lg:grid-cols-3 gap-3">
        {FIELDS.map((f) => (
          <Field key={f.k} label={f.label} hint={f.hint}>
            <Input type="number" min="0" value={form[f.k] ?? ''}
              onChange={(e) => setForm({ ...form, [f.k]: e.target.value === '' ? '' : Number(e.target.value) })} />
          </Field>
        ))}
      </div>
      <div className="flex gap-2 mt-4">
        <Button size="sm" variant="primary" disabled={busy} onClick={save}>{t('common.save', 'Save')}</Button>
        <Button size="sm" disabled={busy} onClick={reset}>{t('sp.th.resetbtn', 'Reset to defaults')}</Button>
      </div>
    </Card>
  );
}

// Comparing a period with the one before it, out to a year.
//
// Reads the DAILY rollup, because the raw samples are pruned at 30 days — which is why this
// question had no answer until now. When the history does not reach back far enough the panel
// SAYS so instead of drawing a comparison against nothing: a change measured against no data is
// not a change of zero, it is not a measurement.
function PerfCompare() {
  const { t } = useI18n();
  const [days, setDays] = useState(7);
  const { data, loading } = useAsync(() => api.get(`/admin/server/metrics/compare?days=${days}`), [days]);

  const RANGES = [[1, t('perf.r.1', 'Yesterday')], [7, t('perf.r.7', 'A week')], [30, t('perf.r.30', 'A month')],
    [182, t('perf.r.182', 'Six months')], [365, t('perf.r.365', 'A year')]];

  const pct = (v) => (v == null ? '—' : `${v.toFixed(1)}%`);
  const num = (v, d = 2) => (v == null ? '—' : v.toFixed(d));
  const ms = (v) => (v == null ? '—' : `${Math.round(v)} ms`);
  /** kbps as the unit a person reads: Mb/s once it is worth it. */
  const rate = (v) => (v == null ? '—' : v >= 1024 ? `${(v / 1024).toFixed(1)} Mb/s` : `${Math.round(v)} kb/s`);

  // Direction is per-metric, not global.
  //
  // This used to assume up is always worse, which was true while the table held CPU, memory,
  // disk and downtime. Uptime broke it the moment it was added: +0.4 pt is the best line on
  // the panel and would have been painted as a warning. `good` says which way is which.
  const Delta = ({ v, unit = '%', good = 'down', digits = 1 }) => {
    if (v == null) return <span className="text-[var(--faint)]">—</span>;
    const eps = unit === '%' ? 0.05 : 0.5;
    const up = v > eps, down = v < -eps;
    const better = good === 'up' ? up : down;
    const worse = good === 'up' ? down : up;
    const shown = unit === '%' ? `${v.toFixed(digits)} pt` : unit === 'ms' ? `${Math.round(v)} ms` : `${Math.round(v)} ${unit}`;
    return (
      <span className={better ? 'text-[var(--success)]' : worse ? 'text-[var(--warning)]' : 'text-[var(--faint)]'}>
        {v > 0 ? '+' : ''}{shown}
      </span>
    );
  };

  /** dd/mm → dd/mm, in the reader's locale. */
  const range = (a, b) => (a && b
    ? `${new Date(a).toLocaleDateString(undefined, { day: '2-digit', month: 'short' })} – ${new Date(b).toLocaleDateString(undefined, { day: '2-digit', month: 'short' })}`
    : null);

  const exportCsv = () => {
    const rows = data?.series || [];
    if (!rows.length) return;
    downloadCsv(toCsv(rows, [
      ['day', (r) => String(r.day).slice(0, 10)],
      ['cpu_avg_pct', (r) => r.cpuAvg?.toFixed(2)], ['cpu_max_pct', (r) => r.cpuMax?.toFixed(2)],
      ['mem_avg_pct', (r) => r.memAvg?.toFixed(2)], ['mem_max_pct', (r) => r.memMax?.toFixed(2)],
      ['disk_avg_pct', (r) => r.diskAvg?.toFixed(2)], ['disk_max_pct', (r) => r.diskMax?.toFixed(2)],
      ['load_avg', (r) => r.loadAvg?.toFixed(2)], ['latency_avg_ms', 'latencyAvg'],
      ['net_rx_avg_kbps', 'netRxAvg'], ['net_tx_avg_kbps', 'netTxAvg'],
      ['samples', 'samples'], ['down_minutes', 'downMinutes'],
    ]), `server-metrics-${days}d-${new Date().toISOString().slice(0, 10)}`);
  };

  const cur = data?.current; const prev = data?.previous; const cov = data?.coverage;

  return (
    <Card className="p-4">
      <div className="flex items-center justify-between gap-2 flex-wrap mb-3">
        <div className="text-sm font-semibold flex items-center gap-2">
          <TrendingUp size={15} className="text-[var(--accent-ink)]" /> {t('perf.cmp.title', 'Compared with the period before')}
        </div>
        <div className="flex items-center gap-2 flex-wrap">
          <select value={days} onChange={(e) => setDays(Number(e.target.value))} className="input !py-1.5 !text-sm !w-auto">
            {RANGES.map(([d, label]) => <option key={d} value={d}>{label}</option>)}
          </select>
          <Button size="sm" disabled={!data?.series?.length} onClick={exportCsv}>
            <Download size={13} /> {t('perf.cmp.csv', 'Export CSV')}
          </Button>
        </div>
      </div>

      {loading ? <Spinner size={14} /> : !cur ? (
        <div className="text-[12px] text-[var(--faint)]">{t('perf.cmp.nodata', 'Nothing recorded for this period yet.')}</div>
      ) : (
        <div className="overflow-x-auto">
          <table className="w-full text-[13px]">
            <thead>
              <tr className="text-[11px] uppercase tracking-wider text-[var(--faint)]">
                <th className="text-start font-normal pb-1.5" />
                {/* Both windows are dated. "The one before" is not a date, and an admin
                    reading a regression needs to know which days it is blamed on. */}
                <th className="text-end font-normal pb-1.5">
                  {t('perf.cmp.now', 'This period')}
                  {range(data?.from, data?.to) && <div className="font-normal normal-case text-[10px] opacity-70">{range(data.from, data.to)}</div>}
                </th>
                <th className="text-end font-normal pb-1.5">
                  {t('perf.cmp.before', 'The one before')}
                  {range(data?.previousFrom, data?.previousTo) && <div className="font-normal normal-case text-[10px] opacity-70">{range(data.previousFrom, data.previousTo)}</div>}
                </th>
                <th className="text-end font-normal pb-1.5">{t('perf.cmp.change', 'Change')}</th>
              </tr>
            </thead>
            <tbody>
              {/* Averages AND peaks. A server averaging 30% with a peak of 99% is a
                  different server from one that sits at 30%, and only the average was shown
                  — so the panel could not see the shape of a problem, only its mean.
                  Latency, load and network were recorded per day and exported to CSV all
                  along; the comparison simply never read them. */}
              {[
                { k: 'cpuAvg', label: t('perf.cmp.cpu', 'CPU, average'), fmt: pct },
                { k: 'cpuMax', label: t('perf.cmp.cpumax', 'CPU, peak'), fmt: pct, sub: true },
                { k: 'memAvg', label: t('perf.cmp.mem', 'Memory, average'), fmt: pct },
                { k: 'memMax', label: t('perf.cmp.memmax', 'Memory, peak'), fmt: pct, sub: true },
                { k: 'diskAvg', label: t('perf.cmp.disk', 'Disk, average'), fmt: pct },
                { k: 'diskMax', label: t('perf.cmp.diskmax', 'Disk, peak'), fmt: pct, sub: true },
                { k: 'loadAvg', label: t('perf.cmp.load', 'Load average'), fmt: (v) => num(v, 2), unit: '', digits: 2 },
                { k: 'latencyAvg', label: t('perf.cmp.lat', 'Response time, average'), fmt: ms, unit: 'ms' },
                { k: 'netRxAvg', label: t('perf.cmp.rx', 'Network in'), fmt: rate, unit: 'kb/s', good: 'none' },
                { k: 'netTxAvg', label: t('perf.cmp.tx', 'Network out'), fmt: rate, unit: 'kb/s', good: 'none' },
                { k: 'uptimePct', label: t('perf.cmp.up', 'Uptime'), fmt: pct, good: 'up' },
                { k: 'downMinutes', label: t('perf.cmp.down', 'Minutes not running'), fmt: (v) => String(Math.round(v)), unit: 'min', sub: true },
              ].map((row) => (
                <tr key={row.k} className="border-t border-[var(--line)]">
                  <td className={`py-1.5 ${row.sub ? 'ps-3 text-[var(--muted)] text-[12px]' : ''}`}>{row.label}</td>
                  <td className="py-1.5 text-end tabular-nums">{row.fmt(cur[row.k])}</td>
                  <td className="py-1.5 text-end tabular-nums text-[var(--muted)]">{prev ? row.fmt(prev[row.k]) : '—'}</td>
                  <td className="py-1.5 text-end tabular-nums">
                    {/* Network has no better direction — more traffic is not good or bad, it
                        is just more — so it shows the movement without a verdict colour. */}
                    <Delta v={data?.change?.[row.k]} unit={row.unit ?? '%'} good={row.good || 'down'} digits={row.digits ?? 1} />
                  </td>
                </tr>
              ))}
            </tbody>
          </table>

          {/* What the numbers rest on. A week's comparison built from four days is a different
              statement from one built from fourteen, and the reader cannot tell without this. */}
          <div className="text-[11px] text-[var(--faint)] mt-2">
            {t('perf.cmp.built', '{d} day(s), {n} sample(s).').replace('{d}', cur.days).replace('{n}', cur.samples)}
            {cov && !cov.complete && (
              <span className="text-[var(--warning)]">
                {' '}{t('perf.cmp.short', 'History only goes back {h} day(s) — there is no earlier period to compare with yet. Daily summaries started when this was added; they are kept for good, so longer comparisons fill in from here.').replace('{h}', cov.daysHeld)}
              </span>
            )}
          </div>
        </div>
      )}
    </Card>
  );
}

function AdminServerPerf() {
  const toast = useToast();
  const dialog = useDialog();
  const { t } = useI18n();
  // Which host's samples the chart draws. '' = whichever container answered, which is the
  // right default for one API and a lottery for several — hence the selector below.
  const [pickHost, setPickHost] = useState('');
  const { data, loading, reload } = useAsync(() => api.get(`/admin/server/metrics${pickHost ? `?host=${encodeURIComponent(pickHost)}` : ''}`), [pickHost]);
  const alerts = useAsync(() => api.get('/admin/server/alerts'), []);
  const outages = useAsync(() => api.get('/admin/server/outages'), []);
  const depsCfg = useAsync(() => api.get('/admin/server/deps-config'), []);
  const [busy, setBusy] = useState(false);
  const [configuring, setConfiguring] = useState(false);
  const [depsBusy, setDepsBusy] = useState(false);
  const [rechecking, setRechecking] = useState(false);
  // Live network rate: diff the cumulative rx/tx byte counters between two 30s refreshes.
  const netPrevRef = useRef(null);
  const [liveNet, setLiveNet] = useState({ rx: null, tx: null });
  // Every section open, as it was before a Simple/Advanced switch was put in front of them.
  // They are still individually collapsible — that is a reader folding away what they are not
  // looking at, which is different from a mode deciding for them.
  const [sec, setSec] = useState({ alloc: true, downtime: true, alerts: true, outages: true, vitals: true });
  const [outageOpen, setOutageOpen] = useState(null);
  // Ticks only while an outage is live. A timer that runs on a healthy page is a render a
  // second for nothing, and this screen is heavy enough already.
  const [nowTick, setNowTick] = useState(() => Date.now());
  const toggleSec = (k) => setSec((s) => ({ ...s, [k]: !s[k] }));
  useEffect(() => {
    const cur = data?.net; if (!cur) return;
    const prev = netPrevRef.current;
    if (prev && cur.at > prev.at) {
      const dt = (cur.at - prev.at) / 1000;
      setLiveNet({ rx: Math.max(0, Math.round((cur.rx - prev.rx) * 8 / 1000 / dt)), tx: Math.max(0, Math.round((cur.tx - prev.tx) * 8 / 1000 / dt)) });
    }
    netPrevRef.current = cur;
  }, [data?.net?.at]);
  // Auto-refresh the read-only metrics + alerts every 30s (cheap — deps/SSL config,
  // which rarely changes, is NOT re-polled). Keeps the dashboard live between samples.
  useEffect(() => { const id = setInterval(() => { reload(); alerts.reload(); }, 30_000); return () => clearInterval(id); /* eslint-disable-next-line */ }, []);
  const sampleNow = async () => {
    setBusy(true);
    try { await api.post('/admin/server/sample-now'); toast.success(t('sp.sampled', 'Sampled.')); reload(); alerts.reload(); } catch { toast.error(t('sp.failed', 'Failed.')); } finally { setBusy(false); }
  };
  // Acknowledging is not resolving: it clears the tab badge and says a human has read the
  // alert. Nothing about the underlying condition changes, and the row stays in the list.
  const [ackPending, setAckPending] = useState(false);
  const ackAll = () => {
    // The same undo window as everything else on this site that cannot be un-clicked. The
    // badge clears now — that IS the undo affordance — and the write happens when the toast
    // expires, so cancelling never touched the server.
    setAckPending(true);
    toast.action({
      tone: 'success', cancelLabel: t('common.undo', 'Undo'), msg: t('sp.al.acked', 'Marked as seen.'),
      onCommit: async () => {
        try { await api.post('/admin/server/alerts/ack'); alerts.reload(); pendingChanged(); }
        catch { toast.error(t('sp.failed', 'Failed.')); }
        finally { setAckPending(false); }
      },
      onCancel: () => setAckPending(false),
    });
  };
  const [clearing, setClearing] = useState(false);
  const clearHistory = async () => {
    const ok = await doubleConfirm(dialog, {
      title: t('sp.clr.title', 'Clear performance history'),
      message: t('sp.clr.warn', 'This permanently deletes every stored sample, daily rollup, alert and outage record. Live readings are unaffected. It cannot be undone.'),
      okLabel: t('sp.clr.go', 'Delete now'),
    });
    if (!ok) return;
    setClearing(true);
    try {
      const r = await api.post('/admin/server/clear', { table: 'all' });
      const n = Object.values(r?.cleared || {}).reduce((a, b) => a + (b || 0), 0);
      toast.success(t('sp.clr.done', '{n} rows deleted.').replace('{n}', n.toLocaleString()));
      reload(); alerts.reload(); outages.reload();
    } catch { toast.error(t('sp.failed', 'Failed.')); }
    finally { setClearing(false); }
  };
  // Probe them again now, rather than waiting out the 2-minute cache.
  //
  // The endpoint clears the cache and kicks off the probe without awaiting it — so this waits
  // a beat before reloading, or it would read back the same stale answers it just invalidated
  // and look like the button did nothing.
  const recheckDeps = async () => {
    setRechecking(true);
    try {
      await api.post('/admin/server/deps-recheck', {});
      await new Promise((r) => setTimeout(r, 1200));
      reload();
    } catch { toast.error(t('sp.failed', 'Failed.')); } finally { setRechecking(false); }
  };
  const toggleDep = async (key, on) => {
    setDepsBusy(true);
    try { await api.put('/admin/server/deps-config', { [key]: on }); depsCfg.reload(); reload(); } catch { toast.error(t('sp.failed', 'Failed.')); } finally { setDepsBusy(false); }
  };
  // Only blank to a spinner on the FIRST load — during the 30s background refresh keep
  // showing the current data (otherwise the whole tab flashes empty every 30s).
  // The two histories, merged into one list.
  //
  // They come from different places and mean different things — a gap in our own samples is
  // the server itself being gone, a ServiceOutage row is one dependency refusing — but to
  // whoever was turned away they are the same event, so they are read as one list and the
  // row says which kind it is. Sorted newest first, because the question is almost always
  // "what just happened".
  const fmtDur = (sec) => (sec < 90 ? `${Math.round(sec)}s` : sec < 5400 ? `${Math.round(sec / 60)} min` : `${(sec / 3600).toFixed(1)} h`);
  const mergedOutages = useMemo(() => {
    const dt = data?.downtime || [];
    const dep = (outages.data?.outages || []).map((o) => ({
      key: `d-${o.id}`, source: 'dep', label: o.label, cause: o.cause,
      startedAt: o.startedAt, endedAt: o.endedAt, seconds: o.seconds, ongoing: o.ongoing,
    }));
    const srv = dt.map((d, i) => ({
      key: `s-${i}-${d.from}`, source: 'server',
      label: t('sp.out.server', 'The server'),
      cause: t('sp.out.server.cause', 'No sample was recorded for this period, the process was down or restarting.'),
      startedAt: d.from, endedAt: d.to, seconds: (d.minutes || 0) * 60, ongoing: false,
    }));
    // Ongoing first, then newest. Sorting purely by start time could put a live outage
    // below three finished ones, which is the opposite of what this list is for.
    return [...dep, ...srv].sort((a, b) => (b.ongoing ? 1 : 0) - (a.ongoing ? 1 : 0) || new Date(b.startedAt) - new Date(a.startedAt));
  }, [outages.data, data?.downtime, t]);

  const liveOutages = useMemo(() => mergedOutages.filter((o) => o.ongoing), [mergedOutages]);

  /** How long an outage has ACTUALLY lasted.
   *
   *  `seconds` comes from the server and is correct forever for a finished outage. For a
   *  live one it is frozen at the moment of the fetch, so it has to be measured from the
   *  start instead — otherwise the page sits there saying "3 min" half an hour in.
   */
  const realSeconds = (o) => (o.ongoing ? Math.max(0, (nowTick - new Date(o.startedAt).getTime()) / 1000) : o.seconds);

  // The tick, and a refetch, both only while something is down. 30s on the data so "it
  // ended" arrives without anybody pressing anything.
  useEffect(() => {
    if (!liveOutages.length) return undefined;
    const tick = setInterval(() => setNowTick(Date.now()), 1000);
    const refetch = setInterval(() => { outages.reload?.(); }, 30_000);
    return () => { clearInterval(tick); clearInterval(refetch); };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [liveOutages.length]);

  // Availability per source over the same window the outages were fetched for. The server's
  // own row is computed from the same gaps, so the two numbers are comparable.
  const uptimeRows = useMemo(() => {
    const days = outages.data?.days || 30;
    const windowSec = days * 86400;
    const rows = (outages.data?.uptime || []).map((u) => ({ key: u.dep, label: u.label, pct: u.pct, downSeconds: u.downSeconds }));
    const srvDown = (data?.downtime || []).reduce((n, d) => n + (d.minutes || 0) * 60, 0);
    if (srvDown) {
      rows.push({
        key: '__server', label: t('sp.out.server', 'The server'),
        downSeconds: srvDown, pct: Math.max(0, Math.round((1 - srvDown / windowSec) * 10000) / 100),
      });
    }
    return rows.sort((a, b) => b.downSeconds - a.downSeconds);
  }, [outages.data, data?.downtime, t]);

  const outageLine = (o) => `${o.label} — ${fmtDur(o.seconds)} — ${new Date(o.startedAt).toLocaleString()}${o.endedAt ? ` → ${new Date(o.endedAt).toLocaleString()}` : ' → still down'}${o.cause ? ` — ${o.cause}` : ''}`;
  const copyOutages = async () => {
    const ok = await copyText([`BetterCommunity outage history`, `exported: ${new Date().toISOString()}`, '', ...mergedOutages.map(outageLine)].join('\n'));
    ok ? toast.success(t('common.copied', 'Copied.')) : toast.error(t('sp.al.copyfail', 'Could not copy, select the rows manually.'));
  };

  if (loading && !data) return <Loading />;
  const latest = data?.latest;
  const deps = data?.deps || {};
  const depsDetail = data?.depsDetail || null;
  const depsAt = data?.depsAt || null;
  // Stable order, from the config rather than from Object.keys(deps): the probe result is
  // built by Promise.all and a card whose rows reorder between refreshes is unreadable.
  const depKeys = (depsCfg.data?.keys || Object.keys(deps)).filter((k) => k in deps);
  // "not applicable" is not a failure and must not be counted as one — Stripe with no key
  // set would otherwise read as "5 of 6" for ever on an installation that never uses it.
  const depsRan = depKeys.filter((k) => deps[k] !== null).length;
  const depsUp = depsRan ? depKeys.filter((k) => deps[k] === true).length : null;
  const ssl = data?.ssl;
  const history = data?.history || [];
  const downtime = data?.downtime || [];
  const cg = data?.cgroupMemory;
  const totals = data?.totals || {};
  const labels = depsCfg.data?.labels || {};
  const allKeys = depsCfg.data?.keys || Object.keys(deps);
  const enabledCfg = depsCfg.data?.enabled || {};
  const gb = (b) => b == null ? null : b / 1024 ** 3;
  const memUsedGB = totals.memTotalBytes != null && totals.memFreeBytes != null ? gb(totals.memTotalBytes - totals.memFreeBytes) : null;
  const diskUsedGB = totals.diskTotalBytes != null && totals.diskFreeBytes != null ? gb(totals.diskTotalBytes - totals.diskFreeBytes) : null;
  // The SAME numbers the cards below show, as a percentage.
  //
  // These used to read latest.memPct / latest.diskPct — the most recent stored sample —
  // while the GB figures underneath were computed live when the page was fetched. Two clocks
  // for one quantity, shown side by side as though they agreed: 60% over "1.9 / 15.5 GB",
  // 83% over "95 / 1007 GB". Neither was wrong; the pairing was. A percentage and the
  // absolute value it is a percentage OF have to come from one reading.
  const memPctLive = totals.memTotalBytes ? 100 * (1 - totals.memFreeBytes / totals.memTotalBytes) : null;
  const diskPctLive = totals.diskTotalBytes ? 100 * (1 - totals.diskFreeBytes / totals.diskTotalBytes) : null;
  // How old the sampled metrics are. CPU and load have no live counterpart in this payload,
  // so they still come from the sample — and the page says so instead of implying "now".
  const sampleAgeMin = latest?.createdAt ? Math.round((Date.now() - new Date(latest.createdAt).getTime()) / 60000) : null;
  // Per-metric tone (green/amber/red) + an overall health rollup = the worst of them.
  const loadRatio = latest && totals.cpuCores ? latest.loadAvg1 / totals.cpuCores : null;
  // Each tone follows the value its own card DISPLAYS. Colouring memory from the stored
  // sample while showing the live number would put an amber ring around "12%".
  const cpuTone = toneFor(latest?.cpuPct, PERF_THRESH.cpuPct), memTone = toneFor(memPctLive, PERF_THRESH.memPct), diskTone = toneFor(diskPctLive, PERF_THRESH.diskPct), loadTone = toneFor(loadRatio, PERF_THRESH.loadRatio);
  const worst = [cpuTone, memTone, diskTone, loadTone];
  const health = !latest ? null : worst.includes('crit') ? 'crit' : worst.includes('warn') ? 'warn' : 'ok';
  const healthLabel = { ok: t('sp.health.ok', 'Healthy'), warn: t('sp.health.warn', 'Under load'), crit: t('sp.health.crit', 'Critical') }[health];
  // Per-metric sparklines from the sampled history (oldest→newest).
  const spark = (key) => history.map((h) => h[key]).filter((v) => v != null);
  const kpi = (label, value, Icon, tone, sparkKey) => (
    <Card className="p-3 relative overflow-hidden">
      {sparkKey && spark(sparkKey).length > 1 && <Sparkline data={spark(sparkKey)} stroke={TONE_STROKE[tone]} className="absolute inset-x-0 bottom-0 h-8 w-full opacity-60 pointer-events-none" />}
      <div className="relative">
        <div className="flex items-center gap-2 text-[var(--faint)] text-xs mb-1"><Icon size={13} /> {label}</div>
        <div className={`text-xl font-bold tabular-nums ${TONE_TEXT[tone] || ''}`}>{value}</div>
      </div>
    </Card>
  );
  return (
    <div>
      {/* ?alert=<id>: the bot's alert posts land on their own alert, not on the list. */}
      <AlertFocus />
      <div className="flex items-center justify-between mb-3 gap-2 flex-wrap">
        <h2 className="font-semibold flex items-center gap-2"><Cpu size={16} className="text-[var(--accent-ink)]" /> {t('sp.title', 'Server performance')}
          {health && <Badge tone={health === 'ok' ? 'green' : health === 'warn' ? 'amber' : 'red'}>{health === 'ok' ? <CheckCircle2 size={11} /> : <AlertTriangle size={11} />} {healthLabel}</Badge>}
        </h2>
        <div className="flex items-center gap-2">
          <span className="text-[11px] text-[var(--faint)] flex items-center gap-1"><span className="w-1.5 h-1.5 rounded-full bg-success animate-pulse" /> {t('sp.auto', 'auto 30s')}</span>
          {/* Sampling by hand and wiping the history are maintenance, not observation. They are
              one mode away, not one misclick away, while you are only looking at the numbers. */}
          <Button size="sm" variant="ghost" disabled={busy} onClick={sampleNow}>{busy ? <Spinner /> : <><RefreshCw size={14} /> {t('sp.samplenow', 'Sample now')}</>}</Button>
          {/* The case this exists for is the sawtooth: a second machine wrote into this
              database and half the history describes a host that was never the server.
              Once the other writer is gone that history cannot be repaired, only dropped. */}
          <Button size="sm" variant="ghost" disabled={clearing} onClick={clearHistory}>
            {clearing ? <Spinner /> : <><Trash2 size={14} /> {t('sp.clear', 'Clear history')}</>}
          </Button>
        </div>
      </div>
      <p className="text-xs text-[var(--muted)] mb-3">{t('sp.desc', 'Metrics reflect this API container\'s own view (os/cgroup) — sampled every ~10 min, auto-refreshed here every 30s. A full per-service breakdown with restart controls needs Docker-socket access (see "Advanced server management").')}</p>

      {/* The verdict — what Simple mode is FOR.
          Simple used to be this same screen with five sections collapsed: the numbers were all
          there and the reader still had to know that 87% disk is fine and 91% is not. The
          thresholds already encode that and the monitor already alerts on them, so the server
          sends the same comparison against the live sample (`verdict`) and this states it in
          one line. Advanced does not need it: someone reading the raw series is past the
          question. */}
      {data?.verdict && (() => {
        const V = data.verdict;
        const tone = V.state === 'problem' ? 'error' : V.state === 'watch' ? 'warning' : V.state === 'unknown' ? 'muted' : 'success';
        const ring = { error: 'border-[var(--error)]', warning: 'border-[var(--warning)]', success: 'border-[var(--success)]', muted: 'border-[var(--line)]' }[tone];
        const dot = { error: 'bg-[var(--error)]', warning: 'bg-[var(--warning)]', success: 'bg-[var(--success)]', muted: 'bg-[var(--faint)]' }[tone];
        const head = {
          ok: t('sp.v.ok', 'The server is fine.'),
          watch: t('sp.v.watch', 'Worth a look.'),
          problem: t('sp.v.problem', 'The server needs attention.'),
          unknown: t('sp.v.unknown', 'No current reading.'),
        }[V.state] || '';
        return (
          <div className={`mb-4 rounded-xl border ${ring} p-3.5 flex items-start gap-3`}>
            <span className={`mt-1 w-2.5 h-2.5 rounded-full shrink-0 ${dot}`} aria-hidden />
            <div className="min-w-0">
              <div className="text-sm font-semibold">{head}</div>
              {V.reasons?.length
                ? <ul className="mt-1 space-y-0.5">
                    {V.reasons.map((r) => (
                      <li key={r.key} className="text-xs text-[var(--muted)]">{r.text}</li>
                    ))}
                  </ul>
                : <div className="text-xs text-[var(--muted)] mt-0.5">{t('sp.v.okdesc', 'CPU, memory and disk are all clear of their alert limits.')}</div>}
            </div>
          </div>
        );
      })()}

      {/* Placed straight under the live numbers: "is this normal" is the question the live
          numbers provoke, and it is the one they cannot answer. */}
      <div className="mb-4"><PerfCompare /></div>
      {/* The daily charts that used to sit on the public status page, with the same window
          before them — an operations view, not a public one. */}
      <div className="mb-4"><PerfDailyMetrics /></div>

      <div className="grid grid-cols-2 sm:grid-cols-4 gap-3 mb-3">
        {kpi('CPU', latest ? `${latest.cpuPct.toFixed(0)}%` : '—', Cpu, cpuTone, 'cpuPct')}
        {kpi(t('sp.memory', 'Memory'), memPctLive != null ? `${memPctLive.toFixed(0)}%` : '—', Gauge, memTone, 'memPct')}
        {kpi(t('sp.disk', 'Disk'), diskPctLive != null ? `${diskPctLive.toFixed(0)}%` : '—', HardDrive, diskTone, 'diskPct')}
        {kpi(t('sp.load', 'Load (1m)'), latest ? latest.loadAvg1.toFixed(2) : '—', TrendingUp, loadTone)}
        {kpi(t('sp.uptime', 'Uptime'), latest ? `${(latest.uptimeSec / 3600).toFixed(1)}h` : '—', Clock, '')}
        {kpi(t('sp.latency', 'Avg latency'), latest?.latencyMs != null ? `${latest.latencyMs}ms` : '—', Zap, latest?.latencyMs != null ? toneFor(latest.latencyMs, [400, 1000]) : '')}
        {kpi(t('sp.download', 'Download'), (liveNet.rx ?? latest?.netRxKbps) != null ? fmtKbps(liveNet.rx ?? latest.netRxKbps) : '—', Download, '', 'netRxKbps')}
        {kpi(t('sp.upload', 'Upload'), (liveNet.tx ?? latest?.netTxKbps) != null ? fmtKbps(liveNet.tx ?? latest.netTxKbps) : '—', Upload, '', 'netTxKbps')}
      </div>

      {/* Absolute totals alongside the percentages above — "11% used" only means
          something once you know it's 11% of how much. */}
      <div className="grid grid-cols-2 sm:grid-cols-4 gap-3 mb-4">
        <Card className="p-3"><div className="flex items-center gap-2 text-[var(--faint)] text-xs mb-1"><Cpu size={13} /> {t('sp.cores', 'CPU cores')}</div><div className="text-xl font-bold tabular-nums">{totals.cpuCores ?? '—'}</div></Card>
        <Card className="p-3"><div className="flex items-center gap-2 text-[var(--faint)] text-xs mb-1"><Gauge size={13} /> {t('sp.ramtotal', 'RAM total')}</div><div className="text-xl font-bold tabular-nums">{memUsedGB != null ? `${memUsedGB.toFixed(1)} / ${gb(totals.memTotalBytes).toFixed(1)} GB` : '—'}</div></Card>
        <Card className="p-3"><div className="flex items-center gap-2 text-[var(--faint)] text-xs mb-1"><HardDrive size={13} /> {t('sp.disktotal', 'Disk total')}</div><div className="text-xl font-bold tabular-nums">{diskUsedGB != null ? `${diskUsedGB.toFixed(0)} / ${gb(totals.diskTotalBytes).toFixed(0)} GB` : '—'}</div></Card>
        <Card className="p-3"><div className="flex items-center gap-2 text-[var(--faint)] text-xs mb-1"><ShieldCheck size={13} /> {t('sp.availability', 'Availability')}</div><div className="text-xl font-bold tabular-nums">{totals.uptimePct != null ? `${totals.uptimePct.toFixed(2)}%` : '—'}</div></Card>
      </div>

      <Card className="p-4 mb-4">
        <div className="flex items-center justify-between mb-2">
          <span className="text-xs font-semibold uppercase tracking-wider text-[var(--faint)]">{t('sp.history', 'CPU / Memory / Disk, history')}</span>
          <span className="flex items-center gap-3 text-[11px] text-[var(--muted)]"><span className="flex items-center gap-1"><span className="w-2.5 h-2.5 rounded-sm" style={{ background: '#f97316' }} /> CPU</span><span className="flex items-center gap-1"><span className="w-2.5 h-2.5 rounded-sm" style={{ background: '#38bdf8' }} /> Mem</span><span className="flex items-center gap-1"><span className="w-2.5 h-2.5 rounded-sm" style={{ background: '#a78bfa' }} /> Disk</span></span>
        </div>
        <MetricChart history={history} />
        {/* CPU and load come from the last stored sample, not from this instant. Saying how
            old it is turns "why is CPU 3% when the box is busy" into an answerable question. */}
        {sampleAgeMin != null && <div className="text-[11px] text-[var(--faint)] mt-2">{t('sp.sampleAge', 'CPU, load, latency and uptime are from the last sample, taken {n} min ago. Memory and disk are read live.').replace('{n}', String(sampleAgeMin))}</div>}
        {cg?.usedBytes != null && <div className="text-[11px] text-[var(--faint)] mt-2">This process's own cgroup memory: {(cg.usedBytes / 1024 / 1024).toFixed(0)} MB{cg.limitBytes ? ` / ${(cg.limitBytes / 1024 / 1024).toFixed(0)} MB allocated` : ' (no cgroup limit set — showing real usage only)'}.</div>}
        {/* A second machine writing into this history is a fact the admin must see, not a
            rendering problem to hide. It is exactly what produced the famous sawtooth: a dev
            machine pointed at the prod database, its samples interleaved with the server's,
            and the chart alternated between two real hosts every tick. The chart above now
            shows only THIS host's samples; this line says who else is writing. */}
        {/* .alert-warning, not raw amber shades. text-amber-200 over bg-amber-500/10 is
            legible on the dark theme and is pale yellow on pale yellow in the light one —
            the same family as the white-on-white bugs. The class uses --warning, which is
            a dark orange on light and a bright amber on dark. */}
        {/* Several hosts writing is a FACT, and it has two completely different causes: API
            replicas of this deployment (normal, and the reason the chart needs a selector),
            or a dev machine pointed at the production database (not normal). The panel cannot
            tell them apart — nothing in a hostname says which — so it states what it sees
            and lets the person who knows decide. It used to assert the second cause, which
            reads as an alarm every ten minutes on a perfectly healthy replicated install. */}
        {(data.hosts?.length || 0) > 1 && (
          <div className="text-[11px] mt-2 px-3 py-2 rounded-lg alert-info flex items-center gap-2 flex-wrap">
            <span>
              {t('srvperf.multihost', '{n} hosts are recording metrics into this database.').replace('{n}', String(data.hosts.length))}{' '}
              {t('srvperf.multihostHint', 'Replicas of this deployment, or something else pointed at the same database, a hostname cannot say which.')}{' '}
              {/* The count on its own reads as thirteen machines. Most of them are usually
                  containers that stopped existing at some past deploy and left their samples
                  behind — which is worth knowing before anybody goes looking for a fleet. */}
              {(() => {
                const live = data.hosts.filter((h) => h.live).length;
                const gone = data.hosts.length - live;
                return gone
                  ? <b>{t('srvperf.hostLive', '{n} still reporting; {g} stopped and left their history behind.')
                      .replace('{n}', String(live)).replace('{g}', String(gone))}</b>
                  : <b>{t('srvperf.hostAllLive', 'All of them are still reporting.')}</b>;
              })()}
            </span>
            <div className="flex-1" />
            <Select className="!w-auto !py-1 !text-[11px]" value={pickHost} onChange={(e) => setPickHost(e.target.value)}>
              <option value="">{t('srvperf.hostAnswering', 'This container ({h})').replace('{h}', data.host || '?')}</option>
              {data.hosts.map((h) => (
                <option key={h.host} value={h.host}>
                  {h.live ? '●' : '○'} {h.host} · {t('srvperf.hostSamples', '{n} samples').replace('{n}', String(h.samples))}
                  {h.lastAt ? ` · ${t('srvperf.hostLast', 'last {a}').replace('{a}', agoShort(h.lastAt))}` : ''}
                </option>
              ))}
              {/* Averaging only makes sense when the hosts are comparable. Offered, never
                  the default: a 4-vCPU server averaged with a 24-core dev box is the
                  sawtooth this column was added to kill, wearing a different hat. */}
              <option value="all">{t('srvperf.hostAll', 'All hosts together')}</option>
            </Select>
          </div>
        )}
      </Card>

      {/* Bandwidth served, broken down by what's consuming it (since the API last started). */}
      {(() => {
        const bw = data?.bandwidthByCat; if (!bw) return null;
        const rows = [['repo', t('sp.bw.repo', 'Repo downloads'), '#f97316'], ['catalog', t('sp.bw.catalog', 'Catalog / submissions'), '#38bdf8'], ['media', t('sp.bw.media', 'Media'), '#a78bfa'], ['other', t('sp.bw.other', 'App / API'), '#64748b']];
        const total = rows.reduce((a, [k]) => a + (bw[k] || 0), 0);
        return (
          <Card className="p-4 mb-4">
            <div className="flex items-center justify-between mb-2 flex-wrap gap-2">
              <span className="text-xs font-semibold uppercase tracking-wider text-[var(--faint)] flex items-center gap-1.5"><Download size={13} className="text-[var(--accent-ink)]" /> {t('sp.bw.title', 'Bandwidth served, by consumer')}</span>
              <span className="text-[11px] text-[var(--muted)] tabular-nums">{fmtBytes(total)} {t('sp.bw.since', 'since restart')}</span>
            </div>
            {total > 0 ? <>
              <div className="flex h-2.5 rounded-full overflow-hidden mb-2.5 bg-[var(--surface-2)]">
                {rows.map(([k, , c]) => (bw[k] || 0) > 0 && <div key={k} style={{ width: `${(bw[k] / total) * 100}%`, background: c }} title={`${bw[k]} B`} />)}
              </div>
              <div className="grid grid-cols-2 sm:grid-cols-4 gap-2 text-xs">
                {rows.map(([k, label, c]) => (
                  <div key={k} className="flex items-center gap-1.5"><span className="w-2.5 h-2.5 rounded-sm shrink-0" style={{ background: c }} /><span className="text-[var(--muted)] truncate" title={label}>{label}</span><span className="ms-auto tabular-nums font-medium">{Math.round(((bw[k] || 0) / total) * 100)}%</span></div>
                ))}
              </div>
              <p className="text-[11px] text-[var(--faint)] mt-2.5">{t('sp.bw.note', 'Counted from response sizes since the API last restarted. Telemetry runs as a separate service, so it isn’t included here.')}</p>
            </> : <div className="text-sm text-[var(--faint)]">{t('sp.bw.none', 'No traffic served yet since restart.')}</div>}
          </Card>
        );
      })()}

      {/* Per-repo ALLOCATED upload + live-served throughput and storage. (CPU is no
          longer a product dimension, so it's not shown here.) */}
      {(() => {
        const ra = data?.repoAllocations;
        if (!ra?.repos?.length) return null;
        return (
          <Card className="p-4 mb-4">
            <button onClick={() => toggleSec('alloc')} className="w-full flex items-center justify-between gap-2 mb-1 flex-wrap text-start">
              <span className="text-xs font-semibold uppercase tracking-wider text-[var(--faint)] flex items-center gap-1.5"><Server size={13} className="text-[var(--accent-ink)]" /> {t('sp.alloc', 'Per-repo allocation')} <span className="text-[var(--muted)] normal-case tracking-normal">· {ra.repos.length}</span></span>
              <span className="flex items-center gap-2">
                <span className="text-[11px] tabular-nums text-[var(--muted)] hidden sm:inline">
                  {t('sp.alloc.summary2', '{n} repo(s) · {u} Mbps total upload').replace('{n}', ra.repos.length).replace('{u}', ra.totalUploadMbps)}
                </span>
                <ChevronDown size={15} className={`text-[var(--faint)] transition-transform ${sec.alloc ? '' : '-rotate-90'}`} />
              </span>
            </button>
            {sec.alloc && (() => {
              const totUsed = ra.repos.reduce((a, r) => a + (r.storageUsedBytes || 0), 0);
              const totQuota = ra.repos.reduce((a, r) => a + (r.storageQuotaBytes || 0), 0);
              const totLive = ra.repos.reduce((a, r) => a + (r.liveUploadMbps || 0), 0);
              return (
              <>
                {/* Totals summary — live upload actually served + storage used across all repos. */}
                <div className="rounded-lg border border-[var(--line)] panel p-3 mb-3">
                  <div className="flex flex-wrap gap-x-5 gap-y-1 text-[11px] text-[var(--faint)]">
                    <span className="flex items-center gap-1.5">{totLive > 0 && <span className="w-1.5 h-1.5 rounded-full bg-success animate-pulse" />}{t('sp.alloc.uplivetot', 'Live upload (total)')}: <b className="text-[var(--text)] tabular-nums">{totLive.toFixed(2)} Mbps</b> <span className="text-[var(--faint)]">/ {ra.totalUploadMbps} {t('sp.alloc.reserved', 'reserved')}</span></span>
                    <span>{t('sp.alloc.stotot', 'Storage used (total)')}: <b className="text-[var(--text)] tabular-nums">{fmtBytes(totUsed)} / {fmtBytes(totQuota)}</b></span>
                  </div>
                </div>
                <div className="text-[11px] text-[var(--faint)] mb-2">{t('sp.alloc.note3', "Upload = throughput actually served right now vs the plan limit; Storage = what's actually stored vs the quota.")}</div>

                {/* Per-repo table — live upload + storage, each with a real used/total bar. */}
                <div className="max-h-96 overflow-auto -mx-1">
                  <table className="w-full text-sm border-collapse min-w-[480px]">
                    <thead>
                      <tr className="text-[10px] uppercase tracking-wider text-[var(--faint)]">
                        <th className="font-semibold text-start py-1.5 ps-1 pe-3 min-w-[150px]">{t('sp.repo', 'Repo')}</th>
                        <th className="font-semibold text-start py-1.5 px-3 min-w-[150px]">{t('sp.upload', 'Upload')}</th>
                        <th className="font-semibold text-start py-1.5 px-3 min-w-[130px]">{t('sp.delivered', 'Delivered')}</th>
                        <th className="font-semibold text-start py-1.5 ps-3 pe-1 min-w-[150px]">{t('sp.storage', 'Storage')}</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-[var(--line)]">
                      {ra.repos.map((r) => {
                        const stoUsed = r.storageQuotaBytes ? Math.min(100, (r.storageUsedBytes / r.storageQuotaBytes) * 100) : 0;
                        const stoTone = stoUsed >= 90 ? '#f87171' : stoUsed >= 70 ? '#f59e0b' : '#34d399';
                        const live = r.liveUploadMbps || 0;
                        const cap = r.uploadMbps || 0;
                        const upPct = cap > 0 ? Math.min(100, (live / cap) * 100) : (live > 0 ? 100 : 0);
                        return (
                          <tr key={r.id} className="hover:panel">
                            <td className="py-2 ps-1 pe-3 min-w-[150px]">
                              <div className="font-medium break-all leading-tight">{r.name}</div>
                              <div className="text-[11px] text-[var(--faint)] flex items-center gap-1.5 flex-wrap">{r.owner}{r.status !== 'ONLINE' && <Badge tone={r.status === 'SUSPENDED' ? 'red' : ''}>{rawStatusLabel(r.status, t)}</Badge>}</div>
                            </td>
                            {/* Live upload actually served now vs the plan limit (0 = idle). */}
                            <td className="py-2 px-3">
                              <div className="flex items-baseline justify-between gap-2 text-[11px] tabular-nums mb-1">
                                <span className="flex items-center gap-1">{live > 0 && <span className="w-1.5 h-1.5 rounded-full bg-success animate-pulse shrink-0" />}<b className="text-[var(--text)]">{live.toFixed(2)}</b> <span className="text-[var(--faint)]">/ {cap} Mbps</span></span>
                                <span className="text-[var(--faint)]">{live <= 0 ? t('sp.alloc.idle', 'idle') : t('sp.alloc.pctused', '{n}%').replace('{n}', upPct.toFixed(0))}</span>
                              </div>
                              <div className="h-1.5 rounded-full bg-[var(--surface-2)] overflow-hidden"><div className="h-full rounded-full bg-info transition-all" style={{ width: `${Math.max(live > 0 ? 3 : 0, upPct)}%` }} /></div>
                            </td>
                            {/* What we have ACTUALLY delivered, across every sample where this
                                repo was serving, against its own cap. The plans state a speed and
                                the terms call it a ceiling; this is the only place either claim can
                                be checked. A dash means it has never been seen transferring — which
                                is no data, not zero. */}
                            <td className="py-2 px-3">
                              {r.delivered ? (<>
                                <div className="flex items-baseline justify-between gap-2 text-[11px] tabular-nums mb-1">
                                  <span><b className="text-[var(--text)]">{r.delivered.avgMbps}</b> <span className="text-[var(--faint)]">{t('sp.avgof', 'avg of {n}').replace('{n}', r.delivered.samples)}</span></span>
                                  <span className={r.delivered.underPct >= 50 ? 'text-warning' : 'text-[var(--faint)]'}>{t('sp.under', '{n}% low').replace('{n}', r.delivered.underPct)}</span>
                                </div>
                                <div className="h-1.5 rounded-full bg-[var(--surface-2)] overflow-hidden">
                                  <div className="h-full rounded-full bg-success transition-all" style={{ width: `${cap > 0 ? Math.min(100, (r.delivered.avgMbps / cap) * 100) : 0}%` }} />
                                </div>
                                <div className="text-[10px] text-[var(--faint)] mt-1">{t('sp.peak', 'peak {n} Mbps').replace('{n}', r.delivered.maxMbps)}</div>
                              </>) : <span className="text-[11px] text-[var(--faint)]">{t('sp.nodata', 'never seen serving')}</span>}
                            </td>
                            {/* Storage actually used vs quota. */}
                            <td className="py-2 ps-3 pe-1">
                              <div className="flex items-baseline justify-between gap-2 text-[11px] tabular-nums mb-1">
                                <span><b className="text-[var(--text)]">{fmtBytes(r.storageUsedBytes)}</b> <span className="text-[var(--faint)]">/ {fmtBytes(r.storageQuotaBytes)}</span></span>
                                <span className="text-[var(--faint)]">{stoUsed < 0.5 ? t('sp.alloc.empty', 'empty') : t('sp.alloc.pctused', '{n}%').replace('{n}', stoUsed.toFixed(0))}</span>
                              </div>
                              <div className="h-1.5 rounded-full bg-[var(--surface-2)] overflow-hidden"><div className="h-full rounded-full" style={{ width: `${Math.max(2, stoUsed)}%`, background: stoTone }} /></div>
                            </td>
                          </tr>
                        );
                      })}
                    </tbody>
                  </table>
                </div>
              </>
              );
            })()}
          </Card>
        );
      })()}

      <div className="grid sm:grid-cols-2 gap-4 mb-4">
        <Card className="p-4">
          <div className="flex items-center justify-between gap-2 mb-2">
            <span className="text-xs font-semibold uppercase tracking-wider text-[var(--faint)]">{t('sp.deps', 'Dependencies')}</span>
            <div className="flex items-center gap-3">
              {!configuring && !!depKeys.length && (
                <button
                  className="text-[11px] text-[var(--muted)] hover:text-[var(--text)] hover:underline disabled:opacity-50"
                  disabled={rechecking} onClick={recheckDeps}
                >{rechecking ? t('sp.deps.checking', 'Checking…') : t('sp.deps.recheck', 'Check now')}</button>
              )}
              <button className="text-[11px] text-[var(--muted)] hover:text-[var(--text)] hover:underline" onClick={() => setConfiguring((c) => !c)}>{configuring ? t('sp.done', 'Done') : t('sp.configure', 'Configure')}</button>
            </div>
          </div>
          {configuring ? (
            <div className="space-y-1.5">
              {allKeys.map((k) => (
                <label key={k} className="flex items-start gap-2 text-sm">
                  <input type="checkbox" className="mt-1" disabled={depsBusy} checked={enabledCfg[k] !== false} onChange={(e) => toggleDep(k, e.target.checked)} />
                  <span className="min-w-0">
                    {labels[k] || k}
                    <span className="block text-[11px] text-[var(--muted)] leading-snug">{DEP_WHAT(t)[k]}</span>
                  </span>
                </label>
              ))}
              {/* Turning one off is not cosmetic: it stops the probe, so that service can no
                  longer open an outage. Worth saying next to the switches rather than in a
                  place somebody would have to already suspect. */}
              <p className="text-[11px] text-[var(--muted)] pt-1.5 border-t border-[var(--line)] leading-snug">
                {t('sp.deps.cfg.h', 'Unticking one stops probing it. It disappears from here AND stops being able to record an outage — the status page will never show it as down.')}
              </p>
            </div>
          ) : (<>
            {/* One line per dependency, not a row of pills.
                Pills answered exactly one question — "is anything red" — and to answer it you
                read six labels in a wrapped row where the order changed with the width. A list
                holds still, has room for the response time beside each name, and can tint the
                one that is failing so it is found rather than searched for. */}
            {depKeys.length ? (
              <div className="divide-y divide-[var(--line)] -mx-1">
                {depKeys.map((k) => {
                  const ok = deps[k];
                  const ms = depsDetail?.[k]?.ms ?? null;
                  return (
                    <div
                      key={k}
                      title={DEP_WHAT(t)[k] || ''}
                      className={`flex items-center gap-2 px-1 py-1.5 ${ok === false ? 'bg-error-bg rounded' : ''}`}
                    >
                      <span className={`w-1.5 h-1.5 rounded-full shrink-0 ${ok === null ? 'bg-[var(--faint)]' : ok ? 'bg-success' : 'bg-error'}`} />
                      <span className={`text-sm min-w-0 truncate ${ok === false ? 'text-error font-medium' : ''}`}>{labels[k] || k}</span>
                      <span className="ms-auto text-[11px] tabular-nums text-[var(--faint)] shrink-0">
                        {/* The number, when there is one. A check that answered "not applicable"
                            never ran, so timing it would be a figure about nothing. */}
                        {ok === null
                          ? t('sp.deps.na', 'not configured')
                          : ok === false
                            ? t('sp.deps.down', 'no answer')
                            : ms == null ? '' : `${ms} ms`}
                      </span>
                    </div>
                  );
                })}
              </div>
            ) : <span className="text-xs text-[var(--faint)]">{t('sp.deps.off', 'All dependency checks are disabled.')}</span>}

            {/* Six pills with no sentence anywhere saying what green MEANT, how often it is
                re-checked, or that this is what writes the outage records the public status
                page reads. It looked like decoration and it is the input. */}
            {!!depKeys.length && (<>
              {/* WHEN, which the panel could not say at all. These answers are served
                  stale-while-revalidate, so a green dot may be two minutes old — or, just
                  after a restart, from a probe that has not come back yet. Without the
                  timestamp there is no way to tell either of those from a live reading. */}
              <p className="text-[11px] text-[var(--muted)] mt-2">
                {depsUp != null && (
                  <span className={depsUp < depsRan ? 'text-error font-medium' : ''}>
                    {t('sp.deps.upN', '{n} of {m} responding').replace('{n}', String(depsUp)).replace('{m}', String(depsRan))}
                  </span>
                )}
                {depsAt && <> · {t('sp.deps.at', 'checked {ago} ago').replace('{ago}', agoShort(depsAt))}</>}
              </p>
              <p className="text-[11px] text-[var(--muted)] mt-1.5 leading-snug">
                {t('sp.deps.h', 'Each one is really contacted — a query, or an HTTP request — not self-reported. Re-checked every few minutes. A red one opens an outage on the public status page and closes it when it comes back, so this is what uptime is measured from.')}
              </p>
            </>)}
          </>)}
        </Card>
        <Card className="p-4">
          <div className="text-xs font-semibold uppercase tracking-wider text-[var(--faint)] mb-2 flex items-center gap-1.5"><Lock size={11} /> {t('sp.ssl', 'SSL certificate')}</div>
          {ssl?.notHttps ? <div className="text-xs text-[var(--muted)] flex items-center gap-1.5"><Info size={12} className="text-[var(--accent-ink)] shrink-0" /> {t('sp.ssl.nohttps', 'SITE_URL is http://, no certificate to probe. HTTPS is provisioned & auto-renewed by Caddy/Let’s Encrypt in production.')}</div>
            : ssl?.daysLeft != null ? <div className="text-sm">{ssl.daysLeft <= 14 ? <Badge tone="red">{t('sp.ssl.left', '{n}d left').replace('{n}', ssl.daysLeft)}</Badge> : ssl.daysLeft <= 30 ? <Badge tone="amber">{t('sp.ssl.left', '{n}d left').replace('{n}', ssl.daysLeft)}</Badge> : <Badge tone="green">{t('sp.ssl.left', '{n}d left').replace('{n}', ssl.daysLeft)}</Badge>} <span className="text-[var(--faint)] text-xs">{t('sp.ssl.expires', 'expires {d}').replace('{d}', new Date(ssl.expiresAt).toLocaleDateString())}</span></div>
            : <div className="text-xs text-[var(--faint)]">{t('sp.ssl.noprobe', "Couldn't probe SITE_URL's certificate.")}</div>}
        </Card>
      </div>


      {/* The thresholds those alerts fire on, right above the alerts themselves — you
          read the list, then change what produced it. */}
      <div className="mt-8 pt-6 border-t border-[var(--line)]">
        <h3 className="text-xs font-semibold uppercase tracking-wider text-[var(--faint)] mb-2">{t('sp.th.title', 'Alert thresholds')}</h3>
        <AlertThresholds />
      </div>

      <div className="mt-8 pt-6 border-t border-[var(--line)]">
        <button onClick={() => toggleSec('alerts')} className="w-full flex items-center justify-between text-start mb-2">
          {/* The count was a muted grey "· 7" — fine as a size, useless as a signal. Simple mode
              keeps this section closed, so an UNACKNOWLEDGED alert has to be visible on the
              header itself or a collapsed section is hiding a live problem. */}
          <h3 className="text-xs font-semibold uppercase tracking-wider text-[var(--faint)] flex items-center gap-1.5 flex-wrap">
            {t('sp.alerts', 'Alerts')}
            {(() => {
              const all = alerts.data?.alerts || [];
              const c = alerts.data?.counts;
              if (!all.length) return null;
              // Ordered by what makes somebody open the section. A count of unacknowledged
              // rows says how much reading is left; a count of ONGOING ones says whether
              // anything is broken, and only the second is a reason to look now. Simple mode
              // keeps this section closed, so both have to survive on the header itself.
              return (<>
                {c?.criticalOngoing > 0 && <Badge tone="red"><OctagonAlert size={9} /> {t('sp.al.critnow', '{n} critical, still happening').replace('{n}', c.criticalOngoing)}</Badge>}
                {c?.ongoing > c?.criticalOngoing && <Badge tone="amber"><AlertTriangle size={9} /> {t('sp.al.ongoingn', '{n} still happening').replace('{n}', c.ongoing - c.criticalOngoing)}</Badge>}
                {!c?.ongoing && <Badge tone="green"><CheckCircle2 size={9} /> {t('sp.al.allclear', 'Nothing ongoing')}</Badge>}
                {c?.unacked > 0 && <span className="text-[var(--muted)] normal-case tracking-normal">{t('sp.al.unacked', '{n} unacknowledged').replace('{n}', c.unacked)}</span>}
              </>);
            })()}
          </h3>
          <ChevronDown size={15} className={`text-[var(--faint)] transition-transform ${sec.alerts ? '' : '-rotate-90'}`} />
        </button>
        {sec.alerts && (alerts.loading ? <Loading /> : (() => {
          const list = alerts.data?.alerts || [];
          if (!list.length) return <EmptyState icon={CheckCircle2} title={t('sp.alerts.none', 'No alerts')} sub={t('sp.alerts.nonesub', 'Nothing has crossed a threshold yet.')} />;
          // Collapse repeats of the exact same alert (kind+message) into one row with a
          // count + first/last seen, so a long outage doesn't read as a wall of dupes.
          // A group is ongoing if ANY sighting in it is: the oldest row is the one that is
          // still open, and hiding that behind the newest would say "over" about a live
          // problem, which is the one mistake this list cannot afford.
          const groups = [];
          const byKey = new Map();
          for (const a of list) {
            const key = `${a.kind}::${a.message}`;
            if (byKey.has(key)) {
              const g = byKey.get(key);
              g.count++; g.firstAt = a.createdAt;
              if (!a.resolvedAt) g.resolvedAt = null;
            } else { const g = { ...a, count: 1, firstAt: a.createdAt, lastAt: a.createdAt }; byKey.set(key, g); groups.push(g); }
          }
          const live = groups.filter((g) => !g.resolvedAt);
          const done = groups.filter((g) => g.resolvedAt);
          const copyAll = async () => {
            const log = [
              `BetterCommunity server-perf alerts`,
              `exported: ${new Date().toISOString()}`,
              ``,
              ...groups.map((g) => `[${g.kind}] ${g.message}${g.count > 1 ? ` (×${g.count})` : ''} — last ${new Date(g.lastAt).toLocaleString()}${g.count > 1 ? `, first ${new Date(g.firstAt).toLocaleString()}` : ''}`),
            ].join('\n');
            const ok = await copyText(log);
            ok ? toast.success(t('common.copied', 'Copied.')) : toast.error(t('sp.al.copyfail', 'Could not copy, select the alerts manually.'));
          };
          const unacked = ackPending ? 0 : list.filter((a) => !a.ackAt).length;
          return (<>
            <div className="flex justify-end gap-2 mb-1.5">
              {unacked > 0 && (
                <Button size="sm" variant="ghost" onClick={ackAll} title={t('sp.al.ack.h', 'Clears the badge on this tab. The condition itself is unchanged.')}>
                  <CheckCircle2 size={12} /> {t('sp.al.ack', 'Mark {n} as seen').replace('{n}', String(unacked))}
                </Button>
              )}
              <Button size="sm" variant="ghost" onClick={copyAll}><Copy size={12} /> {t('sp.al.copyall', 'Copy all')}</Button>
            </div>
            {/* Two lists, not one sorted list. "Is anything broken" and "what happened
                lately" are different questions, and a heading answers the first one even
                when the second is forty rows long. */}
            <div className="space-y-1.5 max-h-96 overflow-auto pe-1 -me-1">
              {live.length > 0 && (<>
                <div className="text-[11px] font-semibold uppercase tracking-wider text-[var(--error)] pt-0.5">{t('sp.al.live', 'Still happening')} · {live.length}</div>
                {live.map((g) => <AlertRow key={g.id} a={g} />)}
              </>)}
              {done.length > 0 && (<>
                <div className="text-[11px] font-semibold uppercase tracking-wider text-[var(--faint)] pt-2">{t('sp.al.past', 'Over')} · {done.length}</div>
                {done.map((g) => <AlertRow key={g.id} a={g} />)}
              </>)}
            </div>
          </>);
        })())}
      </div>

      {/* One outage history, not two.
          There were two sections answering "when was it broken", from different sources and
          disagreeing about what an outage even is: the gaps in our own sampling (the server
          itself was down or restarting) and the periods a dependency was unreachable. Both
          are outages to whoever was refused, so they are one list — with the source named on
          each row, because "the database was unreachable for 8 minutes" and "the whole
          process was gone for 10 hours" call for very different reactions.
          A Card, like everything else on this page: a bare div ignores the translucent-
          surfaces setting and reads as loose text rather than as a panel. */}
      <Card className="p-4 mt-4">
        <button onClick={() => toggleSec('outages')} className="w-full flex items-center justify-between text-start mb-2">
          <span className="text-xs font-semibold uppercase tracking-wider text-[var(--faint)] flex items-center gap-1.5">
            <AlertTriangle size={11} /> {t('sp.out.title', 'Outage history')}
            {mergedOutages.length > 0 && <span className="text-[var(--muted)] normal-case tracking-normal">· {mergedOutages.length}</span>}
            {mergedOutages.some((o) => o.ongoing) && <span className="text-error normal-case tracking-normal">· {t('sp.out.ongoing', 'one is ongoing')}</span>}
          </span>
          <ChevronDown size={15} className={`text-[var(--faint)] transition-transform ${sec.outages ? '' : '-rotate-90'}`} />
        </button>
        {sec.outages && (outages.loading && !outages.data ? <Loading /> : !mergedOutages.length ? (
          <EmptyState icon={CheckCircle2} title={t('sp.out.none', 'No outage recorded')}
            sub={t('sp.out.nonesub3', 'Nothing has been unreachable, and the server has not stopped reporting, in the window kept. Both are measured by the same 10-minute check, so an outage shorter than 10 minutes is invisible to it.')} />
        ) : (<>
          {/* Happening NOW, said before the history. Somebody who opens this page during an
              incident is not browsing — they want what is down, since when, and whether it
              is the box or a dependency, without reading a list to find out. */}
          {liveOutages.length > 0 && (
            <div className="rounded-xl border b-error tint-error p-3 mb-3">
              <div className="flex items-center gap-2 text-sm font-semibold text-[var(--error)]">
                <span className="relative flex h-2 w-2 shrink-0">
                  {/* Motion is the fastest way to read "this is not history". Guarded by the
                      reduced-motion preference, where the ring is simply static. */}
                  <span className="motion-safe:animate-ping absolute inline-flex h-full w-full rounded-full bg-[var(--error)] opacity-60" />
                  <span className="relative inline-flex rounded-full h-2 w-2 bg-[var(--error)]" />
                </span>
                {liveOutages.length === 1
                  ? t('sp.out.live1', 'Something is down right now')
                  : t('sp.out.liveN', '{n} things are down right now').replace('{n}', String(liveOutages.length))}
              </div>
              <div className="mt-2 space-y-1.5">
                {liveOutages.map((o) => (
                  <div key={`live-${o.key}`} className="text-[13px] flex flex-wrap items-baseline gap-x-2">
                    <b>{o.label}</b>
                    <span className="text-[var(--muted)]">
                      {o.source === 'server'
                        ? t('sp.out.live.server', 'the server has stopped reporting, the process is down or restarting')
                        : t('sp.out.live.dep', 'not answering its check')}
                    </span>
                    <span className="tabular-nums text-[var(--error)] font-medium">
                      {t('sp.out.live.for', 'for {d}').replace('{d}', fmtDur(realSeconds(o)))}
                    </span>
                    <span className="text-[11px] text-[var(--faint)] tabular-nums">
                      {t('sp.out.live.since', 'since {t}').replace('{t}', new Date(o.startedAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }))}
                    </span>
                  </div>
                ))}
              </div>
              {/* What the number can and cannot tell you. The probes run on an interval, so
                  "0 min" during an incident means "less than one round", not "fine". */}
              <div className="text-[11px] text-[var(--faint)] mt-2">
                {t('sp.out.live.note', 'Checked every 10 minutes, so the start time is accurate to within one round. This panel refreshes itself while an outage lasts.')}
              </div>
            </div>
          )}

          {/* Availability per source, including the server itself. A percentage without the
              time behind it is a number you cannot argue with, so both are shown. */}
          {uptimeRows.length > 0 && (
            <div className="flex flex-wrap gap-2 mb-3">
              {uptimeRows.map((u) => (
                <span key={u.key} className="text-[11px] px-2 py-1 rounded-lg bg-[var(--surface-2)] border border-[var(--line)]">
                  {u.label} · <b className={u.pct < 99 ? 'text-warning' : ''}>{u.pct}%</b>{' '}
                  <span className="text-[var(--faint)]">({fmtDur(u.downSeconds)} {t('sp.out.down', 'down')})</span>
                </span>
              ))}
            </div>
          )}

          <div className="flex justify-end mb-1.5">
            <Button size="sm" variant="ghost" onClick={copyOutages}><Copy size={12} /> {t('sp.al.copyall', 'Copy all')}</Button>
          </div>

          <div className="space-y-1.5 max-h-96 overflow-auto pe-1 -me-1">
            {mergedOutages.map((o) => {
              const from = new Date(o.startedAt);
              const to = o.endedAt ? new Date(o.endedAt) : null;
              const sameDay = to && from.toDateString() === to.toDateString();
              const time = (x) => x.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
              const day = (x) => x.toLocaleDateString([], { day: 'numeric', month: 'short' });
              return (
                <div key={o.key} role="button" tabIndex={0} onClick={() => setOutageOpen(o)}
                  onKeyDown={(ev) => { if (ev.key === 'Enter' || ev.key === ' ') { ev.preventDefault(); setOutageOpen(o); } }}
                  className="flex items-start gap-3 text-sm rounded-lg border border-[var(--line)] bg-[var(--surface-2)] px-3 py-2 group cursor-pointer hover:border-[var(--ring)] transition-colors">
                  <Badge tone={o.ongoing ? 'red' : o.seconds >= 3600 ? 'red' : 'amber'} className="shrink-0 tabular-nums mt-0.5">{fmtDur(realSeconds(o))}</Badge>
                  <div className="min-w-0 flex-1">
                    <div className="flex items-center gap-1.5 flex-wrap">
                      <span className="font-medium">{o.label}</span>
                      {/* The source, said plainly: one of these means the box fell over. */}
                      <span className="text-[10px] uppercase tracking-wider text-[var(--faint)]">
                        {o.source === 'server' ? t('sp.out.src.server', 'stopped reporting') : t('sp.out.src.dep', 'unreachable')}
                      </span>
                      {o.ongoing && (
                        <span className="text-[10px] uppercase tracking-wider text-error inline-flex items-center gap-1">
                          <span className="motion-safe:animate-pulse inline-block w-1.5 h-1.5 rounded-full bg-[var(--error)]" />
                          {t('sp.out.stillnow', 'still down')}
                        </span>
                      )}
                    </div>
                    {o.cause && <div className="text-[11px] text-[var(--muted)] break-words">{o.cause}</div>}
                    <div className="text-[11px] text-[var(--faint)] tabular-nums">
                      {sameDay
                        ? <>{day(from)} · {time(from)} → {time(to)}</>
                        : to ? <>{day(from)} {time(from)} → {day(to)} {time(to)}</> : <>{day(from)} {time(from)} → …</>}
                      {' · '}{from.getFullYear()}
                    </div>
                  </div>
                  <button onClick={(ev) => { ev.stopPropagation(); copyText(outageLine(o)); toast.success(t('common.copied', 'Copied.')); }}
                    className="text-[var(--faint)] hover:text-[var(--accent-ink)] shrink-0 opacity-0 group-hover:opacity-100 transition mt-0.5"
                    title={t('common.copy', 'Copy')}><Copy size={12} /></button>
                </div>
              );
            })}
          </div>
          {outageOpen && (
            <Modal open onClose={() => setOutageOpen(null)} width="max-w-lg" icon={AlertTriangle}
              title={`${outageOpen.label} · ${fmtDur(realSeconds(outageOpen))}`}>
              <div className="space-y-3 text-[13px]">
                {outageOpen.cause && <div className="rounded-lg bg-[var(--surface-2)] border border-[var(--line)] p-3 break-words">{outageOpen.cause}</div>}
                <div className="grid sm:grid-cols-2 gap-x-4 gap-y-1.5">
                  {[
                    [t('sp.out.d.what', 'What'), outageOpen.label],
                    [t('sp.out.d.kind', 'Kind'), outageOpen.source === 'server' ? t('sp.out.src.server', 'stopped reporting') : t('sp.out.src.dep', 'unreachable')],
                    [t('sp.out.d.from', 'Started'), new Date(outageOpen.startedAt).toLocaleString()],
                    [t('sp.out.d.to', 'Ended'), outageOpen.endedAt ? new Date(outageOpen.endedAt).toLocaleString() : t('sp.out.stillnow', 'still down')],
                    [t('sp.out.d.dur', 'Duration'), fmtDur(outageOpen.seconds)],
                  ].map(([k, v]) => (
                    <div key={k} className="flex items-baseline gap-2 min-w-0">
                      <span className="text-[10px] uppercase tracking-wider text-[var(--faint)] w-20 shrink-0">{k}</span>
                      <span className="break-words min-w-0">{v}</span>
                    </div>
                  ))}
                </div>
                {/* The measurement itself, said here rather than in a footnote: whether a
                    gap is real or just shorter than the check is the first question anybody
                    asks of an outage record. */}
                <p className="text-[11px] text-[var(--muted)]">
                  {outageOpen.source === 'server'
                    ? t('sp.out.d.srvnote', 'Measured as a gap in our own samples: the process recorded nothing for this period, which is what being down looks like from the inside.')
                    : t('sp.out.d.depnote', 'Measured by the dependency check that runs every ten minutes. An incident shorter than one interval is invisible to it.')}
                </p>
                <div className="flex gap-2">
                  <Button size="sm" variant="ghost" onClick={() => { copyText(outageLine(outageOpen)); toast.success(t('common.copied', 'Copied.')); }}><Copy size={12} /> {t('common.copy', 'Copy')}</Button>
                </div>
              </div>
            </Modal>
          )}
          <p className="text-[11px] text-[var(--muted)] mt-2">{t('sp.out.s2', 'A dependency outage is measured by the 10-minute dependency check; a “stopped reporting” one is a gap in our own samples, which is what being down looks like from the inside. Neither can see an incident shorter than one interval.')}</p>
        </>))}
      </Card>

      {/* Real-user Web Vitals — moved here from the Site-analytics tab so all
          performance (server-side + client-side) lives on one Server-perf tab.
          Collapsible + separated so it isn't jammed against the alerts list. */}
      <div className="mt-8 pt-6 border-t border-[var(--line)]">
        <button onClick={() => toggleSec('vitals')} className="w-full flex items-center justify-between text-start mb-2">
          <h3 className="text-xs font-semibold uppercase tracking-wider text-[var(--faint)] flex items-center gap-1.5"><Gauge size={13} /> {t('sp.vitals', 'Web Vitals (real-user)')}</h3>
          <ChevronDown size={15} className={`text-[var(--faint)] transition-transform ${sec.vitals ? '' : '-rotate-90'}`} />
        </button>
        {sec.vitals && <WebVitals />}
      </div>
    </div>
  );
}

// A tiny in-container file browser, confined server-side to FILES_ROOT — good for
// inspecting the deployed code/config, not a general host filesystem browser.
// Two-step confirmation for actions that touch live server files/DB rows: a
// normal confirm dialog, then a second dialog that requires literally typing
// CONFIRM — the same token the backend independently re-checks (server-
// control.mjs's requireConfirm()), so this isn't just a UI speed bump.
// Type CONFIRM, THEN press the red button — in that order.
//
// It used to be the other way round: the danger button first, then a prompt whose OK was a
// generic "Continue". So the last gesture before something irreversible happened was an
// ordinary OK on a text box, which is exactly the click people make without reading. Now
// the typing is the speed bump and the final, deliberate act is pressing the red button
// that names what it will do.
async function doubleConfirm(dialog, { title, message, okLabel = 'Continue' }) {
  const typed = await dialog.prompt({
    title,
    message,
    label: `Type CONFIRM to continue.`,
    placeholder: 'CONFIRM',
    okLabel: 'Next',
  });
  if (typed !== 'CONFIRM') return false;
  return dialog.confirm({ title, message, okLabel, danger: true });
}

function FileManager() {
  const toast = useToast(); const dialog = useDialog(); const { t } = useI18n();
  const [dir, setDir] = useState('.');
  const [data, setData] = useState(null);
  const [editing, setEditing] = useState(null);
  const [busy, setBusy] = useState(false);
  const [q, setQ] = useState('');
  const [history, setHistory] = useState(null); // { path, items } for the backup-history modal
  const [trash, setTrash] = useState(null);     // deleted-but-restorable files, or null while closed
  const undoable = useUndoableSave(() => load(dir));

  const load = (d) => api.get(`/server/files?path=${encodeURIComponent(d)}`).then((r) => { setData(r); setDir(r.path); setQ(''); }).catch(() => toast.error(t('fm.listfail', 'Failed to list.')));
  useEffect(() => { load('.'); /* eslint-disable-next-line */ }, []);

  const openEntry = async (e) => {
    const full = dir === '.' ? e.name : `${dir}/${e.name}`;
    if (e.isDir) return load(full);
    try { const r = await api.get(`/server/files/read?path=${encodeURIComponent(full)}`); setEditing({ path: r.path, content: r.content }); }
    catch (x) { toast.error(x.data?.error === 'too_large' ? t('fm.toolarge', 'File too large to view here, use download instead.') : t('fm.readfail', 'Failed to read (probably binary, use download instead).')); }
  };
  const up = () => { const parts = dir.split('/').filter((x) => x !== '.'); parts.pop(); load(parts.length ? parts.join('/') : '.'); };
  // DELIBERATELY NOT behind the undo window. The undo window is a convenience for edits you
  // might regret, not a safety mechanism — and for this action a six-second "maybe" is worse
  // than a plain yes: you want to know, at the moment you click, that it has taken effect.
  const saveFile = async () => {
    if (!(await doubleConfirm(dialog, { title: t('fm.savechanges', 'Save changes'), message: t('fm.saveconfirm', 'Overwrite "{p}" on the live server? A backup of the current content is kept automatically.').replace('{p}', editing.path), okLabel: t('common.save', 'Save') }))) return;
    setBusy(true);
    try { await api.put('/server/files/write', { path: editing.path, content: editing.content, confirmToken: 'CONFIRM' }); toast.success(t('fm.savedbackup', 'Saved, a backup of the previous version was kept.')); setEditing(null); }
    catch { toast.error(t('fm.savefail', 'Failed to save.')); } finally { setBusy(false); }
  };
  // Deleting is the one action here worth two safety nets, because it is the one whose
  // damage is invisible: the file simply stops being in the list.
  //
  //   1. A six-second undo window, during which the request has not been sent at all.
  //   2. If it does commit, the file is still in the backup repo and now appears under
  //      "Recently deleted" below — which is the half that was missing. Restore has always
  //      existed, but it needed a path to ask about, and a deleted file has no row to
  //      click on. You could only recover a file whose exact path you still remembered.
  //
  // Saving an edit keeps its immediate semantics on purpose (see saveFile above): there
  // the version history is the way back, and a six-second "maybe" is worse than a yes.
  const delEntry = async (e) => {
    const full = dir === '.' ? e.name : `${dir}/${e.name}`;
    if (!(await doubleConfirm(dialog, { title: t('fm.del', 'Delete'), message: t('fm.delconfirm2', 'Delete "{p}"? A backup is kept and it can be restored from "Recently deleted".').replace('{p}', full), okLabel: t('fm.del', 'Delete') }))) return;
    undoable(
      () => api.del(`/server/files?path=${encodeURIComponent(full)}&confirmToken=CONFIRM`),
      t('fm.deletedundo', 'Deleted “{p}”.').replace('{p}', full),
    );
  };

  const loadTrash = async () => {
    try { const r = await api.get('/server/files/deleted'); setTrash(r.deleted || []); }
    catch { toast.error(t('fm.trashfail', 'Failed to list deleted files.')); }
  };
  const restoreDeleted = async (row) => {
    if (!(await doubleConfirm(dialog, {
      title: t('fm.undelete', 'Restore this file'),
      message: t('fm.undeleteconfirm', 'Write "{p}" back to the server, with the content it had just before it was deleted?').replace('{p}', row.path),
      okLabel: t('fm.restorebtn', 'Restore'),
    }))) return;
    // Behind the undo window like the delete it reverses: writing a file onto a live
    // server is worth the same six seconds of grace as removing one.
    undoable(
      async () => { await api.post(`/server/files/backups/${row.hash}/restore`, { path: row.path, confirmToken: 'CONFIRM' }); await loadTrash(); },
      t('fm.restoredundo', 'Restored “{p}”.').replace('{p}', row.path),
    );
  };
  const viewHistory = async (full) => {
    try { const r = await api.get(`/server/files/backups?path=${encodeURIComponent(full)}`); setHistory({ path: full, items: r.history }); }
    catch { toast.error(t('fm.histfail', 'Failed to load history.')); }
  };
  const restoreVersion = async (hash) => {
    if (!(await doubleConfirm(dialog, { title: t('fm.restore', 'Restore this version'), message: t('fm.restoreconfirm', 'Overwrite "{p}" with the version from this backup? The current content is backed up first.').replace('{p}', history.path), okLabel: t('fm.restorebtn', 'Restore') }))) return;
    const path = history.path;
    setHistory(null);
    undoable(
      () => api.post(`/server/files/backups/${hash}/restore`, { path, confirmToken: 'CONFIRM' }),
      t('fm.restoredundo', 'Restored “{p}”.').replace('{p}', path),
    );
  };
  const newFolder = async () => {
    const name = await dialog.prompt({ title: t('fm.newfolder', 'New folder'), label: t('fm.foldername', 'Folder name'), placeholder: 'assets' });
    if (!name) return;
    const full = dir === '.' ? name : `${dir}/${name}`;
    try { await api.post('/server/files/mkdir', { path: full }); toast.success(t('fm.created', 'Created.')); load(dir); }
    catch (x) { toast.error(x.data?.error === 'already_exists' ? t('fm.exists', 'Already exists.') : t('common.failed', 'Failed.')); }
  };
  const newFile = async () => {
    const name = await dialog.prompt({ title: t('fm.newfile', 'New file'), label: t('fm.filename', 'File name'), placeholder: 'notes.txt' });
    if (!name) return;
    const full = dir === '.' ? name : `${dir}/${name}`;
    try { await api.put('/server/files/write', { path: full, content: '' }); toast.success(t('fm.created', 'Created.')); load(dir); }
    catch { toast.error(t('common.failed', 'Failed.')); }
  };
  const rename = async (e) => {
    const newName = await dialog.prompt({ title: t('fm.renametitle', 'Rename "{n}"').replace('{n}', e.name), label: t('fm.newname', 'New name'), placeholder: e.name });
    if (!newName || newName === e.name) return;
    const full = dir === '.' ? e.name : `${dir}/${e.name}`;
    try { await api.put('/server/files/rename', { path: full, newName }); toast.success(t('fm.renamed', 'Renamed.')); load(dir); }
    catch (x) { toast.error(x.data?.error === 'bad_name' ? t('fm.badname', 'Invalid name.') : t('common.failed', 'Failed.')); }
  };
  const downloadEntry = (e) => {
    const full = dir === '.' ? e.name : `${dir}/${e.name}`;
    window.open(`/api/server/files/download?path=${encodeURIComponent(full)}`, '_blank');
  };

  const crumbs = dir === '.' ? [] : dir.split('/').filter(Boolean);
  const entries = (data?.entries || []).filter((e) => !q.trim() || e.name.toLowerCase().includes(q.trim().toLowerCase()));

  return (
    <Card className="p-4">
      <div className="flex items-center gap-2 mb-2 text-sm flex-wrap">
        <FileText size={14} className="text-[var(--accent-ink)] shrink-0" /> <span className="font-semibold shrink-0">{t('fm.title', 'File manager')}</span>
        <div className="flex items-center gap-1 text-xs font-mono text-[var(--faint)] min-w-0 overflow-x-auto">
          <button onClick={() => load('.')} className="hover:text-[var(--accent-ink)] shrink-0">/</button>
          {crumbs.map((c, i) => (
            <span key={i} className="flex items-center gap-1 shrink-0">
              <button onClick={() => load(crumbs.slice(0, i + 1).join('/'))} className="hover:text-[var(--accent-ink)]">{c}</button>
              {i < crumbs.length - 1 && <span>/</span>}
            </span>
          ))}
        </div>
        <div className="flex-1" />
        <Button size="sm" onClick={newFolder}><Plus size={12} /> {t('fm.folder', 'Folder')}</Button>
        <Button size="sm" onClick={newFile}><Plus size={12} /> {t('fm.file', 'File')}</Button>
        {/* The way back to something you cannot browse to. */}
        <Button size="sm" variant={trash ? 'primary' : 'ghost'} onClick={() => (trash ? setTrash(null) : loadTrash())}>
          <RotateCcw size={12} /> {t('fm.trash', 'Recently deleted')}
        </Button>
        {dir !== '.' && <Button size="sm" onClick={up}>{t('fm.up', 'Up')}</Button>}
      </div>
      {editing ? (
        <div>
          <div className="flex items-center justify-between mb-1">
            <div className="text-xs text-[var(--faint)] font-mono">{editing.path}</div>
            <button onClick={() => viewHistory(editing.path)} className="text-xs text-[var(--faint)] hover:text-[var(--accent-ink)] flex items-center gap-1"><History size={12} /> {t('fm.history', 'History')}</button>
          </div>
          <textarea value={editing.content} onChange={(e) => setEditing({ ...editing, content: e.target.value })} className="w-full h-64 font-mono text-xs bg-[var(--surface-2)] rounded-lg p-3 outline-none" spellCheck={false} />
          <div className="flex gap-2 mt-2"><Button variant="primary" disabled={busy} onClick={saveFile}>{busy ? <Spinner /> : t('common.save', 'Save')}</Button><Button onClick={() => setEditing(null)}>{t('su.cancel', 'Cancel')}</Button></div>
        </div>
      ) : trash ? (
        /* The deleted list REPLACES the browser rather than sitting beside it: it answers
           a different question ("what did I lose"), and mixing the two invites restoring a
           file into whichever directory you happen to be standing in. */
        <div>
          <div className="flex items-center justify-between gap-2 mb-2">
            <div className="text-xs text-[var(--muted)]">
              {t('fm.trash.desc', 'Files deleted through this manager that are still gone. Restoring writes back the content it had just before the delete.')}
            </div>
            <Button size="sm" onClick={() => setTrash(null)}>{t('common.close', 'Close')}</Button>
          </div>
          {!trash.length ? (
            <EmptyState icon={RotateCcw} title={t('fm.trash.none.t', 'Nothing deleted')} sub={t('fm.trash.none.s', 'Files removed here would be listed for restoring.')} />
          ) : (
            <div className="divide-y divide-[var(--line)]">
              {trash.map((row) => (
                <div key={`${row.path}-${row.hash}`} className="flex items-center gap-3 py-2">
                  <FileText size={14} className="text-[var(--faint)] shrink-0" />
                  <div className="min-w-0 flex-1">
                    <div className="text-sm font-mono truncate" title={row.path}>{row.path}</div>
                    <div className="text-[11px] text-[var(--faint)]">
                      {t('fm.trash.when', 'deleted {d}').replace('{d}', new Date(row.at).toLocaleString())} · {row.hash.slice(0, 8)}
                    </div>
                  </div>
                  {/* Download before restoring — sometimes you want the content back
                      without putting the file back onto a live server. */}
                  <a href={`/api/server/files/backups/${row.hash}/download?path=${encodeURIComponent(row.path)}`} download>
                    <Button size="sm" variant="ghost"><Download size={13} /></Button>
                  </a>
                  <Button size="sm" variant="primary" onClick={() => restoreDeleted(row)}>
                    <RotateCcw size={13} /> {t('fm.restorebtn', 'Restore')}
                  </Button>
                </div>
              ))}
            </div>
          )}
        </div>
      ) : (
        <>
          <div className="relative mb-2"><Search size={13} className="absolute left-2.5 top-1/2 -translate-y-1/2 text-[var(--faint)] pointer-events-none" />
            <Input className="!ps-8 !py-1.5 !text-xs" placeholder={t('fm.filter', 'Filter this folder…')} value={q} onChange={(e) => setQ(e.target.value)} /></div>
          <div className="divide-y divide-[var(--line)] max-h-80 overflow-auto scroll-thin">
            {entries.length ? entries.map((e) => (
              <div key={e.name} className="flex items-center gap-2 py-1.5 text-sm group">
                <button onClick={() => openEntry(e)} className="flex-1 min-w-0 text-start flex items-center gap-2 hover:text-[var(--accent-ink)]">
                  {e.isDir ? <FolderGit2 size={13} className="text-[var(--accent-ink)] shrink-0" /> : <FileText size={13} className="text-[var(--faint)] shrink-0" />} <span className="truncate" title={e.name}>{e.name}</span>
                </button>
                {!e.isDir && <span className="text-[11px] text-[var(--faint)] shrink-0">{(e.size / 1024).toFixed(1)} KB</span>}
                <span className="hidden group-hover:flex items-center gap-2 shrink-0">
                  {!e.isDir && <button onClick={() => downloadEntry(e)} className="text-[var(--faint)] hover:text-[var(--accent-ink)]" title={t('adm2.download', "Download")}><Download size={12} /></button>}
                  {!e.isDir && <button onClick={() => viewHistory(dir === '.' ? e.name : `${dir}/${e.name}`)} className="text-[var(--faint)] hover:text-[var(--accent-ink)]" title={t('adm2.bkphist', "Backup history")}><History size={12} /></button>}
                  <button onClick={() => rename(e)} className="text-[var(--faint)] hover:text-[var(--accent-ink)]" title={t('adm2.rename', "Rename")}><PenSquare size={12} /></button>
                  <button onClick={() => delEntry(e)} className="text-[var(--faint)] hover:text-error" title={t('adm2.delete', "Delete")}><Trash2 size={12} /></button>
                </span>
              </div>
            )) : <div className="text-xs text-[var(--faint)] py-4 text-center">{data?.entries?.length ? t('fm.nomatches', 'No matches.') : t('fm.emptydir', 'Empty directory.')}</div>}
          </div>
        </>
      )}
      {history && (
        <Modal open onClose={() => setHistory(null)} title={t('fm.histtitle', 'Backup history: {p}').replace('{p}', history.path)} icon={History} width="max-w-lg">
          {history.items.length ? (
            <div className="divide-y divide-[var(--line)] max-h-96 overflow-auto scroll-thin">
              {history.items.map((h) => (
                <div key={h.hash} className="flex items-center gap-2.5 py-2 text-sm">
                  <div className="flex-1 min-w-0"><div className="truncate" title={h.message}>{h.message}</div><div className="text-[11px] text-[var(--faint)]">{new Date(h.at).toLocaleString()} · <code className="font-mono">{h.hash.slice(0, 8)}</code></div></div>
                  {/* Download the version instead of restoring it — the safe half of
                      "what did this file look like before", with nothing written to the
                      live server. */}
                  <a href={`/api/server/files/backups/${h.hash}/download?path=${encodeURIComponent(history.path)}`} download title={t('common.download', 'Download')}>
                    <Button size="sm" variant="ghost"><Download size={13} /></Button>
                  </a>
                  <Button size="sm" onClick={() => restoreVersion(h.hash)}>{t('fm.restorebtn', 'Restore')}</Button>
                </div>
              ))}
            </div>
          ) : <div className="text-xs text-[var(--faint)] py-6 text-center">{t('fm.nobackups', 'No backups yet for this file.')}</div>}
        </Modal>
      )}
    </Card>
  );
}

// Read-only database browser — table list + paginated rows, no free-form SQL
// input anywhere (that's exactly the surface the web terminal risked). Table
// names are validated server-side against the real Postgres catalog.
const DB_SENSITIVE_COL = /hash|secret|token|password|totp/i;

function DbViewer() {
  const toast = useToast(); const dialog = useDialog(); const { t } = useI18n();
  const [source, setSource] = useState('bcweb'); // 'bcweb' | 'telemetry'
  const [tables, setTables] = useState(null);
  const [tableQ, setTableQ] = useState('');
  const [active, setActive] = useState(null);
  const [rows, setRows] = useState(null);
  const [page, setPage] = useState(0);
  const [sort, setSort] = useState({ col: null, dir: 'asc' });
  const [cell, setCell] = useState(null); // { col, value, pk } for the expand/edit modal
  const [draft, setDraft] = useState('');
  const [saving, setSaving] = useState(false);
  const [rowHistory, setRowHistory] = useState(null); // { table, pk, items }
  const pageSize = 25;
  const canEdit = source === 'bcweb'; // the telemetry DB is read-only (no cell/edit routes)
  const dbBase = (s = source) => (s === 'telemetry' ? '/server/telemetry-db' : '/server/db');

  useEffect(() => {
    setTables(null); setActive(null); setRows(null);
    api.get(`${dbBase(source)}/tables`).then((r) => setTables(r.tables))
      .catch((x) => toast.error(x.data?.error === 'telemetry_db_not_configured' ? t('dbv.notconfigured', 'BMM telemetry DB is not configured.') : t('dbv.listfail', 'Failed to list tables.')));
    /* eslint-disable-next-line */
  }, [source]);
  const openTable = async (name, p = 0, s = sort) => {
    setActive(name); setPage(p); setRows(null); setSort(s);
    try {
      const qs = new URLSearchParams({ page: p, pageSize }); if (s.col) { qs.set('sort', s.col); qs.set('dir', s.dir); }
      const r = await api.get(`${dbBase()}/table/${encodeURIComponent(name)}?${qs}`); setRows(r);
    } catch { toast.error(t('dbv.tablefail', 'Failed to load table.')); }
  };
  const toggleSort = (c) => openTable(active, 0, sort.col === c ? { col: c, dir: sort.dir === 'asc' ? 'desc' : 'asc' } : { col: c, dir: 'asc' });
  const cols = rows?.rows?.[0] ? Object.keys(rows.rows[0]) : [];
  const cellText = (v) => v === null ? '' : typeof v === 'object' ? JSON.stringify(v) : String(v);
  const exportCsv = () => {
    if (!rows?.rows?.length) return;
    downloadCsv(toCsv(rows.rows, cols.map((c) => [c, (r) => cellText(r[c])])), `${active}_page${page + 1}`);
  };
  const visibleTables = tables?.filter((t) => !tableQ.trim() || t.name.toLowerCase().includes(tableQ.trim().toLowerCase())) || [];

  return (
    <Card className="p-4">
      <div className="flex items-center gap-2 mb-2 text-sm flex-wrap"><HardDrive size={14} className="text-[var(--accent-ink)]" /><span className="font-semibold">{t('dbv.title', 'Database viewer')}</span>
        <span className="text-xs text-[var(--faint)]">{canEdit ? t('dbv.editcare', '(edit with care)') : t('dbv.readonly', '(read-only)')}</span>
        <div className="ms-auto flex rounded-lg border border-[var(--line)] overflow-hidden text-xs">
          {[['bcweb', 'BCWEB'], ['telemetry', 'BMM Telemetry']].map(([v, l]) => (
            <button key={v} onClick={() => setSource(v)} className={`px-2.5 py-1 ${source === v ? 'bg-[var(--surface-2)] text-[var(--text)] font-medium' : 'text-[var(--muted)] hover:text-[var(--text)]'}`}>{l}</button>
          ))}
        </div>
      </div>
      {!tables ? <Loading /> : (
        <div className="grid sm:grid-cols-[180px_1fr] gap-3">
          <div>
            <div className="relative mb-1.5"><Search size={12} className="absolute left-2 top-1/2 -translate-y-1/2 text-[var(--faint)] pointer-events-none" />
              <Input className="!ps-7 !py-1 !text-xs" placeholder={t('dbv.filtertables', 'Filter tables…')} value={tableQ} onChange={(e) => setTableQ(e.target.value)} /></div>
            <div className="max-h-80 overflow-auto scroll-thin space-y-0.5">
              {visibleTables.map((t) => (
                <button key={t.name} onClick={() => openTable(t.name)} className={`w-full text-start px-2 py-1.5 rounded-lg text-xs flex items-center justify-between gap-2 ${active === t.name ? 'bg-[var(--surface-2)] text-[var(--text)] font-medium' : 'text-[var(--muted)] hover:bg-[var(--surface-2)]'}`}>
                  <span className="truncate" title={t.name}>{t.name}</span><span className="text-[var(--faint)] shrink-0">{t.approxRows}</span>
                </button>
              ))}
              {!visibleTables.length && <div className="text-xs text-[var(--faint)] py-3 text-center">{t('fm.nomatches', 'No matches.')}</div>}
            </div>
          </div>
          <div className="min-w-0">
            {!active ? <div className="text-xs text-[var(--faint)] py-6 text-center">{t('dbv.picktable', 'Pick a table.')}</div>
              : !rows ? <Loading />
              : (
                <>
                  <div className="overflow-auto max-h-96 scroll-thin border border-[var(--line)] rounded-lg">
                    <table className="text-xs w-full">
                      <thead><tr className="border-b border-[var(--line)]">{cols.map((c) => (
                        <th key={c} className="text-start px-2 py-1.5 font-semibold text-[var(--faint)] whitespace-nowrap">
                          <button onClick={() => toggleSort(c)} className="flex items-center gap-1 hover:text-[var(--text)]">
                            {c} {sort.col === c && <ChevronDown size={11} className={sort.dir === 'asc' ? 'rotate-180' : ''} />}
                          </button>
                        </th>
                      ))}</tr></thead>
                      <tbody>
                        {rows.rows.map((r, i) => (
                          <tr key={i} className="border-b border-[var(--line)] last:border-0">
                            {cols.map((c) => (
                              <td key={c} onClick={() => { setCell({ col: c, value: r[c], pk: rows.pkColumn ? r[rows.pkColumn] : null }); setDraft(r[c] === null ? '' : cellText(r[c])); }} className="px-2 py-1.5 whitespace-nowrap max-w-[220px] truncate font-mono cursor-pointer hover:bg-[var(--surface-2)]" title={t('adm2.clickedit', "Click to view / edit")}>
                                {r[c] === null ? <span className="text-[var(--faint)]">null</span> : cellText(r[c])}
                              </td>
                            ))}
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                  <div className="flex items-center justify-between mt-2 text-xs text-[var(--muted)]">
                    <span>{rows.total} {rows.total !== 1 ? t('dbv.rows', 'rows') : t('dbv.row', 'row')}</span>
                    <div className="flex gap-2">
                      <Button size="sm" onClick={exportCsv}><Download size={12} /> {t('dbv.csv', 'CSV (page)')}</Button>
                      <Button size="sm" disabled={page === 0} onClick={() => openTable(active, page - 1)}>{t('dbv.prev', 'Prev')}</Button>
                      <Button size="sm" disabled={(page + 1) * pageSize >= rows.total} onClick={() => openTable(active, page + 1)}>{t('dbv.next', 'Next')}</Button>
                    </div>
                  </div>
                </>
              )}
          </div>
          {cell && (() => {
            const isPk = rows?.pkColumn === cell.col;
            const protected_ = DB_SENSITIVE_COL.test(cell.col);
            const editable = canEdit && !!rows?.pkColumn && cell.pk != null && !isPk && !protected_;
            // DELIBERATELY NOT behind the undo window: this writes a row straight into the
            // database. It already carries a double confirmation and a confirmToken, and the
            // server backs the old value up — that is the right shape of safety here. Adding a
            // six-second "maybe" on top would only blur when the write actually happened.
            const save = async () => {
              if (!(await doubleConfirm(dialog, { title: t('dbv.saverow', 'Save row edit'), message: t('dbv.saverowconfirm', 'Overwrite {t}.{c} (row {pk}) on the live database? The current row is backed up automatically.').replace('{t}', active).replace('{c}', cell.col).replace('{pk}', cell.pk), okLabel: t('common.save', 'Save') }))) return;
              setSaving(true);
              try {
                await api.put(`/server/db/table/${encodeURIComponent(active)}/cell`, { pk: cell.pk, column: cell.col, value: draft, confirmToken: 'CONFIRM' });
                toast.success(t('dbv.rowsaved', 'Saved, the previous row value was backed up.'));
                setCell(null);
                openTable(active, page, sort);
              } catch (x) {
                toast.error(x.data?.error === 'table_protected' ? t('dbv.tableprotected', 'Audit/log tables are read-only, they can\'t be edited here.') : x.data?.error === 'column_protected' ? t('dbv.colprotected', 'This column can\'t be edited here.') : x.data?.error === 'update_failed' ? t('dbv.updatefail', 'Failed: {d}').replace('{d}', x.data?.detail || 'invalid value') : t('common.failed', 'Failed.'));
              } finally { setSaving(false); }
            };
            const viewRowHistory = async () => {
              try { const r = await api.get(`/server/db/backups?table=${encodeURIComponent(active)}&pk=${encodeURIComponent(cell.pk)}`); setRowHistory({ table: active, pk: cell.pk, items: r.history }); }
              catch { toast.error(t('fm.histfail', 'Failed to load history.')); }
            };
            return (
              <Modal open onClose={() => setCell(null)} title={cell.col} icon={HardDrive} width="max-w-lg"
                footer={editable ? <><Button onClick={() => setCell(null)}>{t('su.cancel', 'Cancel')}</Button><Button onClick={viewRowHistory}><History size={13} /> {t('fm.history', 'History')}</Button><Button variant="primary" disabled={saving} onClick={save}>{saving ? <Spinner /> : t('common.save', 'Save')}</Button></> : undefined}>
                {editable ? (
                  <textarea value={draft} onChange={(e) => setDraft(e.target.value)} className="w-full h-40 font-mono text-xs bg-[var(--surface-2)] rounded-lg p-3 outline-none" spellCheck={false} />
                ) : (
                  <>
                    <pre className="text-xs font-mono bg-[var(--surface-2)] rounded-lg p-3 max-h-80 overflow-auto scroll-thin whitespace-pre-wrap break-all">{cell.value === null ? 'null' : cellText(cell.value)}</pre>
                    <p className="text-xs text-[var(--faint)] mt-2">{protected_ ? t('dbv.sensitivenote', "This column can't be edited here (sensitive).") : isPk ? t('dbv.pknote', "The primary key can't be edited.") : t('dbv.nopknote', 'This table has no single-column primary key, so it can only be viewed.')}</p>
                  </>
                )}
              </Modal>
            );
          })()}
          {rowHistory && (
            <Modal open onClose={() => setRowHistory(null)} title={t('dbv.rowhisttitle', 'Row backup history: {t} (pk={pk})').replace('{t}', rowHistory.table).replace('{pk}', rowHistory.pk)} icon={History} width="max-w-lg">
              {rowHistory.items.length ? (
                <div className="divide-y divide-[var(--line)] max-h-96 overflow-auto scroll-thin">
                  {rowHistory.items.map((h) => (
                    <div key={h.hash} className="flex items-center gap-2.5 py-2 text-sm">
                      <div className="flex-1 min-w-0"><div className="truncate" title={h.message}>{h.message}</div><div className="text-[11px] text-[var(--faint)]">{new Date(h.at).toLocaleString()} · <code className="font-mono">{h.hash.slice(0, 8)}</code></div></div>
                      <Button size="sm" onClick={async () => {
                        if (!(await doubleConfirm(dialog, { title: t('dbv.restorerow', 'Restore this row'), message: t('dbv.restorerowconfirm', 'Overwrite {t} (pk={pk}) with this backed-up version? Sensitive columns are never restored. The current row is backed up first.').replace('{t}', rowHistory.table).replace('{pk}', rowHistory.pk), okLabel: t('fm.restorebtn', 'Restore') }))) return;
                        try { const r = await api.post(`/server/db/backups/${h.hash}/restore`, { table: rowHistory.table, pk: rowHistory.pk, confirmToken: 'CONFIRM' }); toast.success(t('dbv.rowrestored', 'Restored {n} column(s){s}.').replace('{n}', r.restored.length).replace('{s}', r.skipped.length ? t('dbv.skipped', ', skipped {k}').replace('{k}', r.skipped.length) : '')); setRowHistory(null); setCell(null); openTable(active, page, sort); }
                        catch { toast.error(t('fm.restorefail', 'Failed to restore.')); }
                      }}>{t('fm.restorebtn', 'Restore')}</Button>
                    </div>
                  ))}
                </div>
              ) : <div className="text-xs text-[var(--faint)] py-6 text-center">{t('dbv.norowbackups', 'No backups yet for this row.')}</div>}
            </Modal>
          )}
        </div>
      )}
    </Card>
  );
}

// The step-up-gated "danger zone": file manager, read-only DB viewer, and a
// server restart — all confined to this container/process. Docker management
// and host power control are NOT wired up — they'd require mounting the Docker
// socket (and, for power, a privileged agent), a docker-compose change with real
// security implications that hasn't been made.
// The three tools behind the elevation gate. A table rather than three hardcoded buttons,
// so the switcher and the panel below it can never disagree about what exists.
const ADV_TOOLS = [
  { id: 'files', k: 'asa.t.files', label: 'File manager', icon: Files },
  { id: 'db', k: 'asa.t.db', label: 'Database', icon: Database },
  { id: 'backups', k: 'asa.t.backups', label: 'Backups', icon: Archive },
  // Separate from 'backups' on purpose: that one restores the machine, this one exports
  // what people wrote. Naming both "backup" and putting them on one screen is how somebody
  // downloads a zip of JSON and believes they can restore from it.
  { id: 'content', k: 'asa.t.content', label: 'Content export', icon: FileJson },
];

function AdminServerAdvanced() {
  const toast = useToast(); const dialog = useDialog(); const { t } = useI18n(); const { user: me } = useAuth();
  // In the URL, so a refresh or a shared link lands on the tool you were in. `replace`, not
  // push: switching between three tools should not mean three presses of Back to leave.
  const [advSp, setAdvSp] = useSearchParams();
  const advTool = ADV_TOOLS.some((x) => x.id === advSp.get('tool')) ? advSp.get('tool') : 'files';
  const setAdvTool = (id) => setAdvSp((prev) => {
    const n = new URLSearchParams(prev); n.set('tool', id); return n;
  }, { replace: true });
  const me2fa = useAsync(() => api.get('/me/2fa'), []);
  const elevateStatus = useAsync(() => api.get('/server/elevate/status').catch(() => ({ elevated: false })), []);
  const [code, setCode] = useState('');
  const [busy, setBusy] = useState(false);

  const elevate = async () => {
    setBusy(true);
    try { await api.post('/server/elevate', { code: code.trim() }); toast.success(t('asa.elevated', 'Elevated for 15 minutes.')); setCode(''); elevateStatus.reload(); }
    catch (x) { toast.error(x.data?.error === 'invalid_code' ? t('asa.invalidcode', 'Invalid code.') : x.data?.error === '2fa_not_enabled' ? t('asa.no2fa', 'Enable 2FA in your profile first.') : x.data?.error === 'forbidden' ? t('asa.noaccess', "You don't have server-control access.") : t('common.failed', 'Failed.')); }
    finally { setBusy(false); }
  };

  if (me2fa.loading || elevateStatus.loading) return <Loading />;
  // Server control is deliberately ORTHOGONAL to the role hierarchy — even a SUPERADMIN
  // holds it only when it has been granted, so shell/Docker/power access is never ambient.
  // But telling a SUPERADMIN that "a SUPERADMIN must grant you" is a riddle: they are the
  // one who can, including to themselves. Say that instead.
  if (!me2fa.data?.canControlServer) return <EmptyState icon={AlertTriangle} title={t('asa.notauth', 'Not authorized')}
    sub={me?.role === 'SUPERADMIN'
      ? t('asa.notauthself', 'Server control is granted separately from your role, so it is never implicit — not even for a SUPERADMIN. Grant it to yourself in the Access & permissions tab.')
      : t('asa.notauthsub', 'A SUPERADMIN must grant you server-control access from the Access & permissions tab first.')}
    action={me?.role === 'SUPERADMIN' ? { label: t('asa.notauth.go', 'Open Roles & permissions'), icon: Shield, to: '/admin?s=access' } : null} />;

  return (
    <div>
      <h2 className="font-semibold mb-1 flex items-center gap-2"><AlertTriangle size={16} className="text-error" /> {t('asa.title', 'Advanced server management')}</h2>
      <p className="text-sm text-[var(--muted)] mb-3">{t('asa.sub', "Confined to this API container's own filesystem/process — no host or Docker access today. A fuller per-service view (Docker start/stop/restart/logs, host power) needs a docker-compose change (mounting the Docker socket, or a separate privileged power agent) that hasn't been made yet.")}</p>

      {!elevateStatus.data?.elevated ? (
        <Card className="p-5 max-w-sm">
          <div className="text-sm font-semibold mb-2 flex items-center gap-2"><ShieldCheck size={15} className="text-[var(--accent-ink)]" /> {t('asa.stepup', 'Step-up verification required')}</div>
          <p className="text-xs text-[var(--muted)] mb-3">{t('asa.stepupsub', 'Enter a fresh code from your authenticator app to unlock these tools for 15 minutes.')}</p>
          <div className="flex gap-2">
            <Input value={code} onChange={(e) => setCode(e.target.value.replace(/\D/g, '').slice(0, 6))} placeholder="123456" />
            <Button variant="primary" disabled={busy || code.length !== 6} onClick={elevate}>{busy ? <Spinner /> : t('asa.elevate', 'Elevate')}</Button>
          </div>
          <div className="mt-2"><TotpQuickFill onFill={(c) => setCode(c)} /></div>
        </Card>
      ) : (
        <>
          {/* One tool at a time. Measured before changing it: stacked, this panel was 2983px
              on an 812px screen, so reaching Backups meant scrolling past the whole file
              manager and the whole database viewer. Nothing overflowed — the page fitted the
              width and was still a pile, which is why "not responsive" was the right word
              for it anyway.

              The same control at every size on purpose: this is a picker, and a picker that
              becomes something else at a breakpoint is two things to learn. */}
          <div className="flex gap-1.5 mb-4 overflow-x-auto no-scrollbar pb-1">
            {ADV_TOOLS.map((tl) => (
              <button key={tl.id} type="button" onClick={() => setAdvTool(tl.id)}
                aria-current={advTool === tl.id ? 'true' : undefined}
                className={`shrink-0 inline-flex items-center gap-2 px-3 py-2 rounded-xl border text-sm transition press ${
                  advTool === tl.id
                    ? 'border-[var(--primary)] bg-[var(--surface-2)] text-[var(--text)]'
                    : 'border-[var(--line)] text-[var(--muted)] hover:text-[var(--text)] hover:border-[var(--primary)]'
                }`}>
                <tl.icon size={15} className={advTool === tl.id ? 'text-[var(--accent-ink)]' : ''} />
                {t(tl.k, tl.label)}
              </button>
            ))}
          </div>
          {/* Mounted one at a time rather than hidden with CSS: the database viewer and the
              file manager both fetch on mount, and keeping all three alive would have every
              one of them polling for a screen nobody is looking at. */}
          {advTool === 'files' && <FileManager />}
          {advTool === 'db' && <DbViewer />}
          {advTool === 'backups' && <BackupManager />}
          {advTool === 'content' && <ContentBackup />}
        </>
      )}
    </div>
  );
}


/**
 * What a content zip would do, before it does it.
 *
 * The import already takes a snapshot and offers an undo, and that is still the wrong shape
 * for the question being asked: "will this replace the twelve pages I wrote this morning" is
 * answerable from the file, without touching the site and reaching for the reversal.
 *
 * The numbers that matter are `adds` and `replaces`. `records` alone reads as harmless — a
 * zip of forty pages sounds like forty pages arriving, and it can just as easily be forty
 * pages overwritten.
 */
function ContentImportPreview({ file, bytes, sections, onClose, onConfirm }) {
  const { t } = useI18n();
  const [state, setState] = useState({ loading: true });
  useEffect(() => {
    let live = true;
    (async () => {
      try {
        const res = await fetch('/api/admin/content-backup/inspect', {
          method: 'POST', credentials: 'include',
          headers: { 'Content-Type': 'application/zip' }, body: bytes,
        });
        const out = await res.json().catch(() => ({}));
        if (!live) return;
        if (!res.ok) setState({ error: out.detail || out.error || `HTTP ${res.status}` });
        else setState({ data: out });
      } catch (e) { if (live) setState({ error: String(e?.message || e) }); }
    })();
    return () => { live = false; };
  }, [bytes]);
  const d = state.data || {};
  const rows = Object.entries(d.sections || {});
  const willReplace = rows.reduce((n, [, v]) => n + (v.replaces || 0), 0);
  return (
    <Modal open onClose={onClose} title={t('cb.pre.title', 'Before importing')} icon={Eye} width="max-w-2xl"
      footer={<div className="flex items-center justify-end gap-2">
        <Button size="sm" variant="ghost" onClick={onClose}>{t('common.cancel', 'Cancel')}</Button>
        <Button size="sm" disabled={state.loading || !!state.error} onClick={onConfirm}>
          <Upload size={13} /> {t('cb.pre.ok', 'Import it')}
        </Button>
      </div>}>
      {state.loading ? <Loading />
        : state.error ? <div className="text-sm text-error">{state.error === 'not_a_zip' ? t('cb.pre.notzip', 'That file is not a zip this screen can read.') : state.error}</div>
        : (
        <div className="space-y-3">
          <div className="rounded-xl border border-[var(--line)] p-3 text-[12px] text-[var(--muted)]">
            <div className="text-[13px] font-semibold text-[var(--text)] mb-1">{file?.name}</div>
            {d.manifest?.generatedAt
              ? t('cb.pre.made', 'Exported on') + ' ' + new Date(d.manifest.generatedAt).toLocaleString()
              : t('cb.pre.nomanifest', 'No manifest in this zip, it may not have come from this screen.')}
            {' · '}{fmtBytes(d.bytes || 0)}
          </div>
          {/* One sentence with the number that decides it, before the table. */}
          <div className={`rounded-xl border p-3 text-[13px] ${willReplace ? 'b-warning tint-warning-soft' : 'b-success tint-success-soft'}`}>
            {willReplace
              ? <span>{t('cb.pre.replace', 'This would overwrite')} <b>{willReplace}</b> {t('cb.pre.replace2', 'existing record(s). What the site says now is saved first, so it can be undone.')}</span>
              : t('cb.pre.add', 'Nothing already on the site is overwritten by this file.')}
          </div>
          <div className="rounded-lg border border-[var(--line)] divide-y divide-[var(--line)]">
            <div className="grid grid-cols-[minmax(0,1fr)_60px_60px_60px] sm:grid-cols-[minmax(0,1fr)_70px_70px_70px] gap-2 px-2.5 py-1.5 text-[11px] uppercase tracking-wider text-[var(--faint)]">
              <span>{t('cb.pre.section', 'Section')}</span><span className="text-end">{t('cb.pre.records', 'In zip')}</span>
              <span className="text-end">{t('cb.pre.new', 'New')}</span><span className="text-end">{t('cb.pre.over', 'Replaced')}</span>
            </div>
            {rows.map(([key, v]) => (
              <div key={key} className="grid grid-cols-[minmax(0,1fr)_60px_60px_60px] sm:grid-cols-[minmax(0,1fr)_70px_70px_70px] gap-2 px-2.5 py-1.5 text-[12px] items-center">
                <span className="truncate flex items-center gap-1.5">
                  {v.label || key}
                  {!v.restorable && <span className="text-[10px] px-1.5 py-0.5 rounded border border-[var(--line)] text-[var(--faint)]">{t('cb.exportonly', 'export only')}</span>}
                </span>
                <span className="text-end tabular-nums">{v.error ? '—' : v.records}</span>
                {/* null is "we could not tell", which must not be drawn as zero. */}
                <span className="text-end tabular-nums text-success">{v.adds == null ? '?' : v.adds}</span>
                <span className="text-end tabular-nums text-warning">{v.replaces == null ? '?' : v.replaces}</span>
              </div>
            ))}
          </div>
          {!!(d.unknown || []).length && (
            <p className="text-[11px] text-[var(--muted)]">
              {t('cb.pre.unknown', 'Files this build does not know and will ignore:')} <code className="font-mono">{d.unknown.join(', ')}</code>
            </p>
          )}
          <p className="text-[11px] text-[var(--muted)]">
            {t('cb.pre.scope', 'Only the sections ticked on the panel behind this one are imported, whatever else the zip holds.')}
          </p>
        </div>
      )}
    </Modal>
  );
}

/**
 * Export the written content as a zip of JSON.
 *
 * The counts come first and the download second, because the choice on this screen is which
 * sections to take and that is not a choice without a number beside each one.
 */
function ContentBackup() {
  const { t } = useI18n(); const toast = useToast();
  const dialog = useDialog();
  const { data, loading, err, reload } = useAsync(() => api.get('/admin/content-backup/preview'), []);
  const [on, setOn] = useState(null);
  const [busy, setBusy] = useState(false);
  const [importing, setImporting] = useState(false);
  const [preview, setPreview] = useState(null); // { file, bytes } — read, not yet applied
  const fileRef = useRef(null);
  // The defaults come from the server, not from a copy here: which sections are on by default
  // is a decision about what a backup MEANS, and two answers to that is one too many.
  useEffect(() => { if (data && !on) setOn(new Set(data.defaults || [])); }, [data]);
  if (loading) return <Loading />;
  if (err) return <Card className="p-6 text-sm text-[var(--muted)]">{String(err)}</Card>;
  const sections = data?.sections || {};
  const picked = on || new Set();
  const toggle = (k) => setOn((prev) => { const n = new Set(prev); if (n.has(k)) n.delete(k); else n.add(k); return n; });

  const download = async () => {
    setBusy(true);
    try {
      // Fetched rather than linked, so an expired session shows a message instead of putting
      // a JSON error page on disk with a .zip on the end of its name.
      const res = await fetch(`/api/admin/content-backup?include=${[...picked].join(',')}`, { credentials: 'include' });
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      const blob = await res.blob();
      const a = document.createElement('a');
      a.href = URL.createObjectURL(blob);
      a.download = `bettercommunity-content-${new Date().toISOString().slice(0, 10)}.zip`;
      a.click();
      URL.revokeObjectURL(a.href);
    } catch (e) { toast.error(String(e?.message || e)); } finally { setBusy(false); }
  };

  /**
   * Read the zip, send it, and offer the way back.
   *
   * Confirmed first, naming the sections. This overwrites live content — an import that
   * happened because a file dialog was open is the one thing a snapshot cannot make pleasant.
   */
  const doImport = async (file, bytes) => {
    const names = [...picked].map((k) => sections[k]?.label || k).join(', ');
    const ok = await dialog.confirm({
      title: t('cb.imp.t', 'Import this content?'),
      message: t('cb.imp.m', 'Sections that will be restored: {x}. Existing pages with the same id are replaced; anything the zip has not heard of is left alone. What the site says now is saved first, so this can be undone.').replace('{x}', names || t('cb.imp.none', 'none selected')),
      okLabel: t('cb.imp.ok', 'Import'),
    });
    if (!ok) return;
    setImporting(true);
    try {
      // Already read for the preview; reading it twice would ask the browser for a file the
      // user may have moved since.
      const body = bytes || await file.arrayBuffer();
      const res = await fetch(`/api/admin/content-backup/import?include=${[...picked].join(',')}`, {
        method: 'POST', credentials: 'include',
        headers: { 'Content-Type': 'application/zip' },
        body,
      });
      const out = await res.json().catch(() => ({}));
      if (!res.ok) throw new Error(out.detail || out.error || `HTTP ${res.status}`);

      const applied = Object.entries(out.applied || {});
      const total = applied.reduce((n, [, v]) => n + v, 0);
      // Sections the zip carried that this route will not write. Said out loud: "accounts
      // did not come back" is a thing somebody has to be told, not left to notice.
      if (out.skipped?.length) {
        toast.info(t('cb.imp.skipped', 'Not imported (export only): {x}')
          .replace('{x}', out.skipped.map((k) => sections[k]?.label || k).join(', ')));
      }
      // No onCommit: the work is done and the server holds the snapshot, so the window
      // offers the reversal and expiring does nothing. Same shape as the API-key revoke.
      toast.action({
        tone: 'success',
        msg: t('cb.imp.done', 'Imported {n} record(s) across {s} section(s).')
          .replace('{n}', String(total)).replace('{s}', String(applied.length)),
        duration: 12000,
        cancelLabel: t('cb.imp.undo', 'Undo'),
        onCancel: async () => {
          try {
            for (const [section] of applied) {
              await api.post('/admin/content-backup/rollback', { section, hash: out.undo });
            }
            toast.success(t('cb.imp.undone', 'Put back the way it was.'));
            reload();
          } catch (e) { toast.error(String(e?.message || e)); }
        },
      });
      reload();
    } catch (e) {
      toast.error(String(e?.message || e));
    } finally { setImporting(false); }
  };

  return (
    <Card className="p-4 space-y-3">
      <div>
        <h3 className="font-semibold text-sm flex items-center gap-2"><FileJson size={15} className="text-[var(--accent-ink)]" /> {t('cb.title', 'Content export')}</h3>
        <p className="text-xs text-[var(--muted)] mt-1 max-w-2xl">
          {t('cb.lede', 'The docs, blog, FAQ, legal versions, settings and account records, as JSON in a zip you can open. Take one before a risky edit, or when moving to another install.')}
        </p>
      </div>

      <div className="space-y-1.5">
        {Object.entries(sections).map(([k, sec]) => (
          <label key={k} className="flex items-center gap-2.5 text-sm cursor-pointer py-0.5">
            <input type="checkbox" checked={picked.has(k)} onChange={() => toggle(k)} className="shrink-0" />
            <span>{sec.label}</span>
            {/* Export-only, said HERE rather than discovered when an import skips it. Three
                sections cannot come back and each has its own reason — the note under the
                list gives them. */}
            {sec.restorable === false && (
              <span className="text-[10px] px-1.5 py-0.5 rounded border border-[var(--line)] text-[var(--faint)]">
                {t('cb.exportonly', 'export only')}
              </span>
            )}
            {/* null is "could not count", which is not the same as zero and must not read as it. */}
            <span className="ms-auto text-[11px] tabular-nums text-[var(--faint)]">
              {sec.count === null ? t('cb.unknown', 'unknown') : sec.count}
            </span>
          </label>
        ))}
      </div>

      {/* Both caveats, on the screen, before the download \u2014 not in the manifest inside the zip
          where they are read after the fact. */}
      <div className="text-[11px] text-[var(--muted)] leading-relaxed border-s-2 border-[var(--line)] ps-2.5 space-y-1">
        <p>{t('cb.note.users', 'Accounts are records only \u2014 no password hashes, no 2FA secrets, no tokens. Restoring them means re-inviting people.')}</p>
        <p>{t('cb.note.files', 'Catalogue and repository sections are metadata; the uploaded files they point at are not in the archive. That is why they are off by default.')}</p>
        <p>{t('cb.note.restore', 'This is not a restore point. For that, use the database backup under Backups.')}</p>
      </div>

      <div className="flex items-center gap-2 pt-1 flex-wrap">
        <Button variant="primary" onClick={download} loading={busy} disabled={!picked.size}>
          <Download size={15} /> {t('cb.download', 'Download the zip')}
        </Button>
        <Button onClick={() => fileRef.current?.click()} loading={importing}>
          <Upload size={15} /> {t('cb.import', 'Import a zip…')}
        </Button>
        {/* Hidden input rather than a drop zone: this replaces live content, and a page you
            can trigger by dragging a file onto the wrong part of it is the wrong shape for
            that. */}
        <input ref={fileRef} type="file" accept=".zip,application/zip" className="hidden"
          onChange={async (e) => {
            const f = e.target.files?.[0]; e.target.value = '';
            // Inspected first, always. The confirmation dialog after it lists the sections;
            // this lists what is actually in the file, which is the half the dialog cannot know.
            if (f) setPreview({ file: f, bytes: await f.arrayBuffer() });
          }} />
        {!picked.size && <span className="text-[11px] text-[var(--muted)]">{t('cb.none', 'Pick at least one section.')}</span>}
      </div>

      {preview && <ContentImportPreview file={preview.file} bytes={preview.bytes} sections={sections}
        onClose={() => setPreview(null)}
        onConfirm={() => { const p = preview; setPreview(null); void doImport(p.file, p.bytes); }} />}

      <p className="text-[11px] text-[var(--muted)] leading-relaxed">
        {t('cb.import.note', 'An import restores what the zip holds, section by section. It never deletes a page the zip has not heard of — anything written since the export stays. What the site said beforehand is committed to a git history first, so it can be put back from the toast or from the list below.')}
      </p>
    </Card>
  );
}

/**
 * The files inside a backup.
 *
 * A backup you cannot open is a promise rather than a record: the panel showed a size, a
 * date and "git accepts it", none of which answer the question somebody actually arrives
 * with — is the file I lost in THIS one. The only way to find out was to restore it, which
 * is what you do once you already know.
 *
 * `readDir` and `readFile` are passed in because the same browser serves a stored snapshot
 * (fetched by id) and one that is only in the admin's hand (posted as bytes). The second
 * cannot read a file without re-uploading the whole archive, so it passes no `readFile` and
 * the rows are simply not clickable — an affordance that would fail is worse than none.
 */
function BundleBrowser({ readDir, readFile }) {
  const { t } = useI18n();
  const [path, setPath] = useState('');
  const [state, setState] = useState({ loading: true });
  const [file, setFile] = useState(null);
  useEffect(() => {
    let live = true;
    setState({ loading: true });
    readDir(path).then((d) => live && setState({ data: d })).catch((e) => live && setState({ error: String(e?.data?.error || e?.message || e) }));
    return () => { live = false; };
  }, [path]);
  const crumbs = path ? path.split('/') : [];
  const open = async (entry) => {
    const next = path ? `${path}/${entry.name}` : entry.name;
    if (entry.isDir) { setPath(next); return; }
    if (!readFile) return;
    setFile({ loading: true, path: next });
    try { setFile({ ...(await readFile(next)) }); }
    catch (e) { setFile({ path: next, error: String(e?.data?.error || e?.message || e) }); }
  };
  return (
    <div>
      <div className="flex items-center flex-wrap gap-1 text-[12px] mb-1.5">
        <button onClick={() => setPath('')} className={`hover:text-[var(--accent-ink)] ${path ? 'text-[var(--muted)]' : 'font-medium'}`}>{t('snap.br.root', 'Backup root')}</button>
        {crumbs.map((c, i) => (
          <span key={i} className="flex items-center gap-1">
            <ChevronRight size={11} className="text-[var(--faint)]" />
            <button onClick={() => setPath(crumbs.slice(0, i + 1).join('/'))} className={`hover:text-[var(--accent-ink)] ${i === crumbs.length - 1 ? 'font-medium' : 'text-[var(--muted)]'}`}>{c}</button>
          </span>
        ))}
      </div>
      <div className="max-h-64 overflow-y-auto divide-y divide-[var(--line)] rounded-lg border border-[var(--line)]">
        {state.loading ? <div className="px-2.5 py-3"><Spinner /></div>
          : state.error ? <div className="px-2.5 py-2 text-[12px] text-error">{state.error}</div>
          : !(state.data?.entries || []).length ? <div className="px-2.5 py-2 text-[12px] text-[var(--faint)]">{t('snap.br.empty', 'This folder is empty in the backup.')}</div>
          : state.data.entries.map((e) => (
            <button key={e.name} onClick={() => open(e)} disabled={!e.isDir && !readFile}
              className="w-full text-start px-2.5 py-1.5 flex items-center gap-2 text-[12px] hover:bg-[var(--surface-2)] disabled:hover:bg-transparent disabled:cursor-default">
              {e.isDir ? <FolderGit2 size={13} className="text-[var(--accent-ink)] shrink-0" /> : <FileText size={13} className="text-[var(--faint)] shrink-0" />}
              <span className="truncate flex-1" title={e.name}>{e.name}</span>
              {!e.isDir && <span className="text-[11px] text-[var(--faint)] shrink-0">{fmtBytes(e.size)}</span>}
            </button>
          ))}
      </div>
      {!readFile && <p className="text-[11px] text-[var(--faint)] mt-1">{t('snap.br.nofile', 'Folders only until it is imported, reading a file out of an archive that is not stored yet would mean uploading it again for every click.')}</p>}
      <Modal open={!!file} onClose={() => setFile(null)} title={file?.path || ''} icon={FileText} width="max-w-3xl">
        {file?.loading ? <Loading />
          : file?.error ? <div className="text-sm text-error">{file.error}</div>
          : file?.binary ? <p className="text-sm text-[var(--muted)]">{t('snap.br.binary', 'Binary file: {n} in the backup. There is nothing useful to show as text.').replace('{n}', fmtBytes(file.bytes || 0))}</p>
          : <>
              {file?.truncated && <div className="text-[11px] text-warning mb-2">{t('snap.br.trunc', 'Showing the first part only, the file is {n}.').replace('{n}', fmtBytes(file.bytes || 0))}</div>}
              <pre className="text-[11px] font-mono whitespace-pre-wrap bg-[var(--surface-2)] p-2 rounded-lg max-h-[60vh] overflow-auto">{file?.text}</pre>
            </>}
      </Modal>
    </div>
  );
}

/**
 * An uploaded bundle, before it is stored.
 *
 * Import verified the file and then kept it, so the only way to see what was in a bundle was
 * to add it to the snapshot list — and the wrong backup then has to be deleted again. This
 * runs the same verification with nothing written anywhere, and the import button below it
 * is the same call that used to happen straight from the file picker.
 */
function ImportPreview({ file, b64, kind, onClose, onImported }) {
  const { t } = useI18n(); const toast = useToast();
  const { data, loading } = useAsync(() => api.post('/server/backups/snapshots/inspect-upload', { data: b64 }), [b64]);
  const [busy, setBusy] = useState(false);
  const d = data || {};
  const doImport = async () => {
    setBusy(true);
    try {
      const r = await api.post('/server/backups/snapshots/import', { kind, note: file.name.slice(0, 120), data: b64 });
      toast.success(t('snap.imported', 'Imported, it verified, and is in the list.'));
      onImported(r.snapshot.id);
    } catch (x) {
      toast.error(x?.data?.error === 'invalid_bundle' ? t('snap.badimport', 'That file is not a backup git will open: {d}').replace('{d}', String(x.data.detail || '').split('\n')[0].slice(0, 120))
        : x?.data?.error === 'too_large' ? t('bkp.toobig', 'Too large to export in one file, compact the backups first.')
        : t('common.failed', 'Failed.'));
    } finally { setBusy(false); }
  };
  return (
    <Modal open onClose={onClose} title={t('snap.pre.title', 'Before importing')} icon={Eye} width="max-w-xl"
      footer={<div className="flex items-center justify-end gap-2">
        <Button size="sm" variant="ghost" onClick={onClose}>{t('common.cancel', 'Cancel')}</Button>
        <Button size="sm" disabled={busy || loading || !d.valid} onClick={doImport}>{busy ? <Spinner /> : <><Upload size={13} /> {t('snap.pre.ok', 'Import it')}</>}</Button>
      </div>}>
      {loading ? <Loading /> : (
        <div className="space-y-3">
          <div className={`rounded-xl border p-3 ${d.valid ? 'b-success tint-success-soft' : 'b-error tint-error-soft'}`}>
            <div className="flex items-center gap-2 text-[14px] font-semibold">
              {d.valid ? <CheckCircle2 size={16} className="text-success" /> : <XCircle size={16} className="text-error" />}
              {d.valid ? t('snap.pre.ok.t', 'Git reads this file as a backup.') : t('snap.pre.bad.t', 'This file will not open as a backup.')}
            </div>
            <p className="text-[12px] text-[var(--muted)] mt-1">
              {d.valid ? t('snap.pre.ok.s', 'Nothing has been stored yet. What is listed below is what an import would add to the snapshot list.')
                : t('snap.pre.bad.s', 'Nothing was stored. Git\u2019s own words are below, usually it means a different file was picked.')}
            </p>
          </div>
          <div className="grid sm:grid-cols-2 gap-2 text-[12px]">
            <div className="rounded-lg border border-[var(--line)] px-2.5 py-2"><div className="text-[var(--faint)] text-[11px]">{t('snap.pre.file', 'File')}</div><div className="truncate" title={file?.name}>{file?.name}</div></div>
            <div className="rounded-lg border border-[var(--line)] px-2.5 py-2"><div className="text-[var(--faint)] text-[11px]">{t('snap.c.size', 'On disk')}</div><div>{fmtBytes(d.bytes || file?.size || 0)}</div></div>
          </div>
          {!!(d.commits || []).length && (
            <div>
              <div className="text-[11px] uppercase tracking-wider text-[var(--faint)] mb-1">{t('snap.contents', 'What it contains')}</div>
              <div className="max-h-40 overflow-y-auto divide-y divide-[var(--line)] rounded-lg border border-[var(--line)]">
                {d.commits.map((c) => (
                  <div key={c.hash} className="px-2.5 py-1.5 flex items-baseline gap-2 text-[12px]">
                    <code className="font-mono text-[10px] text-[var(--faint)] shrink-0">{c.hash.slice(0, 8)}</code>
                    <span className="truncate flex-1" title={c.message}>{c.message}</span>
                    <span className="text-[11px] text-[var(--faint)] shrink-0">{new Date(c.at).toLocaleDateString()}</span>
                  </div>
                ))}
              </div>
            </div>
          )}
          {d.tree && (
            <div>
              <div className="text-[11px] uppercase tracking-wider text-[var(--faint)] mb-1">{t('snap.br.title', 'Files in this backup')}</div>
              <BundleBrowser readDir={(path) => api.post('/server/backups/snapshots/inspect-upload', { data: b64, path }).then((r) => r.tree || { entries: [] })} />
            </div>
          )}
          {!d.valid && d.error && <pre className="text-[10px] font-mono whitespace-pre-wrap text-[var(--muted)] bg-[var(--surface-2)] p-2 rounded-lg max-h-40 overflow-auto">{d.error}</pre>}
        </div>
      )}
    </Modal>
  );
}

// What is actually inside a backup, and the only place a rollback can be started.
//
// The rollback lives HERE rather than next to the row because it should not be reachable
// without having looked: the two facts that decide whether a restore is safe — is the file
// intact, and is it the backup you think it is — are both on this screen.
function SnapshotInspector({ id, onClose, onRestored }) {
  const { t } = useI18n(); const toast = useToast();
  const { data, loading } = useAsync(() => api.get(`/server/backups/snapshots/${id}/inspect`), [id]);
  const [confirm, setConfirm] = useState('');
  const [toDisk, setToDisk] = useState(false);
  const [busy, setBusy] = useState(false);

  const restore = async () => {
    setBusy(true);
    try {
      const r = await api.post(`/server/backups/snapshots/${id}/restore`, { confirmToken: 'CONFIRM', applyToDisk: toDisk });
      toast.success(t('snap.restored', 'Rolled back. The previous state was saved as a backup first ({n}).').replace('{n}', r.safetySnapshot?.id || '—'));
      // Said out loud, because it is the difference between what a rollback sounds like and
      // what a copy-over does: files created after the backup are still there.
      if (r.extra?.length) {
        toast.error(t('snap.extra', '{n} path(s) on disk were not in this backup and were left in place: {l}')
          .replace('{n}', String(r.extra.length)).replace('{l}', r.extra.slice(0, 6).join(', ')));
      }
      onRestored(); onClose();
    } catch (x) {
      toast.error(x?.data?.error === 'no_safety_snapshot' ? t('snap.nosafety', 'Could not back up the current state, so nothing was rolled back.')
        : x?.data?.error === 'invalid_bundle' ? t('snap.invalid', 'This backup does not verify, it will not be restored.')
        : t('common.failed', 'Failed.'));
    } finally { setBusy(false); }
  };

  const d = data || {};
  return (
    <Modal open onClose={onClose} title={t('snap.inspect', 'Inspect this backup')} icon={Archive} width="max-w-xl">
      {loading ? <Loading /> : (
        <div className="space-y-4">
          {/* One verdict, in a sentence, before the detail. The three checks were four badges
              of jargon in a row — a reader had to know what a digest is, and to work out for
              themselves whether the combination meant "safe to restore". */}
          <div className={`rounded-xl border p-3 ${d.valid && d.digestMatches ? 'b-success tint-success-soft' : d.valid ? 'b-warning tint-warning-soft' : 'b-error tint-error-soft'}`}>
            <div className="flex items-center gap-2 text-[14px] font-semibold">
              {d.valid && d.digestMatches ? <CheckCircle2 size={16} className="text-success" />
                : d.valid ? <AlertTriangle size={16} className="text-warning" />
                  : <XCircle size={16} className="text-error" />}
              {d.valid && d.digestMatches ? t('snap.v.ok', 'This backup is intact and is the file we wrote.')
                : d.valid ? t('snap.v.warn', 'This backup opens, but it is not the file we wrote.')
                  : t('snap.v.bad', 'This backup will not open.')}
            </div>
            <p className="text-[12px] text-[var(--muted)] mt-1">
              {d.valid && d.digestMatches ? t('snap.v.ok.s', 'Both checks passed, so a rollback will use exactly what was captured.')
                : d.valid ? t('snap.v.warn.s', 'Git reads it, but its fingerprint does not match the one recorded when it was made — it has been altered or replaced since. Do not roll back to it without knowing why.')
                  : t('snap.v.bad.s', 'Git cannot read it as a bundle, so there is nothing to restore from. Keep an older backup instead.')}
            </p>
          </div>

          {/* The two checks, each said in a full sentence rather than a word. They answer
              different questions and a reader who conflates them draws the wrong conclusion. */}
          <div className="grid sm:grid-cols-2 gap-2">
            {[
              [d.valid, t('snap.c.readable', 'Git can read it'), t('snap.c.readable.s', 'The file is a coherent bundle.')],
              [d.digestMatches, t('snap.c.ours', 'It is our file'), t('snap.c.ours.s', 'Its fingerprint matches what we recorded when it was written.')],
              [d.signature?.present, t('snap.c.signed', 'Signed'), t('snap.c.signed.s', 'Carries a signature that can be checked independently.')],
            ].map(([ok, label, desc]) => (
              <div key={label} className="flex items-start gap-2 rounded-lg border border-[var(--line)] panel px-2.5 py-2">
                {ok ? <CheckCircle2 size={14} className="text-success shrink-0 mt-0.5" /> : <XCircle size={14} className="text-[var(--faint)] shrink-0 mt-0.5" />}
                <div className="min-w-0">
                  <div className="text-[12px] font-medium">{label}</div>
                  <div className="text-[11px] text-[var(--muted)]">{desc}</div>
                </div>
              </div>
            ))}
            <div className="flex items-start gap-2 rounded-lg border border-[var(--line)] panel px-2.5 py-2">
              <Archive size={14} className="text-[var(--faint)] shrink-0 mt-0.5" />
              <div className="min-w-0">
                <div className="text-[12px] font-medium">{fmtBytes(d.meta?.bytes || 0)}</div>
                <div className="text-[11px] text-[var(--muted)]">{t('snap.c.size', 'On disk')}</div>
              </div>
            </div>
          </div>

          <div>
            <div className="text-[11px] uppercase tracking-wider text-[var(--faint)] mb-1">
              {t('snap.contents', 'What it contains')}
              {(d.commits || []).length > 0 && <span className="normal-case tracking-normal text-[var(--muted)]"> · {t('snap.ncommits', '{n} entries').replace('{n}', String(d.commits.length))}</span>}
            </div>
            <div className="max-h-56 overflow-y-auto divide-y divide-[var(--line)] rounded-lg border border-[var(--line)]">
              {(d.commits || []).map((c) => (
                <div key={c.hash} className="px-2.5 py-1.5 flex items-baseline gap-2 text-[12px]">
                  <code className="font-mono text-[10px] text-[var(--faint)] shrink-0">{c.hash.slice(0, 8)}</code>
                  <span className="truncate flex-1" title={c.message}>{c.message}</span>
                  <span className="text-[11px] text-[var(--faint)] shrink-0">{new Date(c.at).toLocaleDateString()}</span>
                </div>
              ))}
              {!(d.commits || []).length && <div className="px-2.5 py-2 text-[12px] text-[var(--faint)]">{t('snap.nocommits', 'Nothing readable in it.')}</div>}
            </div>
          </div>

          {d.valid && (
            <div>
              <div className="text-[11px] uppercase tracking-wider text-[var(--faint)] mb-1">{t('snap.br.title', 'Files in this backup')}</div>
              <BundleBrowser
                readDir={(path) => api.get(`/server/backups/snapshots/${id}/tree?path=${encodeURIComponent(path)}`)}
                readFile={(path) => api.get(`/server/backups/snapshots/${id}/file?path=${encodeURIComponent(path)}`)}
              />
            </div>
          )}

          {/* The raw git output, folded away. It is what you want when a check failed and
              noise the rest of the time. */}
          {d.verify && (
            <details className="rounded-lg border border-[var(--line)]">
              <summary className="px-2.5 py-1.5 text-[11px] text-[var(--muted)] cursor-pointer select-none">{t('snap.raw', 'Raw output from git')}</summary>
              <pre className="text-[10px] font-mono whitespace-pre-wrap text-[var(--muted)] bg-[var(--surface-2)] p-2 max-h-40 overflow-auto">{d.verify}</pre>
            </details>
          )}

          {d.valid && (
            <div className="rounded-lg border b-warning tint-warning-soft p-3 space-y-2">
              <div className="text-[13px] font-semibold flex items-center gap-1.5"><RotateCcw size={13} /> {t('snap.rollback', 'Roll back to this backup')}</div>
              <p className="text-[11px] text-[var(--muted)]">
                {t('snap.rollback.s', 'The current state is backed up first and the rollback is refused if that fails — a rollback with no way back is just a hopeful restore. This resets the backup history only.')}
              </p>
              <p className="text-[11px] text-[var(--muted)]">
                {t('snap.rollback.merge', 'Writing to disk copies the backup OVER what is there. Files created since — uploads, caches, anything a later version writes — are not removed, so the result is a merge rather than an exact return to that moment. Whatever is left over is listed afterwards so you can decide about it.')}
              </p>
              {d.meta?.kind === 'files' && (
                <label className="flex items-start gap-2 text-[11px]">
                  <input type="checkbox" checked={toDisk} onChange={(e) => setToDisk(e.target.checked)} className="mt-0.5" />
                  {/* Separate from the rollback because it is the irreversible half: resetting
                      history can be undone from the safety snapshot, overwriting the live tree
                      cannot. */}
                  <span>{t('snap.rollback.disk', 'Also write these files over the live application directory. This changes what the server is running and cannot be undone by another rollback.')}</span>
                </label>
              )}
              <div className="flex items-center gap-2">
                <Input className="!w-40" value={confirm} onChange={(e) => setConfirm(e.target.value)} placeholder="CONFIRM" />
                <Button size="sm" variant="danger" disabled={busy || confirm !== 'CONFIRM'} onClick={restore}>
                  {busy ? <Spinner /> : t('snap.rollback.ok', 'Roll back')}
                </Button>
              </div>
            </div>
          )}
        </div>
      )}
    </Modal>
  );
}

// Snapshots: the backups an admin can actually take, hold and throw away.
//
// Kept visually apart from the history above because they answer a different question.
// The history answers "put that file back"; a snapshot answers "the server is gone".
function SnapshotsPanel({ onChanged }) {
  const { t } = useI18n(); const toast = useToast(); const dialog = useDialog();
  const { data, loading, reload } = useAsync(() => api.get('/server/backups/snapshots'), []);
  const [busy, setBusy] = useState('');
  const [keep, setKeep] = useState('');
  const [inspecting, setInspecting] = useState(null);
  const [preview, setPreview] = useState(null); // { file, kind, b64 } — an upload, not yet stored

  const snaps = data?.snapshots || [];

  // Import reads the file in the browser and posts it base64. The bundles this produces are
  // megabytes; the endpoint verifies before storing, so a wrong file is refused with git's
  // own words rather than landing in the list as something that cannot be restored.
  // The file is read here and INSPECTED before anything is stored. Importing straight from
  // the picker meant the only way to see what a bundle held was to add it to the list and,
  // if it was the wrong one, delete it again.
  const importFile = async (file, kind) => {
    if (!file) return;
    setBusy('import');
    try {
      const buf = new Uint8Array(await file.arrayBuffer());
      let bin = '';
      for (let i = 0; i < buf.length; i += 8192) bin += String.fromCharCode(...buf.subarray(i, i + 8192));
      setPreview({ file, kind, b64: btoa(bin) });
    } catch (x) {
      toast.error(t('common.failed', 'Failed.'));
    } finally { setBusy(''); }
  };
  const keepNow = data?.keep ?? 10;
  // Absent means ON — the daily snapshot predates this switch, so an install that never set
  // it has been backing up all along and must keep doing so.
  const autoOn = data?.auto !== false;
  const everyNow = data?.everyHours ?? 24;
  const [every, setEvery] = useState('');

  // WHAT and WHERE. Both start as null meaning "not edited on this screen" — the saved
  // value is what is shown until somebody actually changes it, so a reload landing between
  // a keystroke and the Save does not quietly revert the other field.
  const kindsNow = Array.isArray(data?.kinds) ? data.kinds : ['files'];
  const [kinds, setKinds] = useState(null);
  const kindsShown = kinds ?? kindsNow;
  const toggleKind = (k) => setKinds(kindsShown.includes(k) ? kindsShown.filter((x) => x !== k) : [...kindsShown, k]);
  const dirNow = data?.dir || '';
  const [dir, setDir] = useState(null);
  const dirShown = dir ?? dirNow;

  const take = async (kind) => {
    setBusy('new');
    try {
      const r = await api.post('/server/backups/snapshots', { kind });
      // The rotation is reported, never silent. A backup routine that quietly deletes is
      // the reason people distrust backup routines.
      toast.success(r.rotated?.length
        ? t('snap.made.rot', 'Backup taken: {n} older one(s) rotated out.').replace('{n}', String(r.rotated.length))
        : t('snap.made', 'Backup taken.'));
      reload(); onChanged?.();
    } catch (x) {
      toast.error(x?.data?.error === 'no_backups' ? t('bkp.nobackups2', 'Nothing to back up yet — a snapshot freezes the file and DB-row edits made through the tools here, and none have been made. Edit something first, or wait for the daily automatic backup.') : t('common.failed', 'Failed.'));
    } finally { setBusy(''); }
  };

  // Turning it OFF asks first. Everything else on this row is a number you can put back; this
  // one means that from now on the only backups are the ones somebody remembers to take, and
  // the day that matters is the day nobody did.
  const saveAuto = async (next) => {
    if (!next && !await dialog.confirm({
      title: t('snap.auto.t', 'Stop taking backups automatically?'),
      message: t('snap.auto.m', 'Nothing will be backed up on its own after this. Existing backups are kept, but no new one appears unless you take it by hand.'),
      okLabel: t('snap.auto.ok', 'Turn automatic backups off'),
      danger: true,
    })) return;
    setBusy('auto');
    try {
      await api.put('/server/backups/limit', { maxBytes: data?.maxBytes ?? null, auto: next });
      toast.success(next ? t('snap.auto.on2', 'Automatic backups on.') : t('snap.auto.off2', 'Automatic backups off.'));
      reload(); onChanged?.();
    } catch { toast.error(t('common.failed', 'Failed.')); } finally { setBusy(''); }
  };

  const saveKeep = async () => {
    const n = keep.trim() === '' ? keepNow : Math.max(0, Math.round(Number(keep)));
    if (!Number.isFinite(n)) return;
    if (n > 0 && n < snaps.filter((x) => x.kind === 'files').length) {
      // Naming the number that will be deleted, because "Save" on a settings row is not a
      // place anyone expects to lose backups.
      if (!await dialog.confirm({
        title: t('snap.keep.t', 'Delete older backups now?'),
        message: t('snap.keep.m', 'Keeping {n} means the older ones are removed immediately, not at the next backup.').replace('{n}', String(n)),
        okLabel: t('snap.keep.ok', 'Keep {n} and rotate').replace('{n}', String(n)),
        danger: true,
      })) return;
    }
    setBusy('keep');
    try {
      // Sent together: two fields behind one Save button must be one request, or half the
      // form saves and the other half looks like it did.
      const hours = every === '' ? undefined : Math.min(720, Math.max(1, Number(every) || everyNow));
      const r = await api.put('/server/backups/limit', {
        maxBytes: data?.maxBytes ?? null, keep: n, ...(hours ? { everyHours: hours } : {}),
        // Sent only when this screen actually changed them, so saving a retention count from
        // an older tab cannot reset somebody else's selection or destination.
        ...(kinds ? { kinds } : {}), ...(dir === null ? {} : { dir: dir.trim() }),
      });
      toast.success(r.removed?.length ? t('snap.rotated', '{n} removed.').replace('{n}', String(r.removed.length)) : t('common.saved', 'Saved.'));
      setKeep(''); setEvery(''); setKinds(null); setDir(null); reload(); onChanged?.();
    } catch (x) {
      // The destination is the one field here that fails for a reason worth reading — a
      // path that does not exist, a read-only mount. "Failed." would send somebody hunting.
      toast.error(x?.data?.error === 'dir_not_writable'
        ? t('snap.dir.now', 'That folder cannot be written to: {d}').replace('{d}', String(x.data.detail || '').slice(0, 120))
        : x?.data?.error === 'bad_dir'
          ? ({ not_absolute: t('snap.dir.abs', 'The destination must be a full path, starting from the root of the disk.'),
               inside_files_root: t('snap.dir.inside', 'That folder is inside the tree being backed up, each backup would contain the previous ones.'),
               is_root: t('snap.dir.root', 'That is the root of the disk. Pick a folder inside it.') }[x.data.reason]
             || t('snap.dir.bad', 'That destination cannot be used.'))
          : t('common.failed', 'Failed.'));
    } finally { setBusy(''); }
  };

  // Same reason as the history export: the signature travels in a response header, so a
  // plain <a download> would save the file and bin the thing that makes it checkable.
  const download = async (snap) => {
    setBusy(snap.id);
    try {
      const res = await fetch(`/api/server/backups/snapshots/${snap.id}/download`, { credentials: 'include' });
      if (!res.ok) throw new Error('dl');
      const sig = res.headers.get('X-Backup-Signature') || '';
      const blob = await res.blob();
      const name = `bcweb-${snap.id}.bundle`;
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a'); a.href = url; a.download = name; a.click();
      URL.revokeObjectURL(url);
      if (sig) {
        const su = URL.createObjectURL(new Blob([sig], { type: 'text/plain' }));
        const b = document.createElement('a'); b.href = su; b.download = `${name}.sig.b64`; b.click();
        URL.revokeObjectURL(su);
      }
      toast.success(t('bkp.exported', 'Downloaded {n}, the signature was saved next to it.').replace('{n}', name));
    } catch { toast.error(t('common.failed', 'Failed.')); } finally { setBusy(''); }
  };

  const remove = async (snap) => {
    if (!await dialog.confirm({
      title: t('snap.del.t', 'Delete this backup?'),
      message: t('snap.del.m', 'It is removed from the disk for good. Anything already downloaded is unaffected.'),
      okLabel: t('common.delete', 'Delete'), danger: true,
    })) return;
    setBusy(snap.id);
    try { await api.del(`/server/backups/snapshots/${snap.id}`, { confirmToken: 'CONFIRM' }); toast.success(t('common.deleted', 'Deleted.')); reload(); onChanged?.(); }
    catch { toast.error(t('common.failed', 'Failed.')); } finally { setBusy(''); }
  };

  return (
    <div className="mt-3 rounded-xl border border-[var(--line)] p-3">
      <div className="text-xs font-semibold uppercase tracking-wider text-[var(--faint)] mb-1.5 flex items-center gap-1.5">
        <Archive size={12} /> {t('snap.title', 'Point-in-time backups')}
      </div>
      <p className="text-[11px] text-[var(--muted)] mb-2">
        {t('snap.sub', 'One frozen, signed file per backup — taken here, or automatically once a day. Unlike the history above these never change after they are made, which is what makes one worth copying off the box.')}
      </p>

      <div className="flex flex-wrap items-center gap-2">
        <Button size="sm" variant="primary" disabled={!!busy} onClick={() => take('both')}>
          {busy === 'new' ? <Spinner /> : <Archive size={13} />} {t('snap.now', 'Back up now')}
        </Button>
        <Button size="sm" disabled={!!busy} onClick={() => take('files')}>{t('snap.files', 'Files only')}</Button>
        <Button size="sm" disabled={!!busy} onClick={() => take('db')}>{t('snap.db', 'DB rows only')}</Button>
        <label className="inline-flex">
          <input type="file" accept=".bundle" className="hidden" onChange={(e) => { importFile(e.target.files?.[0], 'files'); e.target.value = ''; }} />
          <span className={`inline-flex items-center gap-1.5 px-3 py-1.5 rounded-[10px] text-sm border border-[var(--line)] cursor-pointer hover:bg-[var(--surface-2)] ${busy ? 'opacity-50 pointer-events-none' : ''}`}>
            {busy === 'import' ? <Spinner /> : <UploadIcon size={13} />} {t('snap.import', 'Import a backup')}
          </span>
        </label>
      </div>

      {/* The SCHEDULE, in a box of its own.
          It used to share one wrapping line with the three "do it now" buttons and the
          import, so the Save at the end of that line looked as though it might save any of
          them. Everything in here answers one question — what happens when nobody is
          watching — and the whole block dims when the answer is "nothing". */}
      <div className="mt-3 rounded-lg border border-[var(--line)] panel-quiet p-2.5">
        <div className="flex items-center gap-2 flex-wrap">
          <label className="inline-flex items-center gap-1.5 text-xs font-medium cursor-pointer" title={t('snap.auto.hint', 'Take a backup automatically on a schedule')}>
            <input type="checkbox" checked={autoOn} disabled={!!busy} onChange={(e) => saveAuto(e.target.checked)} />
            {t('snap.auto.label', 'Automatic')}
          </label>
          <div className={`flex items-center gap-1.5 ${autoOn ? '' : 'opacity-50'}`}>
            <span className="text-[11px] text-[var(--muted)]">{t('snap.every', 'every')}</span>
            <Input className="w-16" type="number" min="1" max="720" value={every} disabled={!autoOn || !!busy}
              onChange={(e) => setEvery(e.target.value)} placeholder={String(everyNow)} />
            <span className="text-[11px] text-[var(--muted)]">{t('snap.hours', 'h')}</span>
          </div>
          <div className="flex items-center gap-1.5">
            <span className="text-[11px] text-[var(--muted)]">{t('snap.keeplabel', 'Keep')}</span>
            <Input className="w-20" type="number" min="0" value={keep} onChange={(e) => setKeep(e.target.value)} placeholder={String(keepNow)} />
          </div>
          <Button size="sm" className="ms-auto" disabled={!!busy} onClick={saveKeep}>{busy === 'keep' ? <Spinner /> : t('common.save', 'Save')}</Button>
        </div>
      <div className={`mt-2 flex flex-wrap items-center gap-x-4 gap-y-2 ${autoOn ? '' : 'opacity-50'}`}>
        <span className="text-[11px] text-[var(--muted)]">{t('snap.what', 'Back up')}</span>
        <label className="inline-flex items-center gap-1.5 text-[11px] cursor-pointer">
          <input type="checkbox" checked={kindsShown.includes('files')} disabled={!autoOn || !!busy} onChange={() => toggleKind('files')} />
          {t('snap.what.files', 'Files')}
        </label>
        <label className="inline-flex items-center gap-1.5 text-[11px] cursor-pointer"
          title={t('snap.what.db.h', 'The history of row edits made through the DB console above, not a dump of the whole database.')}>
          <input type="checkbox" checked={kindsShown.includes('db')} disabled={!autoOn || !!busy} onChange={() => toggleKind('db')} />
          {t('snap.what.db', 'Database row history')}
        </label>
        <div className="flex items-center gap-1.5 flex-1 min-w-[260px]">
          <span className="text-[11px] text-[var(--muted)] shrink-0">{t('snap.where', 'to')}</span>
          <Input className="flex-1 min-w-0 font-mono !text-[11px]" value={dirShown} disabled={!!busy}
            onChange={(e) => setDir(e.target.value)}
            placeholder={data?.defaultDir || t('snap.where.ph', 'leave empty for the usual place')} />
        </div>
      </div>
      </div>
      {kindsShown.length === 0 && autoOn && (
        <p className="text-[11px] text-warning mt-1">
          {t('snap.what.none', 'Nothing is selected, the schedule will run and back up nothing.')}
        </p>
      )}
      <p className="text-[11px] text-[var(--faint)] mt-1.5">
        {!autoOn && <span className="text-warning">{t('snap.auto.off', 'Automatic backups are OFF, the only backups from here on are the ones you take by hand. ')}</span>}
        {keepNow > 0
          ? t('snap.keep.on', 'A backup every {h}h, keeping the {n} most recent of each kind, older ones are overwritten as new ones are taken.')
              .replace('{n}', String(keepNow)).replace('{h}', String(everyNow))
          : t('snap.keep.off', 'Rotation is off: backups are kept until you delete them, and nothing watches the disk for you.')}
        {' '}
        {/* Where they are actually written. The saved value, not the field being typed in,
            because this sentence describes what the server will do, not what is unsaved. */}
        <code className="font-mono">{dirNow || data?.defaultDir || ''}</code>
      </p>

      <div className="mt-3 rounded-lg border border-[var(--line)] divide-y divide-[var(--line)] max-h-72 overflow-y-auto">
        {loading ? <div className="p-3"><Spinner /></div>
          : !snaps.length ? <div className="px-3 py-3 text-[11px] text-[var(--faint)]">{t('snap.none', 'No backup taken yet.')}</div>
          : snaps.map((snap) => (
            <div key={snap.id} className="px-3 py-2 flex items-center gap-2">
              <span className="text-[10px] px-1.5 py-0.5 rounded shrink-0 bg-[var(--surface-2)]">
                {snap.kind === 'db' ? t('bkp.dbhist', 'DB row history') : t('bkp.filehist', 'File history')}
              </span>
              <div className="min-w-0 flex-1">
                <div className="text-xs truncate">{new Date(snap.createdAt).toLocaleString()} · {fmtBytes(snap.bytes || 0)}</div>
                <div className="text-[10px] text-[var(--faint)] truncate">
                  {snap.note || (snap.by === 'sweeper' ? t('snap.auto', 'automatic daily') : t('snap.manual', 'taken by hand'))}
                  {' · '}<code className="font-mono">{String(snap.sha256 || '').slice(0, 12)}</code>
                  {!snap.signature && <span className="text-warning"> · {t('snap.unsigned', 'unsigned')}</span>}
                  {/* Changing the destination must never make existing backups disappear, so
                      they stay listed and say where they are. */}
                  {dirNow && snap.atDefault && (
                    <span title={snap.dir}> · {t('snap.elsewhere', 'at the previous location')}</span>
                  )}
                </div>
              </div>
              <Button size="sm" variant="ghost" disabled={!!busy} onClick={() => setInspecting(snap.id)} title={t('snap.inspect', 'Inspect this backup')}><Eye size={13} /></Button>
              <Button size="sm" variant="ghost" disabled={!!busy} onClick={() => download(snap)} title={t('common.download', 'Download')}><Download size={13} /></Button>
              <Button size="sm" variant="ghost" disabled={!!busy} onClick={() => remove(snap)} title={t('common.delete', 'Delete')}><Trash2 size={13} className="text-[var(--error)]" /></Button>
            </div>
          ))}
      </div>

      {inspecting && <SnapshotInspector id={inspecting} onClose={() => setInspecting(null)} onRestored={() => { reload(); onChanged?.(); }} />}
      {preview && <ImportPreview {...preview} onClose={() => setPreview(null)}
        onImported={(id) => { setPreview(null); reload(); onChanged?.(); setInspecting(id); }} />}
    </div>
  );
}

// Backups here are git-based history for edits made through the File manager
// and DB viewer above (see gitbackup.mjs) — NOT a full disaster-recovery
// backup of the whole app. Size shown here is also mirrored in the admin
// Storage tab's ledger.
function BackupManager() {
  const toast = useToast(); const { t } = useI18n();
  const { data, loading, reload } = useAsync(() => api.get('/server/backups/usage'), []);
  const [limitGB, setLimitGB] = useState('');
  const [busy, setBusy] = useState(false);
  const [gcBusy, setGcBusy] = useState(false);
  // The field is cleared inside the deferred work, not before it: on Undo the value the user
  // typed is still sitting there, which is what "nothing happened" should look like.
  const undoSave = useUndoableSave(reload);
  const saveLimit = () => {
    setBusy(true);
    undoSave(async () => {
      await api.put('/server/backups/limit', { maxBytes: limitGB.trim() ? Math.round(Number(limitGB) * 1024 ** 3) : null });
      setLimitGB('');
    }, t('common.saved', 'Saved.'), { onSettled: () => setBusy(false) });
  };
  const runGc = async () => {
    setGcBusy(true);
    try { await api.post('/server/backups/gc'); toast.success(t('bkp.compacted', 'Compacted.')); reload(); } catch { toast.error(t('common.failed', 'Failed.')); } finally { setGcBusy(false); }
  };

  // Downloaded through fetch rather than a plain <a download>, because the signature
  // travels in a RESPONSE HEADER — a link would save the file and throw the one thing
  // that makes it verifiable straight in the bin.
  const [exporting, setExporting] = useState('');
  const exportRepo = async (which) => {
    setExporting(which);
    try {
      const res = await fetch(`/api/server/backups/export?repo=${which}`, { credentials: 'include' });
      if (!res.ok) {
        const j = await res.json().catch(() => ({}));
        throw Object.assign(new Error('export'), { data: j });
      }
      const sig = res.headers.get('X-Backup-Signature') || '';
      const blob = await res.blob();
      const name = (res.headers.get('Content-Disposition') || '').match(/filename="([^"]+)"/)?.[1] || `${which}.bundle`;
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a'); a.href = url; a.download = name; a.click();
      URL.revokeObjectURL(url);
      // The signature is saved beside the bundle automatically. Asking the admin to copy
      // a base64 blob out of a toast is how a signature ends up unchecked forever.
      if (sig) {
        const sigUrl = URL.createObjectURL(new Blob([sig], { type: 'text/plain' }));
        const b = document.createElement('a'); b.href = sigUrl; b.download = `${name}.sig.b64`; b.click();
        URL.revokeObjectURL(sigUrl);
      }
      toast.success(t('bkp.exported', 'Downloaded {n}, the signature was saved next to it.').replace('{n}', name));
    } catch (x) {
      toast.error(x?.data?.error === 'no_backups' ? t('bkp.nobackups', 'Nothing to export yet — the backup store fills automatically as you edit files or database rows on this server. Make an edit, then its history is here to export.')
        : x?.data?.error === 'too_large' ? t('bkp.toobig', 'Too large to export in one file, compact the backups first.')
        : t('common.failed', 'Failed.'));
    } finally { setExporting(''); }
  };

  const [contents, setContents] = useState(null);   // { files: [...], db: [...] }
  const [pubkey, setPubkey] = useState(null);
  const openContents = async () => {
    try { setContents(await api.get('/server/backups/list')); }
    catch { toast.error(t('common.failed', 'Failed.')); }
  };
  if (loading) return <Loading />;
  const d = data || {};
  const pct = d.maxBytes ? Math.min(100, (d.totalBytes / d.maxBytes) * 100) : 0;
  return (
    <Card className="p-4">
      {/* The headline figure sits WITH the title. The one question this panel answers is
          "how much disk, and how close to the limit"; that used to be a 10px line at the end
          of a wrapping legend, four blocks down. */}
      <div className="flex items-start gap-3 flex-wrap mb-1">
        <div className="flex items-center gap-2 text-sm">
          <History size={14} className="text-[var(--accent-ink)]" />
          <span className="font-semibold">{t('bkp.title', 'Backup storage')}</span>
        </div>
        <div className="ms-auto text-end leading-tight">
          <div className="text-lg font-semibold tabular-nums">{fmtBytes(d.totalBytes || 0)}</div>
          <div className="text-[11px] text-[var(--faint)] tabular-nums">
            {d.maxBytes != null
              ? `${t('bkp.of', 'of')} ${fmtBytes(d.maxBytes)} · ${Math.round(pct)}%`
              : t('bkp.nolimit', 'no limit set')}
          </div>
        </div>
      </div>
      <p className="text-xs text-[var(--muted)] mb-3 max-w-2xl">{t('bkp.sub', "Every file edit/delete and DB row edit is git-committed first, so it can always be rolled back — plus a full daily snapshot of the file tree. This is separate from the app's own storage (see the Storage tab).")}</p>
      {/* One bar, three segments — because there are three things on that disk.

          It was two figures above a bar that measured something else: the panel showed
          `filesBytes` and `dbBytes`, and the bar showed `totalBytes`, which the API defines as
          files + db + SNAPSHOTS. `snapshotBytes` and `snapshotCount` came back in the same
          payload and appeared nowhere in the app. So the parts read 1.5 GB, the whole read
          4.1 GB, and nothing on the panel whose job is "where is the disk going" said where
          the rest went — on a number the API takes care to compute, with a comment saying a
          usage figure that ignores half of what it wrote is why a box runs out of space.

          Segments add up to the total by construction now: the same three numbers draw the
          bar and fill the legend, so they cannot disagree again. */}
      {(() => {
        const parts = [
          { k: 'files', bytes: d.filesBytes || 0, cls: 'bg-brand', label: t('bkp.filehist', 'File history') },
          { k: 'db', bytes: d.dbBytes || 0, cls: 'bg-brand-2', label: t('bkp.dbhist', 'DB row history') },
          { k: 'snap', bytes: d.snapshotBytes || 0, cls: 'bg-[var(--muted)]', label: t('bkp.snaps', 'Daily snapshots') },
        ];
        const total = d.totalBytes ?? parts.reduce((n, p) => n + p.bytes, 0);
        // Against the limit when there is one, against the total when there is not — an
        // unlimited store still has a composition worth seeing.
        const scale = d.maxBytes || total || 1;
        const over = d.maxBytes && pct >= 90;
        return (
          <div className="mb-4">
            {/* Thicker, because it is the picture: 2px read as a divider rather than a
                measurement, and the segments were too thin to hover. */}
            <div className="flex h-3 rounded-full bg-[var(--surface-2)] overflow-hidden">
              {parts.map((p) => (
                <div key={p.k} className={over ? 'bg-error' : p.cls} style={{ width: `${(p.bytes / scale) * 100}%` }} title={`${p.label} — ${fmtBytes(p.bytes)}`} />
              ))}
            </div>
            {/* A GRID, not a wrapping row. Three parts of one number line up in three columns
                and stay lined up; the flex row re-flowed at every width and pushed the total
                onto its own line, where it read as a fourth part. */}
            <div className="grid grid-cols-2 sm:grid-cols-3 gap-2 mt-2.5">
              {parts.map((p) => (
                <div key={p.k} className="min-w-0">
                  <div className="flex items-center gap-1.5 text-[11px] text-[var(--muted)]">
                    <span className={`w-2 h-2 rounded-full shrink-0 ${p.cls}`} />
                    <span className="truncate" title={p.label}>{p.label}</span>
                  </div>
                  <div className="text-sm tabular-nums ps-3.5">
                    {fmtBytes(p.bytes)}
                    {p.k === 'snap' && d.snapshotCount != null && (
                      <span className="text-[11px] text-[var(--faint)]"> · {d.snapshotCount}</span>
                    )}
                  </div>
                </div>
              ))}
            </div>
          </div>
        );
      })()}
      {/* The limit, and only the limit. "Compact backups" was the third cell of this row and
          is not part of setting one — it is an action on the store, and it belongs beside the
          paragraph that explains it rather than next to Save, where the two read as a pair. */}
      {/* The two things you DO to the store, side by side and no wider than they need to be.
          The limit input used to span the card, which made a number you type once look like
          the main event; the Compact button sat below a paragraph twice its size. */}
      <div className="grid md:grid-cols-2 gap-3">
        <div className="rounded-xl border border-[var(--line)] p-3">
          <div className="text-[11px] uppercase tracking-wider text-[var(--faint)] mb-1.5">{t('bkp.limit.h', 'Size limit')}</div>
          <div className="flex gap-2">
            <Input type="number" className="max-w-[180px]" value={limitGB} onChange={(e) => setLimitGB(e.target.value)}
              placeholder={d.maxBytes ? (d.maxBytes / 1024 ** 3).toFixed(1) : t('bkp.limitph.short', 'GB')} />
            <Button variant="primary" disabled={busy} onClick={saveLimit}>{busy ? <Spinner /> : t('common.save', 'Save')}</Button>
          </div>
          <p className="text-[11px] text-[var(--faint)] mt-1.5">{t('bkp.limit.s', 'In GB. Leave it empty for no limit.')}</p>
        </div>
        <div className="rounded-xl border border-[var(--line)] p-3">
          <div className="text-[11px] uppercase tracking-wider text-[var(--faint)] mb-1.5">{t('bkp.compact.h', 'Reclaim space')}</div>
          <Button size="sm" disabled={gcBusy} onClick={runGc} title={t('bkp.compacttip', 'Runs git gc on the backup repos to reclaim space from old/loose objects. Non-destructive: NO history is deleted — every version can still be restored.')}>{gcBusy ? <Spinner /> : t('bkp.compact', 'Compact backups')}</Button>
          <p className="text-[11px] text-[var(--faint)] mt-1.5 leading-snug">{t('bkp.note.s', 'Garbage-collects the backup git repos. It never deletes history, every past version stays restorable.')}</p>
        </div>
      </div>

      {/* Getting the backups OFF the box. A backup that only exists on the machine it
          protects is not a backup of that machine.
          A bordered sub-card rather than a hairline: this panel had six blocks separated
          by rules of the same weight, so nothing said which of them were sections and
          which were paragraphs inside one. */}
      <div className="mt-4 rounded-xl border border-[var(--line)] p-3">
        <div className="text-xs font-semibold uppercase tracking-wider text-[var(--faint)] mb-1.5 flex items-center gap-1.5">
          <Download size={12} /> {t('bkp.export', 'Take a copy off the server')}
        </div>
        <p className="text-[11px] text-[var(--muted)] mb-2">
          {t('bkp.export.s', 'Each download is a git bundle containing the full history — open it anywhere with “git clone”, no part of this site required. It is signed, and the signature is saved beside it.')}
        </p>
        {/* Say WHY it's empty before the export button 404s: the store only accrues as an
            admin edits files/rows, so a fresh install having nothing is expected, not broken. */}
        {(d.totalBytes || 0) === 0 && (
          <p className="text-[11px] text-warning mb-2 flex items-start gap-1.5"><Info size={12} className="shrink-0 mt-0.5" /> {t('bkp.export.empty', 'Nothing to export yet. The backup store fills automatically as you edit files or database rows on this server — there is no separate “create a backup” step.')}</p>
        )}
        <div className="flex flex-wrap gap-2">
          <Button size="sm" disabled={!!exporting} onClick={() => exportRepo('files')}>
            {exporting === 'files' ? <Spinner /> : <Download size={13} />} {t('bkp.export.files', 'File history')}
          </Button>
          <Button size="sm" disabled={!!exporting} onClick={() => exportRepo('db')}>
            {exporting === 'db' ? <Spinner /> : <Download size={13} />} {t('bkp.export.db', 'DB row history')}
          </Button>
          <Button size="sm" variant="ghost" onClick={() => (contents ? setContents(null) : openContents())}>
            <Eye size={13} /> {contents ? t('common.close', 'Close') : t('bkp.contents', "What's in them")}
          </Button>
          <Button size="sm" variant="ghost" onClick={async () => {
            if (pubkey) return setPubkey(null);
            try { setPubkey(await api.get('/server/backups/pubkey')); } catch { toast.error(t('common.failed', 'Failed.')); }
          }}>
            <KeyRound size={13} /> {pubkey ? t('common.close', 'Close') : t('bkp.verify', 'How to verify')}
          </Button>
        </div>

        {pubkey && (
          <div className="mt-3 rounded-lg border border-[var(--line)] panel p-3">
            <p className="text-[11px] text-[var(--muted)] mb-2">
              {t('bkp.verify.s', 'Signed with Ed25519. The key below is public on purpose — checking a backup must not require asking the server that produced it, which is precisely the thing you would be doubting.')}
            </p>
            <div className="flex items-center gap-2 mb-2">
              <code className="flex-1 min-w-0 truncate text-[10px] font-mono px-2 py-1.5 rounded bg-[var(--bg-solid)]">{pubkey.publicKey.split('\n')[1]}…</code>
              <Button size="sm" variant="ghost" onClick={() => { copyText(pubkey.publicKey); toast.success(t('common.copied', 'Copied.')); }}><Copy size={13} /></Button>
            </div>
            <pre className="text-[10px] font-mono whitespace-pre-wrap text-[var(--faint)]">{(pubkey.verify || []).join('\n')}</pre>
          </div>
        )}

        {contents && (
          <div className="mt-3 rounded-lg border border-[var(--line)] max-h-64 overflow-y-auto">
            {['files', 'db'].map((k) => (
              <div key={k}>
                <div className="px-3 py-1.5 text-[11px] uppercase tracking-wider text-[var(--faint)] panel sticky top-0">
                  {k === 'files' ? t('bkp.filehist', 'File history') : t('bkp.dbhist', 'DB row history')} · {(contents[k] || []).length}
                </div>
                {!(contents[k] || []).length
                  ? <div className="px-3 py-2 text-[11px] text-[var(--faint)]">{t('bkp.empty', 'Nothing recorded yet.')}</div>
                  : contents[k].map((c) => (
                    <div key={c.hash} className="px-3 py-1.5 border-t border-[var(--line)] flex items-baseline gap-2">
                      <code className="text-[10px] font-mono text-[var(--faint)] shrink-0">{c.hash.slice(0, 8)}</code>
                      <span className="text-xs truncate flex-1" title={c.message}>{c.message}</span>
                      <span className="text-[10px] text-[var(--faint)] shrink-0">{new Date(c.at).toLocaleString()}</span>
                    </div>
                  ))}
              </div>
            ))}
          </div>
        )}
      </div>

      <SnapshotsPanel onChanged={reload} />
    </Card>
  );
}

