// The stylesheet + the utility classes. The refusals are printed, never swallowed.
function CharityCssCard({ t, d, set, secTitle }) {
  const C = { ...CHARITY_DESIGN_DEFAULTS.classes, ...(d.classes || {}) };
  const { refused } = scopeCss(d.css || '', CHARITY_CSS_SCOPE);
  return (
    <Card className="p-3 space-y-2.5">
      {secTitle(t('chc.design.grp.css', 'Your stylesheet'))}
      <Explain className="text-[11px]" summary={t('chc.design.css.h2', 'Every selector you write is confined to this card.')}>
        {t('chc.design.css.h', 'Every selector you write is confined to this card — it cannot restyle the rest of the site. Target .chy-card, .chy-content, .chy-title, .chy-amount… or [data-el="amount"] and [data-b="…"] for one block. @import, expression(), behaviour and any url() pointing off this site are refused. Tailwind classes only work if the site’s build already contains them, so prefer plain CSS here.')}
      </Explain>
      <Textarea rows={10} value={d.css || ''} onChange={(e) => set('css', e.target.value.slice(0, 20000))} className="font-mono text-[12px]" spellCheck={false}
        placeholder={'.chy-card { background: linear-gradient(135deg,#0f172a,#312e81); border-radius: 28px }\n.chy-amount { font-size: 3rem; letter-spacing: -.02em }\n[data-el="bar"] { display: none }'} />
      {refused.length > 0 && <p className="text-[11.5px] text-warning">{t('chc.design.css.refused', 'Left out:')} {refused.join(' · ')}</p>}
      <div className="grid sm:grid-cols-3 gap-2">
        {['root', 'card', 'content'].map((k) => (
          <Field key={k} label={t(`chc.design.cls.${k}`, k === 'root' ? 'Classes: outer' : k === 'card' ? 'Classes: card' : 'Classes: content')} className="!mb-0">
            <Input className="font-mono !text-xs" maxLength={300} value={C[k]} placeholder="p-10 rounded-3xl" onChange={(e) => set('classes', { ...C, [k]: e.target.value })} />
          </Field>
        ))}
      </div>
    </Card>
  );
}

// The block list: the whole content of a `code` card, in order. Nothing is implicit — an empty
// list draws an empty card, which is a legitimate design.
function CharityBlocksCard({ t, d, set, secTitle }) {
  const blocks = Array.isArray(d.blocks) ? d.blocks : [];
  const write = (next) => set('blocks', next.slice(0, 32));
  const patch = (i, o) => write(blocks.map((b, j) => (j === i ? { ...b, ...o } : b)));
  const move = (i, dir) => { const n = [...blocks]; const j = i + dir; if (j < 0 || j >= n.length) return; [n[i], n[j]] = [n[j], n[i]]; write(n); };
  const KIND_LABEL = {
    icon: t('chc.part.icon', 'Heart icon'), title: t('chc.part.title', 'Title'), sub: t('chc.part.sub', 'Tagline'), month: t('chc.part.month', 'Month pill'),
    amount: t('chc.part.amount', 'Total amount'), breakdown: t('chc.part.breakdown', 'Breakdown line'), bar: t('chc.part.bar', 'Progress bar'),
    association: t('chc.part.association', 'Association line'), poll: t('chc.part.poll', 'Vote line'), projected: t('chc.part.projected', 'Projected share line'),
    paid: t('chc.part.paid', 'Donation-sent notice'), give: t('chc.part.give', 'Give button'), vote: t('chc.part.vote', 'Vote button'),
    more: t('chc.part.more', 'Learn-more button'), buttons: t('chc.blk.buttons', 'All three buttons, one row'),
    text: t('chc.blk.text', 'Your own text'), spacer: t('chc.blk.spacer', 'Spacer'), image: t('chc.blk.image', 'Image'),
  };
  return (
    <Card className="p-3 space-y-2">
      {secTitle(t('chc.design.grp.blocks', 'Blocks — the card, in order'))}
      <p className="text-[11px] text-[var(--muted)] leading-snug">{t('chc.design.blocks.h', 'Add only the pieces you want and order them yourself. Each block gets a class box and a [data-b] hook your stylesheet can target. Your own text is shown as text, never as HTML.')}</p>
      {!blocks.length && <p className="text-[11px] text-[var(--faint)]">{t('chc.design.blocks.empty', 'No blocks: the card draws nothing at all.')}</p>}
      {blocks.map((b, i) => (
        <div key={b.id} className="rounded-lg border border-[var(--line)] p-2 space-y-1.5">
          <div className="flex items-center gap-1.5">
            <Dropdown className="flex-1 min-w-0" value={b.kind} onChange={(v) => patch(i, { kind: v })} options={CHARITY_BLOCK_KINDS.map((k) => ({ value: k, label: KIND_LABEL[k] || k }))} />
            <Button size="sm" variant="ghost" disabled={i === 0} onClick={() => move(i, -1)} title={t('common.moveup', 'Move up')}><ChevronUp size={13} /></Button>
            <Button size="sm" variant="ghost" disabled={i === blocks.length - 1} onClick={() => move(i, 1)} title={t('common.movedown', 'Move down')}><ChevronDown size={13} /></Button>
            <Button size="sm" variant="ghost" onClick={() => write(blocks.filter((_, j) => j !== i))} title={t('common.remove', 'Remove')}><X size={13} /></Button>
          </div>
          <div className="flex gap-1.5 flex-wrap">
            {(b.kind === 'text' || b.kind === 'image') && (
              <Input className="flex-1 min-w-[10rem] !py-1 text-xs" maxLength={400} value={b.text || ''}
                placeholder={b.kind === 'image' ? t('chc.blk.alt', 'Image description (accessibility)') : t('chc.blk.textph', 'The line to show')}
                onChange={(e) => patch(i, { text: e.target.value })} />
            )}
            {b.kind === 'image' && <Input className="flex-1 min-w-[10rem] !py-1 text-xs" maxLength={600} value={b.src || ''} placeholder={t('chc.design.urlph', '…or paste an image URL')} onChange={(e) => patch(i, { src: e.target.value })} />}
            {(b.kind === 'spacer' || b.kind === 'image') && <Input type="number" className="w-24 !py-1 text-xs" min="0" max="720" value={b.size || 0} onChange={(e) => patch(i, { size: Math.max(0, Math.min(720, Number(e.target.value) || 0)) })} title={t('chc.blk.size', 'Height / width in px (0 = auto)')} />}
            <Input className="flex-1 min-w-[8rem] !py-1 text-xs font-mono" maxLength={300} value={b.cls || ''} placeholder={t('chc.blk.cls', 'classes for this block')} onChange={(e) => patch(i, { cls: e.target.value })} />
            <code className="text-[10px] text-[var(--faint)] self-center">[data-b=&quot;{b.id}&quot;]</code>
          </div>
        </div>
      ))}
      <Button size="sm" onClick={() => write([...blocks, { id: chyBlockId(), kind: 'text', text: '', cls: '', src: '', size: 0 }])}><Plus size={13} /> {t('chc.design.blocks.add', 'Add a block')}</Button>
    </Card>
  );
}

function CharityDesignEditor({ design, onChange, pot, currency }) {
  const { t } = useI18n();
  const toast = useToast();
  const d = { ...CHARITY_DESIGN_DEFAULTS, ...(design || {}) };
  const set = (k, v) => onChange({ ...d, [k]: v });
  const sizes = charityCanvasSizes(d);
  const pick = (key) => {
    const i = document.createElement('input'); i.type = 'file'; i.accept = 'image/png,image/webp,image/svg+xml,image/jpeg,image/gif';
    i.onchange = async () => {
      const file = i.files?.[0]; if (!file) return;
      try { toast.info(t('chc.design.uploading', 'Uploading…')); const url = await uploadImage(file); set(key, url); }
      catch { toast.error(t('chc.design.uploadfail', 'Upload failed.')); }
    };
    i.click();
  };
  const px = (o) => `${o.w} × ${o.h} px`;
  const num = (k, min, max) => (e) => set(k, Math.max(min, Math.min(max, Number(e.target.value) || min)));
  const outerRef = useRef(null); const innerRef = useRef(null);
  const fit = useFitScale(outerRef, innerRef);
  const bleed = Number(d.bleed) || 0;
  const previewPot = pot ? { ...pot, currency, poll: pot.pollId ? { id: pot.pollId, question: t('chc.design.pollph', 'Which association this month?'), open: true } : null, presets: [] }
    : { totalCents: 42000, orgContribCents: 30000, communityCents: 12000, currency, association: '', percent: 10, status: 'open', poll: null, presets: [] };
  const LAYERS = [
    ['backdrop', t('chc.design.backdrop', 'Backdrop'), t('chc.design.backdrop.h', 'Fills the frame edge to edge, behind the text.'), px(sizes.backdrop)],
    ['overflow', t('chc.design.overflow', 'Overflow layer'), t('chc.design.overflow.h2', 'A transparent image laid over the frame that may spill past it — a mascot leaning out, a ribbon, confetti. Keep the middle clear: the text sits on top.'), `${px(sizes.overflow)} · ${t('chc.design.bleedof', '{n} px of bleed each side').replace('{n}', sizes.overflow.bleed)}`],
    ['sticker', t('chc.design.sticker', 'Corner sticker'), t('chc.design.sticker.h', 'A small image pinned to one corner, sticking out of the frame.'), px(sizes.sticker)],
  ];
  const MODES = [
    ['default', t('chc.design.mode.default', 'Default card'), t('chc.design.mode.default.h', 'The glowing card, drawn by the site. Nothing to upload.')],
    ['custom', t('chc.design.mode.custom', 'Custom artwork'), t('chc.design.mode.custom.h2', 'Your own backdrop, overflow layer and corner sticker — and now: drop any element of the card, re-word any label, add your own CSS.')],
    ['code', t('chc.design.mode.code', 'Write it yourself'), t('chc.design.mode.code.h', 'No card drawn by the site at all: you choose the blocks, their order, and style them with your own scoped CSS.')],
  ];
  // Picking `code` on an empty design hands over the default card taken apart, not a blank box:
  // an admin who has never seen the part names would otherwise have to guess them.
  const setMode = (v) => onChange({ ...d, mode: v, blocks: (v === 'code' && !(d.blocks || []).length) ? CHY_SEED_BLOCKS.map((b) => ({ ...b, id: chyBlockId() })) : d.blocks });
  const secTitle = (txt) => <div className="text-[11px] font-semibold uppercase tracking-wider text-[var(--faint)]">{txt}</div>;
  const corners = [['tl', 'rounded-tl-md', 'top-1 left-1'], ['tr', 'rounded-tr-md', 'top-1 right-1'], ['bl', 'rounded-bl-md', 'bottom-1 left-1'], ['br', 'rounded-br-md', 'bottom-1 right-1']];
  return (
    <div className="mt-5 pt-4 border-t border-[var(--line)]">
      <h3 className="font-medium mb-1 flex items-center gap-2"><Palette size={15} /> {t('chc.design.t', 'Landing design')}</h3>
      <p className="text-xs text-[var(--muted)] mb-3">{t('chc.design.sub2', 'How the charity card looks on the home page. Pick a style; with custom artwork, upload the layers and watch the preview — it is the card exactly as the page draws it.')}</p>

      {/* The picked mode used to carry an alpha on a CSS variable, which Tailwind emits no rule
          for, so it was never actually tinted — .tint-primary-soft is the house class. */}
      <div className="grid sm:grid-cols-3 gap-2 mb-4">
        {MODES.map(([v, l, h]) => (
          <button key={v} type="button" onClick={() => setMode(v)}
            className={`text-start rounded-xl border p-3 flex gap-3 items-start transition ${d.mode === v ? 'border-[var(--primary)] tint-primary-soft' : 'border-[var(--line)] hover:border-[var(--line-strong)]'}`}>
            <span className={`w-12 h-9 rounded-md shrink-0 border ${v === 'default' ? 'bg-gradient-to-br from-[var(--primary)] to-transparent b-primary' : 'border-dashed border-[var(--line-strong)] bg-[var(--surface-2)]'} grid place-items-center`}>
              {v === 'default' ? <Heart size={14} className="text-[var(--accent-ink)]" /> : v === 'code' ? <Code2 size={14} className="text-[var(--muted)]" /> : <ImageIcon size={14} className="text-[var(--muted)]" />}
            </span>
            <span className="min-w-0"><span className="block text-sm font-medium">{l}</span><span className="block text-[11px] text-[var(--muted)] leading-snug">{h}</span></span>
          </button>
        ))}
      </div>

      {d.mode === 'custom' && (
        <div className="grid gap-4 lg:grid-cols-[minmax(0,1fr)_300px] items-start">
          <div className="space-y-2 min-w-0">
            {secTitle(t('chc.design.grp.layers', 'Layers'))}
            {LAYERS.map(([key, title, hint, canvas]) => (
              <div key={key} className="rounded-xl border border-[var(--line)] p-3 flex gap-3 items-start min-w-0">
                <button type="button" onClick={() => pick(key)} title={t('chc.design.upload', 'Upload')}
                  className="w-16 h-16 rounded-lg border border-dashed border-[var(--line-strong)] bg-[var(--bg-solid)] grid place-items-center shrink-0 overflow-hidden hover:border-[var(--primary)]">
                  {d[key] ? <img src={d[key]} alt="" className="w-full h-full object-contain" /> : <Upload size={16} className="text-[var(--faint)]" />}
                </button>
                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-2 flex-wrap">
                    <span className="text-sm font-medium">{title}</span>
                    <span className="text-[10px] px-1.5 py-0.5 rounded-full bg-[var(--surface-2)] text-[var(--muted)] tabular-nums" title={t('chc.design.canvas', 'Canvas to draw')}>{canvas}</span>
                  </div>
                  <div className="text-[11px] text-[var(--muted)] leading-snug mt-0.5">{hint}</div>
                  <div className="flex gap-1.5 mt-2 flex-wrap items-center">
                    <Button size="sm" onClick={() => pick(key)}><Upload size={13} /> {d[key] ? t('chc.design.replace', 'Replace') : t('chc.design.upload', 'Upload')}</Button>
                    <Input className="flex-1 min-w-[9rem] !py-1 text-xs" placeholder={t('chc.design.urlph', '…or paste an image URL')} value={d[key]} onChange={(e) => set(key, e.target.value)} />
                    {d[key] ? <Button size="sm" variant="ghost" onClick={() => set(key, '')} title={t('common.remove', 'Remove')}><X size={13} /></Button> : null}
                  </div>
                </div>
              </div>
            ))}
            <Field label={t('chc.design.alt', 'Artwork description (accessibility)')} className="!mb-0 pt-1"><Input maxLength={200} value={d.alt} onChange={(e) => set('alt', e.target.value)} placeholder={t('chc.design.altph', 'e.g. Our mascot holding a piggy bank')} /></Field>
          </div>

          <div className="space-y-3">
            <CharityFrameCard t={t} d={d} set={set} num={num} sizes={sizes} secTitle={secTitle} />
            <Card className="p-3 space-y-2.5">
              {secTitle(t('chc.design.grp.place', 'Placement'))}
              <div className="grid grid-cols-2 gap-2">
                <Field label={t('chc.design.fit', 'Backdrop fit')} className="!mb-0"><Dropdown value={d.backdropFit} onChange={(v) => set('backdropFit', v)} options={[{ value: 'cover', label: t('chc.design.fit.cover', 'Cover (crop)') }, { value: 'contain', label: t('chc.design.fit.contain', 'Contain') }, { value: 'fill', label: t('chc.design.fit.fill', 'Stretch') }]} /></Field>
                <Field label={t('chc.design.bleed', 'Overflow bleed (px)')} className="!mb-0"><Input type="number" min="0" max="200" value={d.bleed} onChange={num('bleed', 0, 200)} /></Field>
              </div>
              <div className="grid grid-cols-[auto_minmax(0,1fr)] gap-3 items-start">
                <div>
                  <div className="text-[11px] text-[var(--faint)] mb-1">{t('chc.design.corner', 'Sticker corner')}</div>
                  <div className="relative w-[84px] h-[64px] rounded-lg border border-[var(--line)] bg-[var(--surface-2)]">
                    {corners.map(([c, , pos]) => (
                      <button key={c} type="button" onClick={() => set('stickerCorner', c)} aria-label={c}
                        className={`absolute ${pos} w-7 h-6 rounded-md border transition ${d.stickerCorner === c ? 'border-[var(--primary)] bg-[var(--primary)]' : 'border-[var(--line)] bg-[var(--bg-solid)] hover:border-[var(--line-strong)]'}`} />
                    ))}
                  </div>
                </div>
                <div className="space-y-2">
                  <Field label={t('chc.design.stickersize', 'Sticker size (px)')} className="!mb-0"><Input type="number" min="48" max="320" value={d.stickerSize} onChange={num('stickerSize', 48, 320)} /></Field>
                  <Field label={t('chc.design.overhang', 'Overhang (px)')} className="!mb-0"><Input type="number" min="0" max="160" value={d.stickerOffset} onChange={num('stickerOffset', 0, 160)} /></Field>
                </div>
              </div>
            </Card>
          </div>
        </div>
      )}

      {d.mode === 'code' && (
        <div className="grid gap-4 lg:grid-cols-[minmax(0,1fr)_300px] items-start">
          <div className="space-y-3 min-w-0"><CharityBlocksCard t={t} d={d} set={set} secTitle={secTitle} /></div>
          <div className="space-y-3"><CharityFrameCard t={t} d={d} set={set} num={num} sizes={sizes} secTitle={secTitle} /></div>
        </div>
      )}

      {/* Shared by both authored modes: the words, the per-element switches (artwork mode only
          — in `code` mode the block list IS the switch), and the stylesheet. */}
      {d.mode !== 'default' && (
        <div className="grid gap-3 lg:grid-cols-2 items-start mt-3">
          <div className="space-y-3">
            {d.mode === 'custom' && <CharityPartsCard t={t} d={d} set={set} secTitle={secTitle} keys={CHARITY_PART_KEYS.filter((k) => k !== 'month')} />}
            <CharityLabelsCard t={t} d={d} set={set} secTitle={secTitle} />
          </div>
          <CharityCssCard t={t} d={d} set={set} secTitle={secTitle} />
        </div>
      )}

      <div className="mt-4">
        <div className="flex items-center justify-between gap-2 mb-1.5">
          {secTitle(t('chc.design.preview', 'Preview, the card as the home page draws it'))}
          {fit.k < 0.995 && <span className="text-[10px] text-[var(--faint)] tabular-nums">{t('chc.design.scaled', 'Shown at {p} %, the page draws it full size.').replace('{p}', Math.round(fit.k * 100))}</span>}
        </div>
        <div ref={outerRef} className="rounded-xl border border-dashed border-[var(--line)] bg-[var(--bg)] p-2 overflow-hidden">
          <div style={{ height: fit.h || undefined }}>
            <div ref={innerRef} style={{ transform: `scale(${fit.k})`, transformOrigin: 'top left', width: 'max-content', padding: `${bleed + 12}px` }}>
              <CharityCard pot={previewPot} design={d} t={t} onGive={() => {}} preview />
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

function CharityAdminCard() {
  const { t } = useI18n();
  const toast = useToast();
  const dialog = useDialog();
  const { data, loading, reload } = useAsync(() => api.get('/admin/charity'), []);
  // The polls, so the month's vote is PICKED from a list rather than pasted as an id nobody
  // can copy — the whole "search the id" pain. Failure is silent: the picker falls back to a
  // plain input so a polls-permission gap never blocks saving the pot.
  const pollsQ = useAsync(() => api.get('/admin/polls').then((d) => d.polls || []).catch(() => []), []);
  const polls = pollsQ.data || [];
  const pollLabel = (pl) => pl.question || pl.title || pl.questions?.[0]?.text || pl.questions?.[0]?.question || `${t('chc.poll.untitled', 'Untitled poll')} · ${pl.id.slice(0, 8)}`;
  const [cfg, setCfg] = useState(null);
  const [pot, setPot] = useState(null);
  const [busy, setBusy] = useState(false);
  useEffect(() => { if (data) { setCfg(data.config); setPot(data.pot); } }, [data]);
  if (loading || !cfg) return null;
  const money = (c) => `${((c || 0) / 100).toFixed(2)} ${(cfg.currency || 'chf').toUpperCase()}`;
  const saveConfig = async () => {
    setBusy(true);
    try {
      const r = await api.put('/admin/charity', { enabled: cfg.enabled, percent: Number(cfg.percent) || 0, currency: cfg.currency, association: cfg.association, design: cfg.design || CHARITY_DESIGN_DEFAULTS });
      setCfg(r.config); toast.success(t('chc.saved', 'Saved.')); reload();
    } catch { toast.error(t('common.failed', 'Failed.')); } finally { setBusy(false); }
  };
  const savePot = async () => {
    setBusy(true);
    try {
      const r = await api.put('/admin/charity/pot', { pollId: pot.pollId || null, association: pot.association, status: pot.status, proofUrl: pot.proofUrl, proofNote: pot.proofNote });
      setPot(r.pot); toast.success(t('chc.saved', 'Saved.'));
    } catch (e) { toast.error(e?.data?.error === 'poll_not_found' ? t('chc.pollnotfound', 'Poll not found.') : t('common.failed', 'Failed.')); }
    finally { setBusy(false); }
  };
  const closeMonth = async () => {
    if (!await dialog.confirm({ title: t('chc.close.t', 'Freeze this month’s share?'), message: t('chc.close.m', 'This computes BetterCommunity’s contribution from the current revenue and freezes it, so a later change never rewrites it. You can still record the proof and mark it paid afterwards.'), confirmLabel: t('chc.close.ok', 'Freeze share') })) return;
    setBusy(true);
    try { const r = await api.post('/admin/charity/close', {}); setPot(r.pot); toast.success(t('chc.frozen', 'Share frozen.')); reload(); }
    catch (e) { toast.error(e?.data?.error === 'already_paid' ? t('chc.paidalready', 'This month is already paid.') : t('common.failed', 'Failed.')); }
    finally { setBusy(false); }
  };
  const pv = data.preview || {};
  return (
    <Card className="mt-6 p-5">
      <h2 className="font-semibold mb-1 flex items-center gap-2"><Heart size={16} className="text-[var(--accent-ink)]" /> {t('chc.title', 'Community Charity')}</h2>
      <p className="text-sm text-[var(--muted)] mb-4">{t('chc.sub', 'Each month a share of eligible revenue goes to a community-chosen association. The final payment is sent manually.')}</p>

      <label className="flex items-center gap-2 text-sm cursor-pointer select-none mb-3">
        <input type="checkbox" className="accent-[var(--primary)]" checked={cfg.enabled} onChange={(e) => setCfg((c) => ({ ...c, enabled: e.target.checked }))} /> {t('chc.enabled', 'Enable Community Charity')}
      </label>
      <div className="grid gap-2 sm:grid-cols-3">
        <Field label={t('chc.percent', 'Percentage (max 50%)')}><Input type="number" min="0" max="50" value={cfg.percent} onChange={(e) => setCfg((c) => ({ ...c, percent: e.target.value }))} /></Field>
        <Field label={t('chc.currency', 'Currency')}><Input value={cfg.currency} onChange={(e) => setCfg((c) => ({ ...c, currency: e.target.value }))} /></Field>
        <Field label={t('chc.assoc', 'Default association')}><Input placeholder={t('chc.assoc.ph', 'Association name')} value={cfg.association} onChange={(e) => setCfg((c) => ({ ...c, association: e.target.value }))} /></Field>
      </div>
      <div className="rounded-lg bg-[var(--surface-2)] px-3 py-2 text-sm mt-3 flex flex-wrap items-center gap-x-4 gap-y-1">
        <span className="text-[var(--muted)]">{t('chc.eligible', 'Eligible recurring revenue')}: <b className="text-[var(--text)] tabular-nums">{money(pv.eligibleCents)}</b></span>
        <span>{t('chc.orgadds', 'BetterCommunity adds {n} at {p}%').replace('{n}', money(pv.orgShareCents)).replace('{p}', pv.percent ?? cfg.percent)}</span>
      </div>
      <CharityDesignEditor design={cfg.design || CHARITY_DESIGN_DEFAULTS} onChange={(d) => setCfg((c) => ({ ...c, design: d }))} pot={data.pot} preview={data.preview} currency={cfg.currency} />
      <div className="flex justify-end mt-3"><Button variant="primary" loading={busy} onClick={saveConfig}><Save size={15} /> {t('chc.save', 'Save')}</Button></div>

      {pot && (
        <div className="mt-5 pt-4 border-t border-[var(--line)]">
          <h3 className="font-medium mb-2 flex items-center gap-2"><Vote size={15} /> {t('chc.pot', 'This month’s pot')} · {pot.month}</h3>
          <div className="text-sm text-[var(--muted)] mb-3">{t('chc.total', 'Total')}: <b className="text-[var(--text)] tabular-nums">{money(pot.totalCents)}</b> <span className="text-[var(--faint)]">({money(pot.orgContribCents)} + {money(pot.communityCents)})</span></div>
          <div className="grid gap-2 sm:grid-cols-3">
            <Field label={t('chc.poll', 'Linked vote')}>
              {/* Pick the association vote straight from the poll list. A pot pointing at a
                  poll that no longer exists keeps that id as its own option so saving never
                  silently drops it; if the poll list could not load at all, fall back to a
                  plain id box rather than an empty picker. */}
              {pollsQ.loading || polls.length || pot.pollId ? (
                <Dropdown value={pot.pollId || ''} onChange={(v) => setPot((x) => ({ ...x, pollId: v || null }))}
                  options={[
                    { value: '', label: t('chc.poll.none', '— No linked vote —') },
                    ...polls.map((pl) => ({ value: pl.id, label: pollLabel(pl) })),
                    ...(pot.pollId && !polls.some((pl) => pl.id === pot.pollId) ? [{ value: pot.pollId, label: `${t('chc.poll.missing', 'Removed poll')} · ${String(pot.pollId).slice(0, 8)}` }] : []),
                  ]} />
              ) : (
                <Input placeholder={t('chc.poll.ph', 'Poll id of the association vote')} value={pot.pollId || ''} onChange={(e) => setPot((x) => ({ ...x, pollId: e.target.value }))} />
              )}
            </Field>
            <Field label={t('chc.assoc', 'Chosen association')}><Input placeholder={t('chc.assoc.ph', 'Association name')} value={pot.association} onChange={(e) => setPot((x) => ({ ...x, association: e.target.value }))} /></Field>
            <Field label={t('chc.status', 'Status')}><Dropdown value={pot.status} onChange={(v) => setPot((x) => ({ ...x, status: v }))} options={[
              { value: 'open', label: t('chc.status.open', 'Open') },
              { value: 'closing', label: t('chc.status.closing', 'Closing') },
              { value: 'paid', label: t('chc.status.paid', 'Paid') },
            ]} /></Field>
          </div>
          {/* Month-end: freeze the share, then record the manual donation's proof. */}
          <div className="grid gap-2 sm:grid-cols-2 mt-2">
            <Field label={t('chc.proofurl', 'Proof link (receipt / transfer)')}><Input placeholder="https://…" value={pot.proofUrl} onChange={(e) => setPot((x) => ({ ...x, proofUrl: e.target.value }))} /></Field>
            <Field label={t('chc.proofnote', 'Proof note (internal)')}><Input value={pot.proofNote} onChange={(e) => setPot((x) => ({ ...x, proofNote: e.target.value }))} /></Field>
          </div>
          {pot.paidAt && <div className="text-xs text-[var(--faint)] mt-2">{t('chc.paidon', 'Marked paid on {d}').replace('{d}', new Date(pot.paidAt).toLocaleDateString())}</div>}
          <div className="flex flex-wrap justify-end gap-2 mt-3">
            <Button variant="ghost" loading={busy} onClick={closeMonth} disabled={pot.status === 'paid'}><Lock size={15} /> {t('chc.close.ok', 'Freeze share')}</Button>
            <Button variant="primary" loading={busy} onClick={savePot}><Save size={15} /> {t('chc.savepot', 'Save pot')}</Button>
          </div>
        </div>
      )}
    </Card>
  );
}

// The Discord bot's strings. The bot reports its built-in dictionary (EN, FR, DE, ES) on its
// first heartbeat; this edits an override layer per language — the same idea as the site's
// base-language editor — and a language the bot does not ship can be added by code: the bot
// falls back key by key to English. Saved per language; the bot picks it up within 30 s.
function BotI18nCard() {
  const { t } = useI18n();
  const toast = useToast();
  const { data, loading, reload } = useAsync(() => api.get('/admin/bot/i18n'), []);
  const [lang, setLang] = useState('fr');
  const [q, setQ] = useState('');
  const [draft, setDraft] = useState({});
  const [busy, setBusy] = useState(false);
  const [custom, setCustom] = useState('');
  const base = data?.base || {};
  const overrides = data?.overrides || {};
  const langs = useMemo(() => [...new Set([...Object.keys(base), ...Object.keys(overrides)])].sort(), [base, overrides]);
  const keys = useMemo(() => Object.keys(base.en || {}).sort(), [base]);
  const nq = q.trim().toLowerCase();
  const shown = keys.filter((k) => !nq || k.includes(nq) || String(base.en?.[k] || '').toLowerCase().includes(nq) || String(base[lang]?.[k] || overrides[lang]?.[k] || '').toLowerCase().includes(nq));
  const valueOf = (k) => (draft[k] !== undefined ? draft[k] : (overrides[lang]?.[k] ?? ''));
  const changed = Object.keys(draft).length;
  const save = async () => {
    setBusy(true);
    try { const r = await api.put('/admin/bot/i18n', { lang, strings: draft }); toast.success(t('bi.saved', 'Saved, the bot picks it up within 30 s.')); setDraft({}); reload(); void r; }
    catch { toast.error(t('common.failed', 'Failed.')); }
    finally { setBusy(false); }
  };
  const missing = keys.filter((k) => !(base[lang]?.[k]) && !(overrides[lang]?.[k])).length;
  return (
    <Card className="mt-6 p-5">
      <h2 className="font-semibold mb-1 flex items-center gap-2"><MessageSquare size={16} className="text-[var(--accent-ink)]" /> {t('bi.title', 'Discord bot')}</h2>
      <Explain className="text-sm mb-3">{t('bi.sub', 'Every text the bot shows — buttons, cards, the casino, the onboarding — per language. The bot ships English, French, German and Spanish; edit any of them here, or add a language by code (missing keys fall back to English). A server’s manager picks the bot’s language on the welcome card (/setup); “auto” follows each member’s own Discord language.')}</Explain>
      {loading ? <Spinner /> : !keys.length ? (
        <div className="text-sm text-[var(--faint)]">{t('bi.nobase', 'The bot has not reported its dictionary yet, it does on its first heartbeat after starting. Start the bot, then reload.')}</div>
      ) : (
        <>
          <div className="flex flex-wrap items-center gap-2 mb-3">
            <div className="inline-flex rounded-lg border border-[var(--line)] p-0.5 text-xs">
              {langs.map((l) => <button key={l} type="button" onClick={() => { setLang(l); setDraft({}); }} className={`px-2.5 py-1 rounded-md uppercase ${lang === l ? 'bg-[var(--surface-2)] text-[var(--text)] font-medium' : 'text-[var(--muted)]'}`}>{l}{overrides[l] && Object.keys(overrides[l]).length ? <span className="ms-1 text-[9px] text-[var(--accent-ink)]">●</span> : null}</button>)}
            </div>
            <div className="flex items-center gap-1">
              <Input className="!py-1 !text-xs w-16" placeholder="it" maxLength={5} value={custom} onChange={(e) => setCustom(e.target.value.toLowerCase())} />
              <Button size="sm" variant="ghost" disabled={!/^[a-z]{2}$/.test(custom) || langs.includes(custom)} onClick={() => { setLang(custom); setDraft({}); setCustom(''); }}><Plus size={13} /> {t('bi.addlang', 'Add a language')}</Button>
            </div>
            <div className="relative flex-1 min-w-[12rem]"><Search size={13} className="absolute left-2.5 top-1/2 -translate-y-1/2 text-[var(--faint)] pointer-events-none" /><Input className="!ps-8 !py-1.5 !text-sm" placeholder={t('bi.search', 'Search a key or a text…')} value={q} onChange={(e) => setQ(e.target.value)} /></div>
            <span className="text-[11px] text-[var(--faint)]">{t('bi.missing', '{n} of {k} keys without a text in {l}').replace('{n}', missing).replace('{k}', keys.length).replace('{l}', lang.toUpperCase())}</span>
            <Button size="sm" variant="primary" disabled={!changed || busy} onClick={save}>{busy ? <Spinner /> : <Save size={13} />} {t('bi.save', 'Save {n}').replace('{n}', changed)}</Button>
          </div>
          <div className="rounded-lg border border-[var(--line)] divide-y divide-[var(--line)] max-h-[60vh] overflow-auto">
            {shown.map((k) => {
              const en = base.en?.[k] || '';
              const shipped = base[lang]?.[k] || '';
              const v = valueOf(k);
              return (
                <div key={k} className="grid md:grid-cols-[minmax(0,1fr)_minmax(0,1fr)] gap-2 px-3 py-2">
                  <div className="min-w-0">
                    <div className="text-[10px] font-mono text-[var(--faint)] truncate" title={k}>{k}</div>
                    <div className="text-xs text-[var(--muted)] break-words">{en}</div>
                    {shipped && lang !== 'en' && <div className="text-[11px] text-[var(--faint)] break-words mt-0.5">{t('bi.shipped', 'Shipped')}: {shipped}</div>}
                  </div>
                  <Input className="!py-1 !text-xs" value={v} placeholder={shipped || en} onChange={(e) => setDraft((d) => ({ ...d, [k]: e.target.value }))} />
                </div>
              );
            })}
            {!shown.length && <div className="p-4 text-sm text-[var(--faint)]">{t('bi.none', 'No key matches.')}</div>}
          </div>
        </>
      )}
    </Card>
  );
}

function LanguagesCard() {
  const { t } = useI18n();
  const toast = useToast();
  const dialog = useDialog();
  const { data, loading, reload } = useAsync(() => api.get('/admin/locales'), []);
  const [add, setAdd] = useState({ code: '', nativeName: '', englishName: '', rtl: false });
  const [busy, setBusy] = useState(false);
  const [editing, setEditing] = useState(null);
  const locales = data?.locales || [];
  const core = useMemo(() => {
    const out = {};
    for (const p of CORE_I18N_PREFIXES) Object.assign(out, shippedText(p));
    return out;
  }, []);
  // The FULL dictionary (~7k keys) for the "All strings" editor scope. `shippedText('')` returns
  // every key (every key startsWith ''), enumerated from the complete French dictionary.
  const allKeys = useMemo(() => shippedText(''), []);
  const create = async () => {
    const code = add.code.trim();
    if (!code || !add.nativeName.trim()) return;
    setBusy(true);
    try {
      await api.post('/admin/locales', { code, nativeName: add.nativeName.trim(), englishName: add.englishName.trim(), rtl: add.rtl });
      toast.success(t('lc.added', 'Language added.'));
      setAdd({ code: '', nativeName: '', englishName: '', rtl: false });
      reload();
    } catch (e) {
      const err = e?.data?.error;
      toast.error(err === 'exists' ? t('lc.exists', 'That language already exists.')
        : err === 'reserved_code' ? t('lc.reserved', 'English and French are built in.')
          : err === 'bad_code' ? t('lc.badcode', 'Invalid language code (e.g. “ru”, “zh-Hans”).')
            : t('common.failed', 'Failed.'));
    } finally { setBusy(false); }
  };
  const undoDel = useUndoableDelete(reload);
  const patchOne = async (code, body) => { try { await api.put(`/admin/locales/${code}`, body); reload(); } catch { toast.error(t('common.failed', 'Failed.')); } };
  const remove = async (l) => {
    if (!await dialog.confirm({
      title: t('lc.del.t', 'Remove language'),
      message: t('lc.del.m', 'Remove {x}? Its translations are deleted; visitors on it fall back to English.').replace('{x}', l.nativeName),
      confirmLabel: t('lc.del.ok', 'Remove'),
    })) return;
    // The most expensive delete on this screen: a language takes every string anybody
    // translated into it. The window is the difference between a mis-click and an evening.
    undoDel.del(l.code, () => api.del(`/admin/locales/${l.code}`), t('lc.removed', 'Language removed.'));
  };
  const coreCount = Object.keys(core).length;
  return (
    <Card className="mt-6 p-5">
      <h2 className="font-semibold mb-1 flex items-center gap-2"><Languages size={16} className="text-[var(--accent-ink)]" /> {t('lc.title', 'Languages')}</h2>
      <p className="text-sm text-[var(--muted)] mb-3">{t('lc.sub2', 'Edit every site string, in any language. English and French are the built-in base — edit them as an override; add more languages below. Saving applies live for everyone, and clearing a field falls back to the built-in text.')}</p>

      {/* A plain three-step so a translator knows where to start without reading the paragraph. */}
      <div className="rounded-xl border border-[var(--line)] panel p-3 mb-4 text-[12px] text-[var(--muted)] space-y-1.5">
        {[
          t('lc.step1', 'Add a language below, or edit English / French, the built-in base.'),
          t('lc.step2', 'Click Translate to open the editor: search a key, or use “Next missing” to jump straight to the gaps.'),
          t('lc.step3', 'Type the translation, it applies live for everyone. Leave a field empty to fall back to the built-in text.'),
        ].map((s, i) => (
          <div key={i} className="flex items-start gap-2">
            <span className="grid place-items-center w-5 h-5 rounded-full tint-primary text-[var(--accent-ink)] text-[10px] font-bold shrink-0">{i + 1}</span>
            <span>{s}</span>
          </div>
        ))}
      </div>

      {/* Built-in en/fr — editable override layer. This is the general text editor that
          replaced the old home-page-only text editor: any string, both base languages. */}
      <div className="rounded-xl border border-[var(--line)] p-3 mb-4">
        <div className="text-[11px] font-semibold uppercase tracking-wider text-[var(--faint)] mb-2">{t('lc.base', 'Built-in languages')}</div>
        <div className="flex flex-wrap gap-2">
          {[['en', 'English'], ['fr', 'Français']].map(([code, name]) => (
            <button key={code} type="button" onClick={() => setEditing({ code, nativeName: name, rtl: false, base: true })}
              className="inline-flex items-center gap-2 px-3 py-2 rounded-lg border border-[var(--line)] hover:border-[var(--primary)] text-sm transition">
              <PenSquare size={13} className="text-[var(--accent-ink)]" /> {t('lc.editbase', 'Edit {x}').replace('{x}', name)}
              {data?.baseCounts?.[code] > 0 && <Badge tone="primary">{t('lc.overridden', '{n} changed').replace('{n}', data.baseCounts[code])}</Badge>}
            </button>
          ))}
        </div>
      </div>

      {/* Add a language */}
      <div className="rounded-xl border border-[var(--line)] p-3 mb-4 grid gap-2 sm:grid-cols-[7rem_1fr_1fr_auto] items-end">
        <Field label={t('lc.code', 'Code')}><Input placeholder="ru" value={add.code} onChange={(e) => setAdd((a) => ({ ...a, code: e.target.value }))} /></Field>
        <Field label={t('lc.native', 'Native name')}><Input placeholder="Русский" value={add.nativeName} onChange={(e) => setAdd((a) => ({ ...a, nativeName: e.target.value }))} /></Field>
        <Field label={t('lc.english', 'English name')}><Input placeholder="Russian" value={add.englishName} onChange={(e) => setAdd((a) => ({ ...a, englishName: e.target.value }))} /></Field>
        <div className="flex items-center gap-2 pb-1">
          <label className="flex items-center gap-1.5 text-[13px] cursor-pointer select-none whitespace-nowrap"><input type="checkbox" className="accent-[var(--primary)]" checked={add.rtl} onChange={(e) => setAdd((a) => ({ ...a, rtl: e.target.checked }))} /> {t('lc.rtl', 'RTL')}</label>
          <Button size="sm" variant="primary" loading={busy} onClick={create} disabled={!add.code.trim() || !add.nativeName.trim()}><Plus size={14} /> {t('lc.add', 'Add')}</Button>
        </div>
      </div>

      {/* Existing languages */}
      {loading ? <Loading /> : locales.length ? (
        <div className="space-y-2">
          {locales.filter((l) => !undoDel.pending.has(l.code)).map((l) => (
            <div key={l.code} className="flex items-center gap-3 rounded-lg border border-[var(--line)] px-3 py-2 flex-wrap">
              <span className="font-medium">{l.nativeName}</span>
              <code className="text-[11px] text-[var(--faint)]">{l.code}</code>
              {l.rtl && <Badge>RTL</Badge>}
              <Badge tone={l.translatedKeys ? 'primary' : ''}>{t('lc.count', '{n} translated').replace('{n}', l.translatedKeys)}</Badge>
              <div className="flex-1" />
              <label className="flex items-center gap-1.5 text-[12px] cursor-pointer select-none" title={t('lc.enabled.h', 'Show this language in the public picker')}>
                <input type="checkbox" className="accent-[var(--primary)]" checked={l.enabled} onChange={(e) => patchOne(l.code, { enabled: e.target.checked })} /> {t('lc.enabled', 'Public')}
              </label>
              <label className="flex items-center gap-1.5 text-[12px] cursor-pointer select-none">
                <input type="checkbox" className="accent-[var(--primary)]" checked={l.rtl} onChange={(e) => patchOne(l.code, { rtl: e.target.checked })} /> {t('lc.rtl', 'RTL')}
              </label>
              <Button size="sm" variant="ghost" onClick={() => setEditing(l)}><PenSquare size={13} /> {t('lc.translate', 'Translate')}</Button>
              <button className="p-1.5 rounded-lg text-error hover:bg-error-bg" title={t('lc.del.ok', 'Remove')} onClick={() => remove(l)}><Trash2 size={13} /></button>
            </div>
          ))}
        </div>
      ) : <EmptyState icon={Languages} title={t('lc.none', 'No extra languages yet')} sub={t('lc.none.s', 'Add one above to translate the site beyond English and French.')} />}

      <p className="text-[11px] text-[var(--faint)] mt-3">{t('lc.editornote2', 'The editor opens on the {n} most-visible strings; switch to “All strings” inside it to reach the full dictionary. Right-to-left languages set their reading direction with the RTL toggle.').replace('{n}', coreCount)}</p>
      {editing && <LocaleStringEditor locale={editing} core={core} allKeys={allKeys} onClose={() => { setEditing(null); reload(); }} />}
    </Card>
  );
}

function AdminSettings() {
  const toast = useToast();
  const { t } = useI18n();
  const { data, reload } = useAsync(() => api.get('/admin/settings'), []);
  const cap = useAsync(() => api.get('/hosting/capacity'), []);
  const [draft, setDraft] = useState({});
  const [busy, setBusy] = useState(null);
  const [unit, setUnit] = useState({}); // settingKey -> 'MB' | 'GB' (display unit only)
  // The sub-tab strip below replaced the per-group collapse this screen used to have
  // (localStorage bcw.hs.collapsed is no longer read or written).
  // Which group is on screen. Remembered, because an admin who came here to change one thing
  // usually comes back for the same thing.
  // ?s=settings&hs=<group> opens a tab directly, so the guide's "Hosting settings → Security &
  // audit logs" can be a link rather than an instruction to go and find it. A URL that names a
  // tab wins over the remembered one; an unknown name falls back rather than showing nothing.
  const [hsSp] = useSearchParams();
  const [tab, setTab] = useState(() => {
    const want = hsSp.get('hs');
    if (want && HS_TABS.some((x) => x.gk === want)) return want;
    try { return localStorage.getItem('bcw.hs.tab') || 'capacity'; } catch { return 'capacity'; }
  });
  useEffect(() => {
    const want = hsSp.get('hs');
    if (want && HS_TABS.some((x) => x.gk === want)) setTab(want);
  }, [hsSp]);
  useEffect(() => { try { localStorage.setItem('bcw.hs.tab', tab); } catch { /* private mode */ } }, [tab]);
  const [freePoolOpen, setFreePoolOpen] = useState(false);
  const [tempOpen, setTempOpen] = useState(false);
  // Searching crosses every tab on purpose. The tabs answer "where is this one thing" and
  // that is only useful once you know which tab it is on; typing "blog" or "grace" or the
  // setting key itself gets there without knowing.
  const [q, setQ] = useState('');
  useEffect(() => { if (data?.settings) setDraft(data.settings); }, [data]);
  const coerce = (v, kind) => kind === 'bool' ? !!v : (v !== '' && !isNaN(Number(v)) ? Number(v) : v);
  const undoSaveOne = useUndoableSave(() => { reload(); cap.reload?.(); });
  const save = (key, kind) => {
    // Value coerced now, not inside the window — the field stays editable while it counts down.
    const value = coerce(draft[key], kind);
    setBusy(key);
    undoSaveOne(() => api.put(`/admin/settings/${key}`, { value }), t('hs.saved', 'Saved.'),
      { onSettled: () => setBusy(null),
        errorFor: (x) => x.data?.error === 'exceeds_disk'
          ? t('hs.exceedsdisk', `Exceeds the real disk capacity (${x.data.diskGB} GB max).`).replace('{n}', x.data.diskGB)
          : t('hs.savefail', 'Save failed.') });
  };
  // "Save all changes" — edit several settings (CPU / storage / upload …) and save them
  // in one click, instead of one Save button per field.
  const KIND_OF = {}; SETTINGS_GROUPS.forEach((g) => g.keys.forEach(([k, , , kind]) => { KIND_OF[k] = kind === 'gbmb' ? 'number' : kind; }));
  const dirtyKeys = Object.keys(KIND_OF).filter((k) => {
    const kind = KIND_OF[k];
    const cur = coerce(draft[k] ?? (kind === 'bool' ? false : ''), kind);
    const saved = data?.settings?.[k] ?? (kind === 'bool' ? false : '');
    return JSON.stringify(cur) !== JSON.stringify(saved);
  });
  // How many unsaved keys sit in a tab you are not looking at. Without this the sub-tabs would
  // hide edits: "Save all (3)" is floating at the bottom and two of the three are on a tab that
  // is off screen, with nothing saying where.
  const KEYS_BY_GROUP = {};
  SETTINGS_GROUPS.forEach((g) => { KEYS_BY_GROUP[g.gk] = g.keys.map(([k]) => k); });
  // `all` holds every key, so it carries the total — otherwise the one tab that shows
  // everything would be the one tab with no unsaved marker. `tools` holds cards and no
  // settings, so it correctly has none.
  const dirtyIn = (gk) => (gk === 'all' ? dirtyKeys.length : dirtyKeys.filter((k) => (KEYS_BY_GROUP[gk] || []).includes(k)).length);

  const undoSaveAll = useUndoableSave(() => { reload(); cap.reload?.(); });
  const saveAll = () => {
    // The key list and their values are snapshotted: the user can keep editing during the
    // window, and this must write the set they pressed Save on, not whatever is dirty later.
    const batch = dirtyKeys.map((k) => [k, coerce(draft[k], KIND_OF[k])]);
    setBusy('__all__');
    undoSaveAll(async () => {
      for (const [k, value] of batch) await api.put(`/admin/settings/${k}`, { value });
    }, t('hs.savecount', `Saved ${batch.length} changes.`).replace('{n}', batch.length),
       { onSettled: () => setBusy(null),
         errorFor: (x) => x.data?.error === 'exceeds_disk' ? t('hs.exceedsdisk', `Exceeds the real disk capacity (${x.data.diskGB} GB max).`).replace('{n}', x.data.diskGB) : (x.data?.error || t('common.failed', 'Failed.')) });
  };
  // What is on screen: the search wins over the tab, `all` shows every group, otherwise the
  // one tab. A group whose keys all fail the search is dropped entirely rather than left as
  // an empty header — an empty group reads as "nothing configured here".
  const needle = q.trim().toLowerCase();
  const searching = needle.length > 0;
  const matches = (k, label, desc) =>
    k.toLowerCase().includes(needle)
    || t(`hs.l.${k}`, label).toLowerCase().includes(needle)
    || t(`hs.d.${k}`, desc).toLowerCase().includes(needle);
  const visibleGroups = SETTINGS_GROUPS
    .filter((g) => searching || tab === 'all' || g.gk === tab)
    .map((g) => (searching ? { ...g, keys: g.keys.filter(([k, label, desc]) => matches(k, label, desc)) } : g))
    .filter((g) => g.keys.length > 0);
  const matchCount = visibleGroups.reduce((n, g) => n + g.keys.length, 0);
  // The cards are not key rows, so the search cannot filter them; they step aside while it
  // is running rather than sitting under a result count that does not describe them.
  const showCards = (gk) => !searching && (tab === gk || tab === 'all');

  const c = cap.data?.capacity;
  const tempPct = c?.tempMarginGB ? Math.min(100, (c.tempUsedGB / c.tempMarginGB) * 100) : 0;
  return (
    <div className="mt-10">
      {/* Plain header — consistent with every other admin panel (Events, Campaigns…).
          The "Save all" pill still floats to a sticky dock at the bottom-right when
          there are unsaved edits, so pinning the header isn't needed. */}
      <div className="flex items-center justify-between mb-3 flex-wrap gap-2">
        <h2 className="font-semibold flex items-center gap-2"><Settings2 size={16} className="text-[var(--accent-ink)]" /> {t('hs.title', 'Hosting settings')}</h2>
        {/* No guide link here.
            There were two on this one screen, worded differently and pointing at two different
            entries: the house one that every admin screen now carries at the top, and this
            one. And a third kind, better than both, is already under each SETTING: a "Learn
            more" that deep-links to that setting's own paragraph. A header link to the whole
            chapter is the least useful of the three and was the one making the top of the page
            look cluttered. */}
      </div>
      {dirtyKeys.length > 0 && (
        <div className="fixed bottom-4 left-1/2 -translate-x-1/2 z-40 anim-slide">
          <Button variant="primary" disabled={busy === '__all__'} onClick={saveAll} className="shadow-lg">{busy === '__all__' ? <Spinner /> : <><CheckCheck size={15} /> {t('hs.saveall', 'Save all')} ({dirtyKeys.length})</>}</Button>
        </div>
      )}
      {/* Sub-tabs, not one scroll.
          Eight collapsible groups plus the capacity visuals made this the longest screen in the
          admin: finding "how big can a blog post be" meant scrolling past every storage gauge,
          the temp-margin manager and the Discord cap. One group at a time now, and STORAGE &
          CAPACITY is its own tab holding every gauge and every ceiling — the question "what is
          using the disk, and what stops it" has one place to be asked. The strip scrolls
          sideways rather than wrapping, because the admin column is narrow. */}
      {/* The same underlined strip Analytics, Web Vitals and the Plugins screen use. This was
          the one sub-tab bar in the admin wearing rounded pills — so the only screen where
          "where am I" is answered by a different shape, and the pills read as filter chips
          (something you toggle) rather than as tabs (somewhere you are). The unsaved dot
          stays: it is the one thing this strip has that the others do not need. */}
      {/* On a phone the strip was ten tabs behind a sideways swipe with nothing saying how
          many were off-screen, so the tabs past "Pricing" were effectively invisible. A
          native select shows the whole list at once, in the picker the phone already has,
          and marks which tabs hold unsaved edits. */}
      {/* One dropdown at every width now, not a phone select beside a desktop strip. Even on a
          desktop the strip was ten tabs behind a sideways scroll in a column this narrow. The
          app's own Dropdown (opaque `--bg-solid` menu, keyboard-driven) shows the whole list
          at once with its icons, and names the tabs that hold unsaved edits. State and the
          ?hs= URL behaviour are untouched \u2014 only the control changed. */}
      <div className="mb-4 flex items-center gap-2 flex-wrap">
        <span className="text-xs text-[var(--muted)]">{t('hs.tab.pick', 'Settings section')}</span>
        <Dropdown value={tab} onChange={(v) => setTab(v)} className="min-w-[240px]"
          options={HS_TABS.map((tb) => ({
            value: tb.gk,
            icon: <tb.icon size={14} className={tab === tb.gk ? 'text-[var(--accent-ink)]' : 'text-[var(--faint)]'} />,
            label: (
              <span className="inline-flex items-center gap-1.5">
                {t(`hs.g.${tb.gk}`, tb.title)}
                {dirtyIn(tb.gk) > 0 && <span className="w-1.5 h-1.5 rounded-full bg-[var(--primary)]" title={t('hs.tab.dirty', 'unsaved changes in this tab')} />}
                {dirtyIn(tb.gk) > 0 && <span className="text-[10px] text-[var(--faint)]">{t('hs.tab.dirtyn', '{n} unsaved').replace('{n}', dirtyIn(tb.gk))}</span>}
              </span>
            ),
          }))} />
      </div>
      {/* One box, every tab. Matches the label, the description AND the setting key, because
          an admin who arrived from the API or a support thread has the key and not the
          label. While it has text, the tabs stop deciding what is on screen. */}
      <div className="mb-4 relative">
        <Search size={14} className="absolute start-3 top-1/2 -translate-y-1/2 text-[var(--faint)] pointer-events-none" />
        <Input className="!ps-9" value={q} onChange={(e) => setQ(e.target.value)}
          placeholder={t('hs.search', 'Search every setting \u2014 name, description or key')} />
        {q && <button type="button" onClick={() => setQ('')} className="absolute end-2 top-1/2 -translate-y-1/2 p-1 text-[var(--faint)] hover:text-[var(--text)]" aria-label={t('common.clear', 'Clear')}><X size={14} /></button>}
      </div>
      {searching && (
        <div className="text-xs text-[var(--muted)] mb-3">
          {matchCount === 0
            ? t('hs.search.none', 'No setting matches \u201c{q}\u201d.').replace('{q}', q)
            : t('hs.search.n', '{n} setting(s) across {g} section(s).').replace('{n}', matchCount).replace('{g}', visibleGroups.length)}
        </div>
      )}
      {showCards('capacity') && (<>
      {/* At-a-glance stacked bar of the WHOLE Total capacity — where every GB goes
          (hosting quotas, approved submissions, temp margin, reserved, free) plus the
          separately-tracked free-plan pool. */}
      {c && (() => {
        const total = c.totalGB || 0;
        const seg = (gb, color, label) => ({ gb: Math.max(0, Number(gb) || 0), color, label });
        const segs = [
          seg(c.hostingAllocatedGB, 'var(--primary)', t('hs.seg.hosting', 'Hosting quotas')),
          seg(c.submissionsPublishedGB, '#8b5cf6', t('hs.seg.subs', 'Approved submissions')),
          seg(c.tempUsedGB, '#f59e0b', t('hs.seg.tempuse', 'Temp (in use)')),
          seg((c.tempMarginGB || 0) - (c.tempUsedGB || 0), 'rgba(245,158,11,0.35)', t('hs.seg.tempres', 'Temp (reserved)')),
          seg(c.reservedGB, 'var(--faint)', t('hs.seg.reserved', 'Reserved margin')),
        ];
        const used = segs.reduce((a, s) => a + s.gb, 0);
        const all = [...segs, seg(Math.max(0, total - used), 'var(--surface-2)', t('hs.seg.free', 'Free'))];
        return (
          <Card className="p-4 mb-3">
            <div className="flex items-center justify-between text-sm mb-2 flex-wrap gap-2">
              <span className="flex items-center gap-2 font-medium"><HardDrive size={15} className="text-[var(--accent-ink)]" /> {t('hs.totalcap', 'Total capacity')}</span>
              <span className="text-xs text-[var(--muted)] tabular-nums">{t('hs.capused', '{used} / {total} GB used · {free} GB free').replace('{used}', used.toFixed(1)).replace('{total}', total).replace('{free}', Math.max(0, total - used).toFixed(1))}</span>
            </div>
            <div className="flex h-3.5 rounded-full overflow-hidden bg-[var(--surface-2)] border border-[var(--line)]">
              {total > 0 && all.map((s, i) => s.gb > 0.001 && <div key={i} title={`${s.label}: ${s.gb.toFixed(2)} GB`} style={{ width: `${(s.gb / total) * 100}%`, background: s.color }} />)}
            </div>
            <div className="flex flex-wrap gap-x-4 gap-y-1 mt-2.5 text-[11px]">
              {all.filter((s) => s.gb > 0.001).map((s, i) => (
                <span key={i} className="flex items-center gap-1.5 text-[var(--muted)]"><span className="w-2.5 h-2.5 rounded-sm shrink-0" style={{ background: s.color }} /> {s.label} <b className="text-[var(--text)] tabular-nums">{s.gb.toFixed(1)}G</b></span>
              ))}
            </div>
            {c.diskFreeGB != null && <div className="text-[11px] text-[var(--faint)] mt-1.5">{t('hs.realdisk', 'Real disk:')} <b className="text-[var(--text)]">{t('hs.gbfree', '{n} GB free').replace('{n}', c.diskFreeGB.toFixed(0))}</b> / {t('hs.gbtotal', '{n} GB total').replace('{n}', c.diskTotalGB?.toFixed(0))}.</div>}
            {c.freeTierCapEnabled && c.freeTierCapGB > 0 && (
              <div className="mt-3 pt-3 border-t border-[var(--line)]">
                <button type="button" onClick={() => setFreePoolOpen(true)} className="w-full text-start group" title={t('hs.freepool.view', 'See what fills this pool')}>
                  <div className="flex items-center justify-between text-xs mb-1"><span className="text-[var(--muted)] flex items-center gap-1.5 group-hover:text-[var(--text)]"><Gift size={12} className="text-success" /> {t('hs.freepool', 'Free-plan pool (separate)')} <ArrowUpRight size={11} className="opacity-40 group-hover:opacity-100" /></span><span className="tabular-nums font-medium">{(c.freeTierUsedGB || 0).toFixed(1)} / {c.freeTierCapGB} GB</span></div>
                  <div className="h-2 rounded-full bg-[var(--surface-2)] overflow-hidden"><div className="h-full bg-success" style={{ width: `${Math.min(100, ((c.freeTierUsedGB || 0) / c.freeTierCapGB) * 100)}%` }} /></div>
                </button>
              </div>
            )}
            {/* BMM telemetry storage — used vs. the admin-set allocation (separate DB). */}
            {c.telemetryUsedGB != null && (() => {
              const alloc = c.telemetryLimitGB || 0;
              const pct = alloc > 0 ? Math.min(100, (c.telemetryUsedGB / alloc) * 100) : 0;
              return (
                <div className="mt-3 pt-3 border-t border-[var(--line)]">
                  <div className="flex items-center justify-between text-xs mb-1">
                    <span className="text-[var(--muted)] flex items-center gap-1.5"><Gauge size={12} className="text-info" /> {t('hs.telestore', 'BMM telemetry storage')} {alloc > 0 ? '' : <span className="text-[var(--faint)]">{t('hs.nolimit', '(no limit set)')}</span>}</span>
                    <span className="tabular-nums font-medium">{c.telemetryUsedGB.toFixed(2)}{alloc > 0 ? ` / ${alloc} GB` : ` ${t('hs.gbused', 'GB used')}`}</span>
                  </div>
                  {alloc > 0 && <div className="h-2 rounded-full bg-[var(--surface-2)] overflow-hidden"><div className={`h-full ${pct > 90 ? 'bg-error' : 'bg-info'}`} style={{ width: `${pct}%` }} /></div>}
                </div>
              );
            })()}
          </Card>
        );
      })()}
      <TelemetryConfigCard />
      <FreePoolBreakdown open={freePoolOpen} onClose={() => setFreePoolOpen(false)} />
      {/* Temp submissions margin — live usage. Uploads (.bmmplugin / .bmmtheme / app
          payloads) are refused once this is full, until moderation clears space. */}
      {c && (
        <Card className="p-4 mb-3">
          <div className="flex items-center justify-between text-sm mb-1.5">
            <span className="flex items-center gap-2 text-[var(--muted)]"><Upload size={14} className="text-[var(--accent-ink)]" /> {t('hs.tempstore', 'Temp storage (submissions)')}</span>
            <span className="font-semibold tabular-nums">{(c.tempUsedGB ?? 0).toFixed(2)} / {c.tempMarginGB ?? 0} GB</span>
          </div>
          <div className="h-2 rounded-full bg-[var(--surface-2)] overflow-hidden flex">
            <div className={`h-full ${tempPct > 90 ? 'bg-error' : 'bg-gradient-to-r from-brand to-brand-2'}`} style={{ width: `${(c.tempMarginGB ? Math.min(100, ((c.tempPendingGB || 0) / c.tempMarginGB) * 100) : 0)}%` }} title={t('hs.temppending', 'Pending review')} />
            <div className="h-full bg-error-bg" style={{ width: `${(c.tempMarginGB ? Math.min(100, ((c.tempRejectedGB || 0) / c.tempMarginGB) * 100) : 0)}%` }} title={t('hs.temprejected', 'Rejected (in grace)')} />
          </div>
          <div className="flex items-center justify-between gap-2 mt-1.5 flex-wrap">
            <div className="text-[11px] text-[var(--faint)]">{t('hs.tempnote', 'Submitted files (.bmmplugin, .bmmtheme, app payloads) live here until moderation. When full, new submission uploads are refused.')}
              {(c.tempRejectedGB || 0) > 0.001 && <span className="text-error"> · {t('hs.temprej', '{n} GB held by rejected files in grace').replace('{n}', (c.tempRejectedGB || 0).toFixed(2))}</span>}</div>
            <Button size="sm" variant="ghost" onClick={() => setTempOpen(true)}><Files size={13} /> {t('hs.tempmanage', 'Manage')}</Button>
          </div>
        </Card>
      )}
      <TempStorageManager open={tempOpen} onClose={() => setTempOpen(false)} onChange={() => cap.reload?.()} />
      {/* Discord bot member-storage cap — same screen as every other service cap, even
          though it lives in the bot.config blob rather than a flat AdminSetting. */}
      <DiscordStorageCapCard />
      {/* A storage ceiling like every other one on this tab. It used to render under all
          eight tabs, which is most of why this screen felt long. */}
      <FeedbackStorageCard />
      </>)}
      <div className="space-y-5">
        {visibleGroups.map((g) => {
          // Always open. The collapse was how you skipped past a group in a single long
          // scroll; the tab already did the skipping, and a persisted `collapsed` entry would
          // have opened a freshly-picked tab onto nothing but its own header.
          const isOpen = true;
          return (
          <div key={g.title} className="card rounded-2xl overflow-hidden">
            <div className="w-full flex items-center gap-2.5 px-4 py-3 panel border-b border-[var(--line)] text-start">
              <span className="grid place-items-center w-8 h-8 rounded-lg tint-primary border b-primary shrink-0"><g.icon size={15} className="text-[var(--accent-ink)]" /></span>
              <div className="min-w-0 flex-1"><div className="text-sm font-semibold">{t(`hs.g.${g.gk}`, g.title)}</div>{GROUP_DESC[g.title] && <div className="text-[11px] text-[var(--faint)]">{t(`hs.gd.${g.gk}`, GROUP_DESC[g.title])}</div>}</div>
              <span className="text-[10px] text-[var(--faint)] tabular-nums shrink-0">{g.keys.length}</span>
            </div>
            {isOpen && (
            <div className="p-3 grid md:grid-cols-2 gap-3">
              {g.keys.map(([k, label, desc, kind, nativeUnit]) => {
                const L = t(`hs.l.${k}`, label);
                const D = t(`hs.d.${k}`, desc);
                const saveLabel = t('hs.save', 'Save');
                return (
                <Card key={k} className="p-4">
                  {kind === 'bool' ? (
                    <div className="flex items-center justify-between gap-3">
                      <label className="flex items-center gap-2.5 text-sm cursor-pointer flex-1"><input type="checkbox" checked={draft[k] !== false && draft[k] !== 'false' && !!draft[k]} onChange={(e) => setDraft({ ...draft, [k]: e.target.checked })} /> <span className="font-medium">{L}</span></label>
                      <Button size="sm" disabled={busy === k} onClick={() => save(k, kind)}>{busy === k ? <Spinner /> : saveLabel}</Button>
                    </div>
                  ) : kind === 'gbmb' ? (() => {
                    const curUnit = unit[k] || nativeUnit;
                    const displayValue = draft[k] !== '' && draft[k] != null ? convertUnit(Number(draft[k]), nativeUnit, curUnit) : '';
                    return (
                      <div className="flex items-end gap-2">
                        <div className="flex-1"><Field label={L}><Input type="number" value={displayValue} onChange={(e) => setDraft({ ...draft, [k]: e.target.value === '' ? '' : convertUnit(Number(e.target.value), curUnit, nativeUnit) })} /></Field></div>
                        <Select className="!w-auto !py-2.5" value={curUnit} onChange={(e) => setUnit({ ...unit, [k]: e.target.value })}><option value="MB">MB</option><option value="GB">GB</option><option value="TB">TB</option></Select>
                        <Button size="sm" disabled={busy === k} onClick={() => save(k, 'number')}>{busy === k ? <Spinner /> : saveLabel}</Button>
                      </div>
                    );
                  })() : (
                    // Text fields (SEO title/description, tag ids, tokens, image URL) were all
                    // rendered as a number input by this fallback branch — so they silently would
                    // not accept text. Honour the declared kind.
                    <div className="flex items-end gap-3">
                      <div className="flex-1"><Field label={L}><Input type={kind === 'text' ? 'text' : 'number'} value={draft[k] ?? ''} onChange={(e) => setDraft({ ...draft, [k]: e.target.value })} /></Field></div>
                      <Button size="sm" disabled={busy === k} onClick={() => save(k, kind)}>{busy === k ? <Spinner /> : saveLabel}</Button>
                    </div>
                  )}
                  {/* The gist stays on the control; the full explanation lives in the Admin guide,
                      so a setting reads as a control, not a manual (clamp + a "learn more" link). */}
                  <div className="text-[11px] text-[var(--faint)] mt-1.5 line-clamp-2">{D}</div>
                  <Link to={`?s=guide&g=hostingsettings&k=${encodeURIComponent(k)}`} className="text-[11px] text-[var(--accent-ink)] hover:underline inline-flex items-center gap-0.5 mt-1">{t('hs.more', 'Learn more')} <ChevronRight size={10} /></Link>
                  {k === 'hosting.totalCapacityGB' && c?.diskTotalGB != null && <div className="text-[11px] text-warning mt-1">{t('hs.realdiskcap', "Real disk: {free} GB free / {total} GB total, can't be set above this.").replace('{free}', c.diskFreeGB.toFixed(0)).replace('{total}', c.diskTotalGB.toFixed(0))}</div>}
                </Card>
                );
              })}
            </div>
            )}
          </div>
          );
        })}
      </div>
      {/* Not rows in the table above: these are LISTS an admin builds and tools an admin
          runs, so they cannot be key/label/type entries like the rest. They belong to a tab
          all the same \u2014 rendering them under every one is what made picking a two-field
          group still mean scrolling past the sitemap scanner. */}
      {showCards('seo') && (
        <div className="mt-8 space-y-4">
          <div className="text-[11px] font-semibold uppercase tracking-wider text-[var(--faint)]">{t('hs.seo.section2', 'Search engines & indexing')}</div>
          <SeoHealthCard />
          <SitemapCard />
          <SeoPagesCard />
        </div>
      )}
      {showCards('tools') && (
        <div className="mt-8 space-y-4">
          <div className="text-[11px] font-semibold uppercase tracking-wider text-[var(--faint)]">{t('hs.tools.section', 'Maintenance & demo data')}</div>
          <ConfigTransferCard />
          <SeedGeneratorCard />
        </div>
      )}
    </div>
  );
}



